    /* ============================================================
     * BASE -> WORLD
     * ============================================================ */

    async function baseToWorld(
        options = {}
    ) {

        if (
            detect().state ===
            STATE.WORLD
        ) {

            return {

                ok: true,

                alreadyThere:
                    true
            };
        }


        const candidates =

            collectActiveButtons()

                .map(
                    row => ({
                        ...row,

                        score:
                            scoreGoWorld(
                                row
                            )
                    })
                )

                .filter(
                    row =>
                        row.score >=
                        80
                )

                .sort(
                    (a, b) =>
                        b.score -
                        a.score
                );


        if (
            !candidates.length
        ) {

            return {

                ok: false,

                reason:
                    'WORLD 이동 버튼을 찾지 못함'
            };
        }


        const target =
            candidates[0];


        const click =
            triggerButton(
                target.node
            );


        if (
            !click.ok
        ) {

            return {

                ok: false,

                click,

                target
            };
        }


        const verified =
            await waitForState(
                STATE.WORLD,
                {
                    timeout:
                        options.timeout ??
                        12000
                }
            );


        return {

            ok:
                verified.ok,

            click,

            target: {

                node:
                    target.node.name,

                path:
                    target.path,

                score:
                    target.score
            },

            verified
        };
    }


