    /* ============================================================
     * WORLD_MINIMAP -> WORLD_MAP
     * ============================================================ */

    async function worldMinimapToWorldMap(
        options = {}
    ) {

        const current =
            detect();


        if (
            current.state ===
            STATE.WORLD_MAP
        ) {

            return {

                ok: true,

                alreadyThere:
                    true
            };
        }


        if (
            current.state !==
            STATE.WORLD_MINIMAP
        ) {

            return {

                ok: false,

                reason:
                    '현재 상태가 WORLD_MINIMAP이 아님',

                current
            };
        }


        const button =
            findDirectPath(
                PATH.WORLD_MAP
            );


        if (
            !button ||
            !isActive(
                button
            )
        ) {

            return {

                ok: false,

                reason:
                    'worldmapBtn을 찾지 못함'
            };
        }


        const click =
            triggerButton(
                button
            );


        if (
            !click.ok
        ) {

            return {

                ok: false,

                click
            };
        }


        const verified =
            await waitForState(
                STATE.WORLD_MAP,
                {
                    timeout:
                        options.timeout ??
                        10000
                }
            );


        return {

            ok:
                verified.ok,

            click,

            verified
        };
    }


    /* ============================================================
     * WORLD -> WORLD_MAP
     * ============================================================ */

    async function worldToWorldMap(
        options = {}
    ) {

        let current =
            detect();


        if (
            current.state ===
            STATE.WORLD_MAP
        ) {

            return {

                ok: true,

                alreadyThere:
                    true
            };
        }


        if (
            current.state ===
            STATE.WORLD
        ) {

            const step1 =
                await worldToWorldMinimap(
                    options
                );


            if (
                !step1.ok
            ) {

                return {

                    ok: false,

                    stage:
                        'WORLD_TO_WORLD_MINIMAP',

                    detail:
                        step1
                };
            }
        }


        current =
            detect();


        if (
            current.state ===
            STATE.WORLD_MINIMAP
        ) {

            const step2 =
                await worldMinimapToWorldMap(
                    options
                );


            return step2;
        }


        return {

            ok: false,

            reason:
                'WORLD_MAP 이동 실패',

            current:
                detect()
        };
    }


    /* ============================================================
     * 뒤로가기 후보 찾기
     * ============================================================ */

    function findBackCandidates(
        root,
        options = {}
    ) {

        if (!root)
            return [];


        const candidates =
            [];


        walk(
            root,
            node => {

                if (
                    !isActive(node)
                )
                    return;


                let button =
                    null;


                try {

                    button =
                        node.getComponent?.(
                            cc.Button
                        );

                } catch {}


                if (!button)
                    return;


                const handlers =
                    [];


                for (
                    const event
                    of button.clickEvents || []
                ) {

                    handlers.push({

                        event,

                        component:
                            String(
                                event?.component ||
                                ''
                            ),

                        handler:
                            String(
                                event?.handler ||
                                ''
                            ),

                        targetName:
                            String(
                                event
                                    ?.target
                                    ?.name ||
                                ''
                            )
                    });
                }


                const text =

                    [
                        node.name,
                        nodePath(node),

                        ...handlers.map(
                            h =>
                                `${h.component} ${h.handler} ${h.targetName}`
                        )
                    ]

                        .join(' ')

                        .replace(
                            /[^a-zA-Z0-9가-힣]/g,
                            ''
                        )

                        .toLowerCase();


                let score = 0;


                if (
                    text.includes(
                        'btnback'
                    )
                )
                    score += 10000;


                if (
                    text.includes(
                        'backbtn'
                    )
                )
                    score += 9500;


                if (
                    text.includes(
                        'onclickback'
                    )
                )
                    score += 9000;


                if (
                    text.includes(
                        'onbtnback'
                    )
                )
                    score += 9000;


                if (
                    text.includes(
                        'onback'
                    )
                )
                    score += 8500;


                if (
                    text.includes(
                        'back'
                    )
                )
                    score += 7000;


                if (
                    text.includes(
                        'btnclose'
                    )
                )
                    score += 8000;


                if (
                    text.includes(
                        'closebtn'
                    )
                )
                    score += 7500;


                if (
                    text.includes(
                        'onclickclose'
                    )
                )
                    score += 7300;


                if (
                    text.includes(
                        'onbtnclose'
                    )
                )
                    score += 7300;


                if (
                    text.includes(
                        'onclose'
                    )
                )
                    score += 7000;


                if (
                    text.includes(
                        'close'
                    )
                )
                    score += 5000;


                if (
                    text.includes(
                        'return'
                    )
                )
                    score += 4500;


                /*
                 * 제외
                 */

                if (
                    text.includes(
                        'worldmapbtn'
                    )
                )
                    score -= 30000;


                if (
                    text.includes(
                        'btnsevermap'
                    )
                )
                    score -= 30000;


                if (
                    text.includes(
                        'servermap'
                    )
                )
                    score -= 20000;


                if (
                    text.includes(
                        'transfer'
                    )
                )
                    score -= 10000;


                if (
                    text.includes(
                        'rank'
                    )
                )
                    score -= 8000;


                if (
                    score > 0
                ) {

                    candidates.push({

                        node,

                        button,

                        handlers,

                        score,

                        path:
                            nodePath(node),

                        text
                    });
                }
            }
        );


        candidates.sort(
            (a, b) =>
                b.score -
                a.score
        );


        return candidates;
    }


    /* ============================================================
     * WORLD_MAP -> WORLD_MINIMAP
     * ============================================================ */

    async function worldMapToWorldMinimap(
        options = {}
    ) {

        let current =
            detect();


        if (
            current.state ===
            STATE.WORLD_MINIMAP
        ) {

            return {

                ok: true,

                alreadyThere:
                    true
            };
        }


        if (
            current.state !==
            STATE.WORLD_MAP
        ) {

            return {

                ok: false,

                reason:
                    '현재 WORLD_MAP 상태가 아님',

                current
            };
        }


        const panel =
            findComponent(
                'WorldServerListPanel',
                true
            );


        const panelNode =

            panel?.node

            ||

            findNodeByName(
                'WorldServerListPanel',
                true
            );


        if (!panelNode) {

            return {

                ok: false,

                reason:
                    'WorldServerListPanel 없음'
            };
        }


        /*
         * 버튼 우선
         */

        const candidates =
            findBackCandidates(
                panelNode
            );


        console.table(
            candidates.map(
                (row, index) => ({

                    index,

                    score:
                        row.score,

                    node:
                        row.node.name,

                    path:
                        row.path,

                    handlers:
                        row.handlers
                            .map(
                                h =>
                                    `${h.component}.${h.handler}`
                            )
                            .join(' | ')
                })
            )
        );


        for (
            const candidate
            of candidates
        ) {

            const click =
                triggerButton(
                    candidate.node
                );


            if (
                !click.ok
            )
                continue;


            await sleep(
                350
            );


            current =
                detect();


            if (
                current.state ===
                STATE.WORLD_MINIMAP
            ) {

                return {

                    ok: true,

                    method:
                        'button',

                    target: {

                        node:
                            candidate.node.name,

                        path:
                            candidate.path,

                        score:
                            candidate.score
                    },

                    detected:
                        current
                };
            }


            if (
                current.state ===
                STATE.WORLD
            ) {

                return {

                    ok: true,

                    directWorld:
                        true,

                    method:
                        'button',

                    detected:
                        current
                };
            }
        }


        /*
         * component method fallback
         */

        if (panel) {

            const preferred = [

                'onClickBack',
                'onBtnBack',
                'onBack',
                'back',

                'onClickClose',
                'onBtnClose',
                'onClose',
                'close',

                'closePanel',
                'hide'
            ];


            for (
                const methodName
                of preferred
            ) {

                if (
                    typeof panel[
                        methodName
                    ] !==
                    'function'
                )
                    continue;


                try {

                    panel[
                        methodName
                    ]();


                    await sleep(
                        350
                    );


                    current =
                        detect();


                    if (
                        current.state ===
                        STATE.WORLD_MINIMAP
                    ) {

                        return {

                            ok: true,

                            method:
                                `component.${methodName}`,

                            detected:
                                current
                        };
                    }


                    if (
                        current.state ===
                        STATE.WORLD
                    ) {

                        return {

                            ok: true,

                            directWorld:
                                true,

                            method:
                                `component.${methodName}`,

                            detected:
                                current
                        };
                    }

                } catch (
                    error
                ) {

                    console.warn(
                        `[NAV] ${methodName} 실패`,
                        error
                    );
                }
            }
        }


        return {

            ok: false,

            reason:
                'WORLD_MAP 뒤로가기 실패',

            current:
                detect()
        };
    }


    /* ============================================================
     * WORLD_MINIMAP -> WORLD
     * ============================================================ */

    async function worldMinimapToWorld(
        options = {}
    ) {

        let current =
            detect();


        if (
            current.state ===
            STATE.WORLD
        ) {

            return {

                ok: true,

                alreadyThere:
                    true
            };
        }


        if (
            current.state !==
            STATE.WORLD_MINIMAP
        ) {

            return {

                ok: false,

                reason:
                    '현재 WORLD_MINIMAP 상태가 아님',

                current
            };
        }


        const minimapRoot =

            findNodeByName(
                'NWorldMinimap3D',
                true
            )

            ||

            findDirectPath(
                'NWorldMap/UICanvas/PopLayer/UIFrameNone/CONTENT/NWorldMinimap3D'
            );


        if (!minimapRoot) {

            return {

                ok: false,

                reason:
                    'NWorldMinimap3D 찾지 못함'
            };
        }


        const candidates =
            findBackCandidates(
                minimapRoot
            );


        console.table(
            candidates.map(
                (row, index) => ({

                    index,

                    score:
                        row.score,

                    node:
                        row.node.name,

                    path:
                        row.path,

                    handlers:
                        row.handlers
                            .map(
                                h =>
                                    `${h.component}.${h.handler}`
                            )
                            .join(' | ')
                })
            )
        );


        for (
            const candidate
            of candidates
        ) {

            const click =
                triggerButton(
                    candidate.node
                );


            if (
                !click.ok
            )
                continue;


            const verified =
                await waitForState(
                    STATE.WORLD,
                    {
                        timeout:
                            options.timeout ??
                            5000,

                        stable:
                            2
                    }
                );


            if (
                verified.ok
            ) {

                return {

                    ok: true,

                    target: {

                        node:
                            candidate.node.name,

                        path:
                            candidate.path,

                        score:
                            candidate.score
                    },

                    click,

                    verified
                };
            }
        }


        /*
         * 상위 PopLayer/UIFrame close 버튼까지 확인
         */

        let parent =
            minimapRoot.parent;


        for (
            let depth = 0;
            depth < 5 &&
            parent;
            depth++
        ) {

            const parentCandidates =
                findBackCandidates(
                    parent
                );


            for (
                const candidate
                of parentCandidates
            ) {

                /*
                 * worldmapBtn 제외
                 */

                if (
                    candidate.node.name ===
                    'worldmapBtn'
                )
                    continue;


                const click =
                    triggerButton(
                        candidate.node
                    );


                if (
                    !click.ok
                )
                    continue;


                const verified =
                    await waitForState(
                        STATE.WORLD,
                        {
                            timeout:
                                3000,

                            stable:
                                2
                        }
                    );


                if (
                    verified.ok
                ) {

                    return {

                        ok: true,

                        method:
                            'parent-close',

                        target: {

                            node:
                                candidate.node.name,

                            path:
                                candidate.path,

                            score:
                                candidate.score
                        },

                        verified
                    };
                }
            }


            parent =
                parent.parent;
        }


        return {

            ok: false,

            reason:
                'WORLD_MINIMAP 뒤로가기 실패',

            candidates:
                candidates
                    .slice(0, 15)
                    .map(
                        row => ({

                            node:
                                row.node.name,

                            path:
                                row.path,

                            score:
                                row.score,

                            handlers:
                                row.handlers
                                    .map(
                                        h =>
                                            `${h.component}.${h.handler}`
                                    )
                        })
                    )
        };
    }


    /* ============================================================
     * WORLD_MAP -> WORLD
     *
     * 뒤로 두 번
     * ============================================================ */

    async function worldMapToWorld(
        options = {}
    ) {

        let current =
            detect();


        if (
            current.state ===
            STATE.WORLD
        ) {

            return {

                ok: true,

                alreadyThere:
                    true
            };
        }


        /*
         * 1단계
         * WORLD_MAP -> WORLD_MINIMAP
         */

        if (
            current.state ===
            STATE.WORLD_MAP
        ) {

            const step1 =
                await worldMapToWorldMinimap(
                    options
                );


            if (
                !step1.ok
            ) {

                return {

                    ok: false,

                    stage:
                        'WORLD_MAP_TO_WORLD_MINIMAP',

                    detail:
                        step1
                };
            }


            current =
                detect();


            /*
             * 한번에 WORLD까지 빠진 경우
             */

            if (
                current.state ===
                STATE.WORLD
            ) {

                return {

                    ok: true,

                    direct:
                        true,

                    step1
                };
            }
        }


        /*
         * 2단계
         * WORLD_MINIMAP -> WORLD
         */

        if (
            current.state ===
            STATE.WORLD_MINIMAP
        ) {

            const step2 =
                await worldMinimapToWorld(
                    options
                );


            return {

                ok:
                    step2.ok,

                step2
            };
        }


        return {

            ok: false,

            reason:
                'WORLD_MAP → WORLD 전환 중 상태 이상',

            current:
                detect()
        };
    }


    /* ============================================================
     * goto
     * ============================================================ */

    async function goto(
        target,
        options = {}
    ) {

        target =
            String(
                target || ''
            ).toUpperCase();


        let current =
            detect();


        console.log(
            '[NAV]',
            current.state,
            '→',
            target
        );


        if (
            current.state ===
            target
        ) {

            return {

                ok: true,

                alreadyThere:
                    true,

                state:
                    target
            };
        }


        /* ========================================================
         * TARGET = WORLD_MAP
         * ======================================================== */

        if (
            target ===
            STATE.WORLD_MAP
        ) {

            /*
             * BASE -> WORLD
             */

            if (
                current.state ===
                STATE.BASE
            ) {

                const step =
                    await baseToWorld(
                        options
                    );


                if (
                    !step.ok
                ) {

                    return {

                        ok: false,

                        stage:
                            'BASE_TO_WORLD',

                        detail:
                            step
                    };
                }


                current =
                    detect();
            }


            /*
             * WORLD -> WORLD_MINIMAP
             */

            if (
                current.state ===
                STATE.WORLD
            ) {

                const step =
                    await worldToWorldMinimap(
                        options
                    );


                if (
                    !step.ok
                ) {

                    return {

                        ok: false,

                        stage:
                            'WORLD_TO_WORLD_MINIMAP',

                        detail:
                            step
                    };
                }


                current =
                    detect();
            }


            /*
             * WORLD_MINIMAP -> WORLD_MAP
             */

            if (
                current.state ===
                STATE.WORLD_MINIMAP
            ) {

                return await worldMinimapToWorldMap(
                    options
                );
            }
        }


        /* ========================================================
         * TARGET = WORLD
         * ======================================================== */

        if (
            target ===
            STATE.WORLD
        ) {

            /*
             * BASE -> WORLD
             */

            if (
                current.state ===
                STATE.BASE
            ) {

                return await baseToWorld(
                    options
                );
            }


            /*
             * WORLD_MINIMAP -> WORLD
             */

            if (
                current.state ===
                STATE.WORLD_MINIMAP
            ) {

                return await worldMinimapToWorld(
                    options
                );
            }


            /*
             * WORLD_MAP -> WORLD_MINIMAP -> WORLD
             */

            if (
                current.state ===
                STATE.WORLD_MAP
            ) {

                return await worldMapToWorld(
                    options
                );
            }
        }


        /* ========================================================
         * TARGET = BASE
         * ======================================================== */

        if (
            target ===
            STATE.BASE
        ) {

            /*
             * WORLD_MAP -> WORLD
             */

            if (
                current.state ===
                STATE.WORLD_MAP
            ) {

                const step =
                    await worldMapToWorld(
                        options
                    );


                if (
                    !step.ok
                ) {

                    return {

                        ok: false,

                        stage:
                            'WORLD_MAP_TO_WORLD',

                        detail:
                            step
                    };
                }


                current =
                    detect();
            }


            /*
             * WORLD_MINIMAP -> WORLD
             */

            if (
                current.state ===
                STATE.WORLD_MINIMAP
            ) {

                const step =
                    await worldMinimapToWorld(
                        options
                    );


                if (
                    !step.ok
                ) {

                    return {

                        ok: false,

                        stage:
                            'WORLD_MINIMAP_TO_WORLD',

                        detail:
                            step
                    };
                }


                current =
                    detect();
            }


            /*
             * WORLD -> BASE
             */

            if (
                current.state ===
                STATE.WORLD
            ) {

                return await worldToBase(
                    options
                );
            }
        }


        return {

            ok: false,

            reason:
                '지원되지 않는 상태 전환',

            from:
                current.state,

            to:
                target,

            current
        };
    }


    /* ============================================================
     * 진단
     * ============================================================ */

    function diagnose() {

        const detected =
            detect();


        const signals =
            getSignals();


        const result = {

            version:
                VERSION,

            detected,

            signals:
                simplifySignals(
                    signals
                ),

            paths: {

                minimap: {

                    expected:
                        PATH.MINIMAP,

                    found:
                        !!signals.minimapButtonNode,

                    active:
                        signals.minimapButton,

                    actual:
                        signals.minimapButtonNode
                            ? nodePath(
                                signals.minimapButtonNode
                            )
                            : null
                },


                worldmap: {

                    expected:
                        PATH.WORLD_MAP,

                    found:
                        !!signals.worldmapButtonNode,

                    active:
                        signals.worldmapButton,

                    actual:
                        signals.worldmapButtonNode
                            ? nodePath(
                                signals.worldmapButtonNode
                            )
                            : null
                },


                minimapRoot: {

                    found:
                        !!signals.minimapRootNode,

                    active:
                        signals.minimapRoot,

                    actual:
                        signals.minimapRootNode
                            ? nodePath(
                                signals.minimapRootNode
                            )
                            : null
                },


                serverPanel: {

                    found:
                        !!signals.serverPanelNode,

                    active:
                        signals.serverPanel,

                    actual:
                        signals.serverPanelNode
                            ? nodePath(
                                signals.serverPanelNode
                            )
                            : null
                }
            }
        };


        console.log(
            '[TOPWAR_NAV diagnose]',
            result
        );


        console.table([

            {
                item:
                    'MinimapBtn',

                found:
                    result.paths
                        .minimap
                        .found,

                active:
                    result.paths
                        .minimap
                        .active,

                path:
                    result.paths
                        .minimap
                        .actual
            },

            {
                item:
                    'NWorldMinimap3D',

                found:
                    result.paths
                        .minimapRoot
                        .found,

                active:
                    result.paths
                        .minimapRoot
                        .active,

                path:
                    result.paths
                        .minimapRoot
                        .actual
            },

            {
                item:
                    'worldmapBtn',

                found:
                    result.paths
                        .worldmap
                        .found,

                active:
                    result.paths
                        .worldmap
                        .active,

                path:
                    result.paths
                        .worldmap
                        .actual
            },

            {
                item:
                    'WorldServerListPanel',

                found:
                    result.paths
                        .serverPanel
                        .found,

                active:
                    result.paths
                        .serverPanel
                        .active,

                path:
                    result.paths
                        .serverPanel
                        .actual
            }

        ]);


        return result;
    }


