    /* ============================================================
     * UI helper
     * ============================================================ */

    function stateColor(state) {

        switch (state) {

            case STATE.BASE:

                return '#42a5f5';


            case STATE.WORLD:

                return '#66bb6a';


            case STATE.WORLD_MINIMAP:

                return '#ab47bc';


            case STATE.WORLD_MAP:

                return '#ffa726';


            default:

                return '#888';
        }
    }


    function log(
        message,
        object
    ) {

        const entry = {
            time:
                Date.now(),

            message:
                String(
                    message ?? ''
                ),

            data:
                object
        };


        runtimeLogs.unshift(
            entry
        );


        if (
            runtimeLogs.length >
            MAX_RUNTIME_LOGS
        ) {

            runtimeLogs.length =
                MAX_RUNTIME_LOGS;
        }


        console.log(
            '[TOPWAR_NAV]',
            message,
            object ?? ''
        );


        return entry;
    }


    function refreshUnsafe() {

        const current =
            detect();


        stateElement.textContent =

            moving

                ? `${current.state} · 이동중`

                : current.state;


        reasonElement.textContent =
            current.reason;


        dotElement.style.background =
            stateColor(
                current.state
            );


        /*
         * WORLD_MINIMAP은
         * 월드 버튼을 현재상태 처리하지 않음.
         */

        for (
            const button
            of moveButtons
        ) {

            button.classList.toggle(

                'current',

                button.dataset.target ===
                current.state
            );
        }


        return current;
    }

    function recordError(stage, error) {
        const entry = { stage, message: error?.message || String(error), stack: error?.stack };
        runtimeErrors.push(entry);
        if (runtimeErrors.length > 30) runtimeErrors.shift();
        console.error('[TOPWAR_NAV] ' + stage, error);
        log(stage + ': ' + entry.message);
        return { ok: false, reason: entry.message, stage };
    }

    function refresh() {
        try { return refreshUnsafe(); }
        catch (error) {
            if (runtimeErrors.at(-1)?.message !== error.message) recordError('화면 감지', error);
            stateElement.textContent = 'ERROR';
            reasonElement.textContent = error.message;
            return { state: STATE.UNKNOWN, reason: error.message };
        }
    }



    /* ============================================================
     * 실시간 watcher
     * ============================================================ */

    function startWatcher() {

        if (watcher) {

            clearInterval(
                watcher
            );
        }


        lastState =
            refresh().state;


        watcher =
            setInterval(
                () => {

                    if (disposed) return;
                    if (!root.isConnected) (document.body || document.documentElement).appendChild(root);
                    if (!style.isConnected) (document.head || document.documentElement).appendChild(style);

                    const current =
                        refresh();


                    if (
                        current.state !==
                        lastState
                    ) {

                        const previous =
                            lastState;


                        lastState =
                            current.state;


                        log(
                            `${previous} → ${current.state}`
                        );


                        window.dispatchEvent(

                            new CustomEvent(
                                'topwar:navigation-state-change',
                                {

                                    detail: {

                                        previous,

                                        current:
                                            current.state,

                                        detected:
                                            current,

                                        time:
                                            Date.now()
                                    }
                                }
                            )
                        );
                    }

                },

                WATCH_INTERVAL
            );
    }


    /* ============================================================
     * UI 이동
     * ============================================================ */

    async function move(target) {

        if (moving)
            return;


        moving =
            true;


        for (
            const button
            of moveButtons
        ) {

            button.disabled =
                true;
        }


        try {

            const before =
                detect();


            log(
                `${before.state} → ${target}`
            );


            const result =
                await goto(
                    target
                );


            log(

                result.ok
                    ? `${target} 이동 성공`
                    : `${target} 이동 실패`,

                result
            );


            return result;

        } catch (
            error
        ) {

            const result = {

                ok:
                    false,

                error:
                    error?.message ||
                    String(error)
            };


            log(
                '이동 오류',
                result
            );


            return result;

        } finally {

            moving =
                false;


            for (
                const button
                of moveButtons
            ) {

                button.disabled =
                    false;
            }


            refresh();
        }
    }


    /* ============================================================
     * UI Event
     * ============================================================ */

    for (
        const button
        of moveButtons
    ) {

        button.addEventListener(

            'click',

            () =>

                move(
                    button.dataset.target
                )
        );
    }


    root
        .querySelector(
            '.diagnose'
        )
        .addEventListener(
            'click',
            () => {

                const result =
                    diagnose();


                log(
                    '진단',
                    result
                );
            }
        );


    root
        .querySelector(
            '.signal'
        )
        .addEventListener(
            'click',
            () => {

                const result =
                    getSignals();


                console.log(
                    '[TOPWAR_NAV signals]',
                    result
                );


                console.table([

                    {
                        signal:
                            'MinimapBtn',

                        active:
                            result.minimapButton
                    },

                    {
                        signal:
                            'NWorldMinimap3D',

                        active:
                            result.minimapRoot
                    },

                    {
                        signal:
                            'worldmapBtn',

                        active:
                            result.worldmapButton
                    },

                    {
                        signal:
                            'WorldServerListPanel',

                        active:
                            result.serverPanel
                    },

                    {
                        signal:
                            'NWorldMap',

                        active:
                            result.nWorldMap
                    }

                ]);


                log(
                    '신호 확인',
                    simplifySignals(
                        result
                    )
                );
            }
        );


    root
        .querySelector(
            '.collapse'
        )
        .addEventListener(
            'click',
            event => {

                root.classList.toggle(
                    'collapsed'
                );


                event.target.textContent =

                    root.classList.contains(
                        'collapsed'
                    )

                        ? '+'

                        : '−';
            }
        );


    /* ============================================================
     * Drag
     * ============================================================ */

    const header =
        root.querySelector(
            '.header'
        );


    let dragging =
        false;


    let offsetX =
        0;


    let offsetY =
        0;


    header.addEventListener(
        'mousedown',
        event => {

            if (
                event.target.closest(
                    'button'
                )
            )
                return;


            dragging =
                true;


            const rect =
                root
                    .getBoundingClientRect();


            offsetX =
                event.clientX -
                rect.left;


            offsetY =
                event.clientY -
                rect.top;
        }
    );


    document.addEventListener(
        'mousemove',
        event => {

            if (
                !dragging
            )
                return;


            root.style.left =
                `${event.clientX - offsetX}px`;


            root.style.top =
                `${event.clientY - offsetY}px`;


            root.style.right =
                'auto';
        },
        { signal: uiEvents.signal }
    );


    document.addEventListener(
        'mouseup',
        () => {

            dragging =
                false;
        },
        { signal: uiEvents.signal }
    );


    /* ============================================================
     * Destroy
     * ============================================================ */

    function destroy() {
        disposed = true;
        try { stopGameMacro(); } catch {}
        try { stopGameRecorder({discard:true}); } catch {}
        uiEvents.abort();

        if (watcher) {

            clearInterval(
                watcher
            );


            watcher =
                null;
        }


        root.remove();


        style.remove();


        if (
            window.TOPWAR_NAV ===
            api
        ) {

            delete window.TOPWAR_NAV;
        }
    }


    /* ============================================================
     * Public API
     * ============================================================ */


    // Profile integration; all app/module version labels use the single VERSION value.
    const profileModule = (() => {

    /* ============================================================
     * TOPWAR_PROFILE
     *
     * TOPWAR_NAV 위에 억지로 함수를 추가하지 않고
     * 별도 모듈로 사용한다.
     *
     * 실행:
     *
     *   const data = await TOPWAR_PROFILE.collectAll();
     *
     * 결과:
     *
     *   window.TOPWAR_PROFILE_DATA
     *
     * ============================================================ */


    const VERSION = '0.9.3';


    const TAB_ORDER = [
        'toggle1',   // 기지 외관
        'toggle3',   // 대열 외관
        'toggle4',   // 기지 효과
        'toggle5',   // 이동 효과
        'toggle6',   // 행군 참여
        'toggle7',   // 수호 효과
        'toggle8',   // 영광의 장식
        'toggle10'   // 기지 오라
    ];


    const TAB_ORDER_MAP =
        new Map(
            TAB_ORDER.map(
                (name, index) => [
                    name,
                    index
                ]
            )
        );


    /* ============================================================
     * BASIC
     * ============================================================ */


    function sleep(ms) {

        return new Promise(
            resolve =>
                setTimeout(
                    resolve,
                    ms
                )
        );
    }


    function isActive(node) {

        return !!node &&
            node.active !== false &&
            node.activeInHierarchy !== false;
    }


    function nodePath(node) {

        const arr = [];

        let cur =
            node;


        while (cur) {

            arr.unshift(
                cur.name || '?'
            );

            cur =
                cur.parent;
        }


        return arr.join('/');
    }


    function walk(
        root,
        callback,
        options = {}
    ) {

        if (!root)
            return;


        const includeInactive =
            !!options.includeInactive;


        const stack =
            [root];


        while (stack.length) {

            const node =
                stack.pop();


            if (!node)
                continue;


            if (
                !includeInactive &&
                !isActive(node)
            ) {
                continue;
            }


            callback(node);


            const children =
                node.children || [];


            for (
                let i =
                    children.length - 1;

                i >= 0;

                i--
            ) {

                stack.push(
                    children[i]
                );
            }
        }
    }


    function findChildPath(
        root,
        path
    ) {

        const parts =
            String(path)
                .split('/')
                .filter(Boolean);


        let cur =
            root;


        for (
            const part
            of parts
        ) {

            if (!cur)
                return null;


            cur =
                cur.getChildByName?.(
                    part
                ) ||
                (cur.children || [])
                    .find(
                        child =>
                            child.name ===
                            part
                    ) ||
                null;
        }


        return cur;
    }


    /* ============================================================
     * TEXT
     * ============================================================ */


    function collectTexts(node) {

        const values =
            [];


        walk(
            node,
            cur => {

                try {

                    const label =
                        cur.getComponent?.(
                            cc.Label
                        );


                    const text =
                        String(
                            label?.string ??
                            ''
                        ).trim();


                    if (text) {

                        values.push(
                            text
                        );
                    }

                } catch {}


                try {

                    const rich =
                        cur.getComponent?.(
                            cc.RichText
                        );


                    const text =
                        String(
                            rich?.string ??
                            ''
                        ).trim();


                    if (text) {

                        values.push(
                            text
                        );
                    }

                } catch {}

            },
            {
                includeInactive:
                    true
            }
        );


        return [
            ...new Set(values)
        ];
    }


    function getText(node) {

        return collectTexts(node)
            .join(' / ');
    }


    /* ============================================================
     * SPRITES
     * ============================================================ */


    


    /* ============================================================
     * BUTTON HANDLERS
     * ============================================================ */


    function getButtonHandlers(node) {

        let button =
            null;


        try {

            button =
                node.getComponent?.(
                    cc.Button
                );

        } catch {}


        if (!button) {

            return [];
        }


        return (
            button.clickEvents || []
        ).map(
            event => ({

                component:
                    String(
                        event?.component ||
                        event?._componentName ||
                        ''
                    ),

                handler:
                    String(
                        event?.handler ||
                        event?._handler ||
                        ''
                    ),

                customEventData:
                    event?.customEventData ??
                    event?._customEventData ??
                    ''
            })
        );
    }


    function isSkinItemNode(node) {
        const selected = collectToggles().find(tab => tab.toggle.isChecked)?.name;
        const events = {
            toggle1: ['towerDetailNode', 'itemClickCallBack'],
            toggle3: ['armyLineSkinNode', 'itemClickCallBack'],
            toggle4: ['CityEffectCellNode', 'onSelectClick'],
            toggle5: ['TransportEffectNode', 'onItemClick'],
            toggle6: ['SkinBaseItem', 'onItemClick'],
            toggle7: ['SkinBaseItem', 'onItemClick'],
            toggle8: ['ZSWEnigmaNode', 'onItemClick'],
            toggle10: ['CastleHaloItem', 'itemClick']
        };
        const expected = events[selected];
        return !!expected && getButtonHandlers(node).some(event => event.component === expected[0] && event.handler === expected[1]);
    }


    /* ============================================================
     * COMPONENT STATE INSPECTION
     *
     * 보유 상태와 관련된 실제 필드가 존재하면 읽는다.
     * ============================================================ */


    function detectOwnership(itemNode) {
        const evidence = [];
        walk(itemNode, node => {
            if (node.name === 'notHaveNode') evidence.push({ name: node.name, path: nodePath(node), active: node.active });
        }, { includeInactive: true });
        const allTrue = evidence.length && evidence.every(row => row.active === true);
        const allFalse = evidence.length && evidence.every(row => row.active === false);
        return { owned: allTrue ? false : allFalse ? true : null,
            confidence: allTrue || allFalse ? 'HIGH' : 'UNKNOWN',
            reason: allTrue ? 'notHaveNode 활성' : allFalse ? 'notHaveNode 비활성' : '확정 근거 없음 또는 충돌', evidence };
    }


    /* ============================================================
     * PROFILE
     * ============================================================ */


    function findProfileRoot() {
        // Use the proven NAV traversal. The profile walker prunes inactive ancestors
        // and can miss a live panel below a scene/container traversal boundary.
        return findNodeByName('UserInfoMainPanel', true);
    }


    /* ============================================================
     * TOGGLES
     * ============================================================ */


    function collectToggles() {

        const root =
            findProfileRoot();


        if (!root) {

            return [];
        }


        const result =
            [];


        walk(
            root,
            node => {

                let toggle =
                    null;


                try {

                    toggle =
                        node.getComponent?.(
                            cc.Toggle
                        );

                } catch {}


                if (!toggle)
                    return;


                /*
                 * 현재 우리가 확인한
                 * towerNode ToggleContainer만
                 */
                const path =
                    nodePath(node);


                if (
                    !path.includes(
                        '/towerNode/toggleNode/'
                    )
                ) {
                    return;
                }


                result.push({

                    node,

                    toggle,

                    name:
                        node.name,

                    text:
                        getText(node) || {"toggle1":"기지 외관","toggle3":"대열 외관","toggle4":"기지 효과","toggle5":"이동 효과","toggle6":"행군 참여","toggle7":"수호 효과","toggle8":"영광의 장식","toggle10":"기지 오라"}[node.name],

                    active:
                        isActive(node),

                    checked:
                        !!toggle.isChecked,

                    path
                });

            },
            {
                includeInactive:
                    true
            }
        );


        return result
            .filter(
                row =>
                    row.active
                    &&
                    row.text
                    &&
                    TAB_ORDER_MAP.has(
                        row.name
                    )
            )
            .sort(
                (a, b) =>
                    TAB_ORDER_MAP.get(
                        a.name
                    )
                    -
                    TAB_ORDER_MAP.get(
                        b.name
                    )
            );
    }


    /* ============================================================
     * CONTENT
     * ============================================================ */


    function findTowerNode() {

        const root =
            findProfileRoot();


        if (!root)
            return null;


        return findChildPath(
            root,
            'contentNode/towerNode'
        );
    }


    function findContentRoot() {
    const tower = findTowerNode();
    if (!tower) return null;
    const selected = collectToggles().filter(tab => tab.toggle.isChecked);
    if (selected.length !== 1) return null;
    // Confirmed by the user's 2026-09-14 runtime diagnostics, not guessed names.
    const paths = {
        toggle1: 'skinNode',
        toggle3: 'armyparentNode/armyLineSkinNode',
        toggle4: 'headFrameNode/CityEffectNode',
        toggle5: 'transportParentNode/TransportEffectNode',
        toggle6: 'marchEnigmaParent/MarchEnigmaNode',
        toggle7: 'castleEnigmaParent/CastleEnigmaNode',
        toggle8: 'zswEnigmaParent/ZSWEnigmaNode',
        toggle10: 'castleHaloParent/CastleHaloNode'
    };
    const prefix = paths[selected[0].name];
    const content = prefix && findChildPath(tower, prefix + '/allTowerNode/view/content');
    return content && isActive(content) ? content : null;
}


    /* ============================================================
     * DATA STABILITY
     * ============================================================ */


    function contentSignature() {
        const content = findContentRoot();
        if (!content) return '';
        const items = collectCurrentItems();
        // Animated labels and sprite frames do not determine list readiness.
        // Item identity and explicit ownership markers must settle instead.
        return items.length ? JSON.stringify(items.map(item => ({
            id: item.id, key: item.key, path: item.path, owned: item.owned
        })).sort((a, b) => a.key.localeCompare(b.key))) : '';
    }


    async function waitForContentStable(options = {}) {
    const timeout = Number(options.timeout ?? 20000);
    const interval = Number(options.interval ?? 150);
    const settle = Number(options.settleMs ?? 1000);
    if (![timeout, interval, settle].every(Number.isFinite) || timeout <= 0 || interval <= 0 || settle < 0) {
        throw new Error('timeout/interval은 양수, settleMs는 0 이상의 유한한 숫자여야 합니다');
    }
    const panel = findProfileRoot();
    const tab = collectToggles().find(row => row.toggle.isChecked)?.name;
    const started = Date.now();
    let previous = '', lastChange = started, changes = 0, lastCount = 0;
    while (Date.now() - started < timeout) {
        if (
            disposed ||
            !findProfileRoot() ||
            collectToggles()
                .find(
                    row =>
                        row.toggle.isChecked
                )
                ?.name !== tab
        ) {
            throw new Error('수집 중 프로필이 닫히거나 선택 탭이 변경됨');
        }
        const signature = contentSignature();
        if (signature !== previous) { previous = signature; lastChange = Date.now(); changes++; }
        if (signature) {
            lastCount = JSON.parse(signature).length;
            if (Date.now() - lastChange >= settle) return {
                ok: true, signature, elapsedMs: Date.now() - started, changes, itemCount: lastCount
            };
        }
        await sleep(interval);
    }
    return { ok: false, signature: previous, elapsedMs: Date.now() - started, changes,
        itemCount: lastCount, reason: previous ? '제한 시간 내 목록 안정화 미완료' : '선택 탭의 아이템 미확인' };
}


    /* ============================================================
     * ITEM COLLECTION
     * ============================================================ */


    function itemKey(node) {
        const parts = [];
        for (let current = node; current; current = current.parent) {
            parts.unshift(current.name + '[' + (current.parent?.children || []).indexOf(current) + ']');
        }
        return parts.join('/');
    }

    function collectCurrentItems() {

        const content =
            findContentRoot();


        const tower =
            findTowerNode();


        if (!tower) {

            return [];
        }


        const nodes =
            [];


        /*
         * 가장 정확한 방법:
         * allTowerNode/view/content의 직계 아이템
         */
        if (content) {

            for (
                const child
                of content.children || []
            ) {

                if (
                    !isActive(child)
                ) {
                    continue;
                }


                if (
                    isSkinItemNode(
                        child
                    )
                ) {

                    nodes.push(
                        child
                    );
                }
            }
        }


        /*
         * fallback:
         * towerNode 전체에서 itemClickCallBack 탐색
         */
        if (
            !nodes.length
        ) {

            walk(
                content,
                node => {

                    if (
                        isSkinItemNode(
                            node
                        )
                    ) {

                        nodes.push(
                            node
                        );
                    }
                }
            );
        }


        const seen =
            new Set();


        return nodes
            .filter(
                node => {

                    if (
                        seen.has(node)
                    ) {
                        return false;
                    }


                    seen.add(node);

                    return true;
                }
            )
            .map(
                node => {

                    const ownership =
                        detectOwnership(
                            node
                        );


                    const texts =
                        collectTexts(
                            node
                        );


                    return {

                        id:
                            String(
                                node.name ||
                                ''
                            ),

                        name:
                            texts[0] ||
                            null,

                        texts,

                        owned:
                            ownership.owned,

                        ownership: {

                            confidence:
                                ownership
                                    .confidence,

                            reason:
                                ownership
                                    .reason,

                            evidence:
                                ownership
                                    .evidence
                        },

                        path:
                            nodePath(node),
                        key: itemKey(node)
                    };
                }
            );
    }


    /* ============================================================
     * TAB LOAD
     * ============================================================ */


    async function loadTab(tab, options = {}) {
        if (disposed) throw new Error('Navigator 종료됨');
        const panel = findProfileRoot();
        const beforeContent = findContentRoot();
        const beforeSignature = contentSignature();
        const wasChecked = !!tab.toggle.isChecked;
        if (typeof tab.toggle.check !== 'function') throw new Error(tab.name + ': toggle.check 없음');
        tab.toggle.check();
        await sleep(Number(options.delay ?? 700));
        if (
            disposed ||
            !findProfileRoot() ||
            collectToggles()
                .find(
                    row =>
                        row.toggle.isChecked
                )
                ?.name !== tab.name
        ) {
            throw new Error('프로필이 닫히거나 선택 탭이 변경됨');
        }
        const stable = await waitForContentStable(options);
        const afterSignature = contentSignature();
        const changed = wasChecked || beforeContent !== findContentRoot() || beforeSignature !== afterSignature;
        return {
            ok:
                stable.ok &&
                changed &&
                !disposed &&
                !!findProfileRoot() &&
                collectToggles()
                    .find(
                        row =>
                            row.toggle.isChecked
                    )
                    ?.name === tab.name,
            tab:
                tab.text,
            toggle:
                tab.name,
            beforeSignature,
            afterSignature,
            stable
        };
    }


    /* ============================================================
     * SINGLE TAB
     * ============================================================ */


function inspectCurrentProfileItems() {
    const panel = findProfileRoot();
    const tower = findTowerNode();
    const content = findContentRoot();
    const describe = node => node ? {
        name: node.name, path: nodePath(node), active: node.active,
        activeInHierarchy: node.activeInHierarchy, children: node.children?.length || 0
    } : null;
    const candidates = [];
    const itemButtons = [];
    walk(panel, node => {
        if (node.name === 'content' && /\/allTowerNode\/view\/content$/.test(nodePath(node))) candidates.push(describe(node));
    }, { includeInactive: true });
    walk(content, node => {
        const handlers = getButtonHandlers(node);
        if (handlers.length && itemButtons.length < 20) itemButtons.push({
            ...describe(node), matches: isSkinItemNode(node), handlers
        });
    }, { includeInactive: true });
    return {
        panel: describe(panel), tower: describe(tower), content: describe(content),
        selectedTabs: collectToggles().filter(tab => tab.toggle.isChecked).map(tab => tab.name),
        contentCandidates: candidates, itemButtons,
        matchedItems: collectCurrentItems().length
    };
}


    async function collectTab(
        tab,
        options = {}
    ) {

        const load =
            await loadTab(
                tab,
                options
            );


        /*
         * 프로필 탭은 기존 방식대로 현재 로드된 전체 데이터 구조에서
         * 바로 읽는다. 별도의 ScrollView 조작은 하지 않는다.
         */
        const observedItems =
            collectCurrentItems();


        const items =
            load.ok
                ? observedItems
                : [];


        if (!load.ok) {

            return {
                toggle:
                    tab.name,
                name:
                    tab.text,
                loaded:
                    false,
                stable:
                    !!load.stable?.ok,
                count:
                    null,
                ownedCount:
                    null,
                unownedCount:
                    null,
                unknownCount:
                    null,
                items:
                    [],
                observedItems,
                observedCount:
                    observedItems.length,
                error:
                    !load.stable?.ok
                        ? '아이템 로딩 확인 실패'
                        : '탭 전환 전후 데이터 변화 미확인',
                diagnostics:
                    inspectCurrentProfileItems(),
                load
            };
        }


        const owned =
            items.filter(
                item =>
                    item.owned === true
            );


        const unowned =
            items.filter(
                item =>
                    item.owned === false
            );


        const unknown =
            items.filter(
                item =>
                    item.owned === null
            );


        const result = {

            toggle:
                tab.name,

            name:
                tab.text,

            loaded:
                load.ok,

            stable:
                load.stable?.ok ??
                false,

            count:
                items.length,

            ownedCount:
                owned.length,

            unownedCount:
                unowned.length,

            unknownCount:
                unknown.length,

            items
        };


        console.log(
            `[PROFILE] ${tab.text}`,
            {
                total:
                    result.count,

                owned:
                    result.ownedCount,

                unowned:
                    result.unownedCount,

                unknown:
                    result.unknownCount
            }
        );


        return result;
    }


    /* ============================================================
     * ALL
     * ============================================================ */


    async function waitForProfileUiReady(
        options = {}
    ) {

        const timeout =
            Math.max(
                1000,
                Number(
                    options.profileReadyTimeout ??
                    5200
                )
            );

        const stableMs =
            Math.max(
                250,
                Number(
                    options.profileReadyStableMs ??
                    650
                )
            );

        const pollMs =
            Math.max(
                60,
                Number(
                    options.profileReadyPollMs ??
                    100
                )
            );


        const deadline =
            Date.now() +
            timeout;


        let stableSignature =
            '';

        let stableSince =
            0;

        let lastState = {
            profileFound:
                false,
            toggleCount:
                0,
            toggleNames:
                []
        };


        while (
            !disposed &&
            Date.now() <
                deadline
        ) {

            const profile =
                findProfileRoot();


            if (!profile) {

                stableSignature =
                    '';

                stableSince =
                    0;

                lastState = {
                    profileFound:
                        false,
                    toggleCount:
                        0,
                    toggleNames:
                        []
                };


                await sleep(
                    pollMs
                );

                continue;
            }


            let toggles =
                [];


            try {

                toggles =
                    collectToggles();

            } catch {}


            const toggleNames =
                toggles
                    .map(
                        tab =>
                            String(
                                tab?.name ||
                                ''
                            )
                    )
                    .filter(
                        Boolean
                    );


            const expectedReady =
                TAB_ORDER.every(
                    name =>
                        toggleNames.includes(
                            name
                        )
                );


            lastState = {
                profileFound:
                    true,
                toggleCount:
                    toggles.length,
                toggleNames
            };


            if (!expectedReady) {

                stableSignature =
                    '';

                stableSince =
                    0;

                await sleep(
                    pollMs
                );

                continue;
            }


            const signature =
                TAB_ORDER
                    .map(
                        name =>
                            toggleNames.includes(
                                name
                            )
                                ? name
                                : '-'
                    )
                    .join(
                        '|'
                    );


            if (
                signature !==
                stableSignature
            ) {

                stableSignature =
                    signature;

                stableSince =
                    Date.now();

            } else if (
                Date.now() -
                    stableSince >=
                stableMs
            ) {

                return {
                    ok: true,
                    profile:
                        findProfileRoot(),
                    toggles:
                        collectToggles(),
                    stableMs,
                    toggleNames
                };
            }


            await sleep(
                pollMs
            );
        }


        return {
            ok: false,
            reason:
                '프로필 UI 준비 시간 초과: 8개 탭이 안정적으로 생성되지 않음',
            ...lastState
        };
    }


    async function collectAll(
        options = {}
    ) {

        /*
         * 각 단계는 최초 1회 + 실패 시 최대 3회 재시도한다.
         * maxRetries를 넘겨도 안전상 3회를 초과하지 않는다.
         */
        const maxRetries =
            Math.max(
                0,
                Math.min(
                    3,
                    Number(
                        options.maxRetries ??
                        3
                    )
                )
            );

        const maxAttempts =
            maxRetries + 1;

        const retryDelay =
            Math.max(
                100,
                Number(
                    options.retryDelay ??
                    350
                )
            );

        /*
         * WORLD_MAP / WORLD_MINIMAP이면
         * 기존 NAV가 막아줌.
         */
        if (![STATE.BASE, STATE.WORLD].includes(detect().state)) return { ok: false, reason: '현재 화면에서는 프로필 수집 불가' };
        let profile = findProfileRoot();


        if (!profile) {

            if (
                typeof openOwnProfile !==
                'function'
            ) {

                return {

                    ok: false,

                    reason:
                        'TOPWAR_NAV.openOwnProfile 없음'
                };
            }


            let opened =
                null;

            const openAttempts =
                [];


            for (
                let attempt = 1;
                attempt <= maxAttempts;
                attempt += 1
            ) {

                try {

                    opened =
                        await openOwnProfile({
                            timeout:
                                options
                                    .profileTimeout ??
                                3000
                        });

                } catch (
                    error
                ) {

                    opened = {
                        ok: false,
                        reason:
                            error?.message ||
                            String(
                                error
                            )
                    };
                }


                openAttempts.push({
                    attempt,
                    ok:
                        !!opened?.ok,
                    reason:
                        opened?.reason ||
                        null
                });


                if (
                    opened?.ok
                )
                    break;


                if (
                    attempt <
                    maxAttempts
                ) {

                    try {
                        options.onProgress?.({
                            type:
                                'profile-open-retry',
                            attempt:
                                attempt + 1,
                            maxAttempts,
                            reason:
                                opened?.reason ||
                                '프로필 열기 실패'
                        });
                    } catch {}


                    await sleep(
                        retryDelay
                    );
                }
            }


            if (!opened?.ok) {

                return {

                    ok: false,

                    stage:
                        'OPEN_PROFILE',

                    detail:
                        opened,

                    attempts:
                        openAttempts
                };
            }


            await sleep(
                Number(
                    options
                        .profileDelay ??
                    400
                )
            );


            profile =
                findProfileRoot();
        }


        if (!profile) {

            return {

                ok: false,

                reason:
                    'UserInfoMainPanel 확인 실패'
            };
        }


        /*
         * UserInfoMainPanel 노드만 생겼다고 준비 완료가 아니다.
         * 실제 8개 탭이 모두 생성되고 같은 구성이 일정 시간 유지된 뒤에
         * profile-ready를 발생시킨다.
         */
        const ready =
            await waitForProfileUiReady(
                options
            );


        if (!ready.ok) {

            return {
                ok: false,
                stage:
                    'WAIT_PROFILE_UI',
                reason:
                    ready.reason,
                detail:
                    ready
            };
        }


        /*
         * Cocos가 프로필 프레임 내부 노드를 교체할 수 있으므로
         * 준비 완료 시점의 최신 root를 다시 잡는다.
         */
        profile =
            ready.profile ||
            findProfileRoot();


        const tabs =
            ready.toggles ||
            collectToggles();


        /*
         * 판매 정보 Collector가 UI 진행상황을 실제 수집 단계와 동기화할 수 있도록
         * 실제 8개 탭 준비 완료 뒤에 이벤트를 전달한다.
         */
        try {
            options.onProgress?.({
                type:
                    'profile-ready',
                profilePath:
                    nodePath(
                        profile
                    ),
                toggleCount:
                    tabs.length,
                toggleNames:
                    tabs.map(
                        tab =>
                            tab.name
                    ),
                stableMs:
                    ready.stableMs
            });
        } catch {}


        if (
            tabs.length !==
                TAB_ORDER.length ||
            !TAB_ORDER.every(
                name =>
                    tabs.some(
                        tab =>
                            tab.name ===
                            name
                    )
            )
        ) {

            return {
                ok: false,
                stage:
                    'VERIFY_PROFILE_TABS',
                reason:
                    `프로필 필수 탭 부족: ${tabs.length}/${TAB_ORDER.length}`,
                detail: {
                    toggleNames:
                        tabs.map(
                            tab =>
                                tab.name
                        )
                }
            };
        }


        const result = {

            ok: true,

            version:
                VERSION,

            collectedAt:
                new Date()
                    .toISOString(),

            tabCount:
                tabs.length,

            totalItems:
                0,

            ownedCount:
                0,

            unownedCount:
                0,

            unknownCount:
                0,

            tabs: {},

            flat: []
        };


        for (
            let index = 0;
            index < tabs.length;
            index++
        ) {

            const tab =
                tabs[index];


            console.log(
                `[PROFILE ${index + 1}/${tabs.length}] ${tab.text}`
            );


            try {
                options.onProgress?.({
                    type: 'tab-start',
                    index,
                    total: tabs.length,
                    toggle: tab.name,
                    label: tab.text
                });
            } catch {}


            /*
             * Cocos가 같은 프로필 화면 안에서 root 객체를 교체할 수 있으므로
             * 객체 identity는 비교하지 않는다. 화면이 닫혔는지만 확인한다.
             */
            if (
                disposed ||
                !findProfileRoot()
            ) {
                result.ok = false;
                result.reason =
                    disposed
                        ? '수집기 종료됨'
                        : '프로필 화면이 탭 조사 중 닫힘';
                result.stage =
                    'PROFILE_TAB_TRAVERSAL';
                break;
            }


            let data =
                null;

            const attempts =
                [];


            for (
                let attempt = 1;
                attempt <= maxAttempts;
                attempt += 1
            ) {

                try {

                    data =
                        await collectTab(
                            tab,
                            options
                        );

                } catch (
                    error
                ) {

                    recordError(
                        '프로필 탭 ' +
                        tab.name +
                        ` 시도 ${attempt}`,
                        error
                    );

                    data = {
                        name:
                            tab.text,
                        toggle:
                            tab.name,
                        loaded:
                            false,
                        stable:
                            false,
                        count:
                            null,
                        ownedCount:
                            null,
                        unownedCount:
                            null,
                        unknownCount:
                            null,
                        items:
                            [],
                        error:
                            error?.message ||
                            String(
                                error
                            )
                    };
                }


                const attemptOk =
                    !!data?.loaded &&
                    !!data?.stable;


                attempts.push({
                    attempt,
                    ok:
                        attemptOk,
                    reason:
                        attemptOk
                            ? null
                            : (
                                data?.error ||
                                '탭 데이터 확인 실패'
                              )
                });


                if (
                    attemptOk
                )
                    break;


                if (
                    attempt <
                    maxAttempts
                ) {

                    try {
                        options.onProgress?.({
                            type:
                                'tab-retry',
                            index,
                            total:
                                tabs.length,
                            toggle:
                                tab.name,
                            label:
                                tab.text,
                            attempt:
                                attempt + 1,
                            maxAttempts,
                            reason:
                                data?.error ||
                                '탭 데이터 확인 실패'
                        });
                    } catch {}


                    await sleep(
                        retryDelay
                    );
                }
            }


            data = {
                ...data,
                attempts
            };


            if (!data.loaded || !data.stable) result.ok = false;


            try {
                options.onProgress?.({
                    type: 'tab-complete',
                    index,
                    total: tabs.length,
                    toggle: tab.name,
                    label: tab.text,
                    ok: !!data.loaded && !!data.stable,
                    data
                });
            } catch {}


            result.tabs[
                tab.text
            ] =
                data;


            for (
                const item
                of data.items
            ) {

                result.flat.push({

                    tab:
                        tab.text,

                    toggle:
                        tab.name,

                    ...item
                });
            }


            result.totalItems +=
                data.count;

            result.ownedCount +=
                data.ownedCount;

            result.unownedCount +=
                data.unownedCount;

            result.unknownCount +=
                data.unknownCount;
        }


        result.ok = result.ok && tabs.length === TAB_ORDER.length && Object.keys(result.tabs).length === TAB_ORDER.length;
        if (!result.ok) {
            result.confirmedItemCount = result.totalItems;
            result.totalItems = result.ownedCount = result.unownedCount = result.unknownCount = null;
        }
        window.TOPWAR_PROFILE_DATA = result;


        console.log(
            '=============================='
        );

        console.log(
            '[TOPWAR_PROFILE] 수집 완료'
        );

        console.table(
            Object.values(
                result.tabs
            ).map(
                tab => ({

                    tab:
                        tab.name,

                    total:
                        tab.count,

                    owned:
                        tab.ownedCount,

                    unowned:
                        tab.unownedCount,

                    unknown:
                        tab.unknownCount
                })
            )
        );


        console.log(
            'TOTAL',
            {
                tabs:
                    result.tabCount,

                items:
                    result.totalItems,

                owned:
                    result.ownedCount,

                unowned:
                    result.unownedCount,

                unknown:
                    result.unknownCount
            }
        );


        console.log(
            '최종 객체:',
            result
        );


        return result;
    }


    /* ============================================================
     * OWNED ONLY
     * ============================================================ */


    function getOwned(
        data =
            window.TOPWAR_PROFILE_DATA
    ) {

        if (!data?.flat) {

            return [];
        }


        return data.flat.filter(
            item =>
                item.owned === true
        );
    }


    function getUnowned(
        data =
            window.TOPWAR_PROFILE_DATA
    ) {

        if (!data?.flat) {

            return [];
        }


        return data.flat.filter(
            item =>
                item.owned === false
        );
    }


    function getUnknown(
        data =
            window.TOPWAR_PROFILE_DATA
    ) {

        if (!data?.flat) {

            return [];
        }


        return data.flat.filter(
            item =>
                item.owned === null
        );
    }


    /* ============================================================
     * PUBLIC
     * ============================================================ */


    return {
        inspectCurrentProfileItems,

        waitForProfileUiReady,

        version:
            VERSION,

        TAB_ORDER,

        findProfileRoot,

        collectToggles,

        findContentRoot,

        collectCurrentItems,

        detectOwnership,

        waitForContentStable,

        collectTab,

        collectAll,

        getOwned,

        getUnowned,

        getUnknown
    };


})();

    /* ============================================================
     * TOPWAR CHARACTER SALE COLLECTOR
     *
     * 목적:
     * - 범용 매크로가 아니라 캐릭터 판매용 정보 수집
     * - 현재 확정된 프로필 8개 탭 데이터를 하나의 객체로 통합
     * - 아직 구조가 확정되지 않은 닉네임/서버/VIP/전투력 등은
     *   억지로 추측하지 않고 실제 Label(path + text)을 진단 데이터로 보존
     *
     * 결과:
     *   window.TOPWAR_CHARACTER_SALE_DATA
     * ============================================================ */

    const SALE_SCHEMA_VERSION = '0.9.3';

    const SALE_PROGRESS_ITEMS = Object.freeze([
        { key: 'profileBasic', label: '프로필 기본 정보', implemented: true },
        { key: 'toggle1', label: '보유 외관 정보', implemented: true },
        { key: 'toggle3', label: '보유 대열 정보', implemented: true },
        { key: 'toggle4', label: '보유 기지 효과 정보', implemented: true },
        { key: 'toggle5', label: '보유 이동 효과 정보', implemented: true },
        { key: 'toggle6', label: '보유 행군 참여 정보', implemented: true },
        { key: 'toggle7', label: '보유 수호 효과 정보', implemented: true },
        { key: 'toggle8', label: '보유 영광의 장식 정보', implemented: true },
        { key: 'toggle10', label: '보유 기지 오라 정보', implemented: true },

        // 영웅 상세 판매 정보.
        { key: 'heroes', label: '보유 영웅 정보', implemented: true },
        { key: 'skills', label: '장착 스킬 정보', implemented: true },
        { key: 'traits', label: '영웅 특성', implemented: true },
        { key: 'equipment', label: '타이탄 장비', implemented: true },
        { key: 'awakening', label: '영웅 각성', implemented: true },

        // 아직 후속 Collector가 필요한 항목.
        { key: 'inventory', label: '보유 아이템 / 재화 정보', implemented: false }
    ]);

    const SALE_PROFILE_CATEGORIES = Object.freeze({
        toggle1: { key: 'baseSkins',       label: '기지 외관' },
        toggle3: { key: 'formationSkins',  label: '대열 외관' },
        toggle4: { key: 'baseEffects',     label: '기지 효과' },
        toggle5: { key: 'marchEffects',    label: '이동 효과' },
        toggle6: { key: 'marchJoin',       label: '행군 참여' },
        toggle7: { key: 'guardianEffects', label: '수호 효과' },
        toggle8: { key: 'decorations',     label: '영광의 장식' },
        toggle10:{ key: 'baseAura',        label: '기지 오라' }
    });


    /*
     * 판매용 보유 수에서 제외할 항목.
     *
     * 카테고리와 관계없이 정확히 "효과 없음"만 제외한다.
     * "기본", "고전 해병대", "골든 링"은 정상 보유 항목으로 카운트한다.
     *
     * 원본 items 자체는 보존하고,
     * 판매용 ownedItems / ownedCount에서만 "효과 없음"을 제외한다.
     */
    const SALE_EXCLUDED_PROFILE_ITEM_NAMES =
        new Set([
            '효과 없음'
        ]);


    function saleProfileItemTexts(item) {

        return [
            item?.name,
            ...(Array.isArray(item?.texts)
                ? item.texts
                : [])
        ]
            .map(
                value =>
                    String(
                        value ?? ''
                    ).trim()
            )
            .filter(Boolean);
    }


    function isExcludedSaleProfileItem(
        toggle,
        item
    ) {

        return saleProfileItemTexts(
            item
        ).some(
            text =>
                SALE_EXCLUDED_PROFILE_ITEM_NAMES.has(
                    text
                )
        );
    }


    function saleOwnedProfileItems(
        toggle,
        items
    ) {

        return (
            Array.isArray(items)
                ? items
                : []
        ).filter(
            item =>
                item?.owned === true
                &&
                !isExcludedSaleProfileItem(
                    toggle,
                    item
                )
        );
    }

    function collectProfileHeaderLabels() {
        const panel = profileModule.findProfileRoot();

        if (!panel) {
            return [];
        }

        const rows = [];
        const seen = new Set();

        walk(panel, node => {
            const path = nodePath(node);

            /*
             * 판매 기본정보 후보만 보기 위해 외관 아이템 리스트 영역은 제외.
             * towerNode 내부 데이터는 profile.categories 쪽에서 별도로 수집한다.
             */
            if (path.includes('/contentNode/towerNode/')) {
                return;
            }

            const candidates = [];

            try {
                const label = node.getComponent?.(window.cc?.Label);
                const value = String(label?.string ?? '').trim();
                if (value) {
                    candidates.push({
                        type: 'cc.Label',
                        text: value
                    });
                }
            } catch {}

            try {
                const rich = node.getComponent?.(window.cc?.RichText);
                const value = String(rich?.string ?? '').trim();
                if (value) {
                    candidates.push({
                        type: 'cc.RichText',
                        text: value
                    });
                }
            } catch {}

            for (const item of candidates) {
                const key = JSON.stringify([path, item.type, item.text]);
                if (seen.has(key)) continue;
                seen.add(key);

                rows.push({
                    name: String(node.name || ''),
                    path,
                    type: item.type,
                    text: item.text
                });
            }
        });

        return rows;
    }

    function classifyProfileHeaderLabels(labels) {
        const groups = {
            nickname: [],
            server: [],
            level: [],
            vip: [],
            power: []
        };

        const rules = {
            nickname: /(nickname|nick|user.?name|player.?name|name)/i,
            server: /(server|zone|sid)/i,
            level: /(^|[^a-z])(level|lv)([^a-z]|$)/i,
            vip: /vip/i,
            power: /(power|combat|fight|battle.?power)/i
        };

        for (const row of labels || []) {
            const haystack = [
                row.name,
                row.path
            ].join(' ');

            for (const [key, pattern] of Object.entries(rules)) {
                if (pattern.test(haystack)) {
                    groups[key].push(row);
                }
            }
        }

        return groups;
    }

    function normalizeSaleProfile(profileData) {
        const categories = {};

        for (const descriptor of Object.values(SALE_PROFILE_CATEGORIES)) {
            categories[descriptor.key] = {
                key: descriptor.key,
                label: descriptor.label,
                toggle: null,
                loaded: false,
                stable: false,
                count: null,
                ownedCount: null,
                rawOwnedCount: null,
                excludedOwnedCount: 0,
                unownedCount: null,
                unknownCount: null,
                ownedItems: [],
                excludedOwnedItems: [],
                unknownItems: [],
                items: []
            };
        }

        for (const tab of Object.values(profileData?.tabs || {})) {
            const descriptor = SALE_PROFILE_CATEGORIES[tab.toggle];
            if (!descriptor) continue;

            const items = Array.isArray(tab.items) ? tab.items : [];
            const target = categories[descriptor.key];

            target.toggle = tab.toggle;
            target.loaded = !!tab.loaded;
            target.stable = !!tab.stable;
            const rawOwnedItems =
                items.filter(
                    item =>
                        item.owned === true
                );

            const saleOwnedItems =
                saleOwnedProfileItems(
                    tab.toggle,
                    items
                );

            const excludedOwnedItems =
                rawOwnedItems.filter(
                    item =>
                        isExcludedSaleProfileItem(
                            tab.toggle,
                            item
                        )
                );

            target.count =
                tab.count ??
                null;

            /*
             * 판매용 ownedCount.
             * 기본 지급 항목/효과 없음은 제외한다.
             */
            target.ownedCount =
                saleOwnedItems.length;

            /*
             * 진단을 위해 게임에서 읽은 원래 보유 수는 따로 보존.
             */
            target.rawOwnedCount =
                tab.ownedCount ??
                rawOwnedItems.length;

            target.excludedOwnedCount =
                excludedOwnedItems.length;

            target.unownedCount =
                tab.unownedCount ??
                null;

            target.unknownCount =
                tab.unknownCount ??
                null;

            target.ownedItems =
                saleOwnedItems;

            target.excludedOwnedItems =
                excludedOwnedItems;

            target.unknownItems =
                items.filter(
                    item =>
                        item.owned == null
                );

            target.items =
                items;
        }

        const categoryValues =
            Object.values(
                categories
            );

        const saleOwnedCount =
            categoryValues.reduce(
                (sum, category) =>
                    sum +
                    (
                        Number.isFinite(
                            category.ownedCount
                        )
                            ? category.ownedCount
                            : 0
                    ),
                0
            );

        const rawOwnedCount =
            categoryValues.reduce(
                (sum, category) =>
                    sum +
                    (
                        Number.isFinite(
                            category.rawOwnedCount
                        )
                            ? category.rawOwnedCount
                            : 0
                    ),
                0
            );

        const excludedOwnedCount =
            categoryValues.reduce(
                (sum, category) =>
                    sum +
                    (
                        Number.isFinite(
                            category.excludedOwnedCount
                        )
                            ? category.excludedOwnedCount
                            : 0
                    ),
                0
            );


        return {
            summary: {
                ok:
                    !!profileData?.ok,

                reason:
                    profileData?.reason ||
                    profileData?.detail?.reason ||
                    null,

                stage:
                    profileData?.stage ||
                    null,

                tabCount:
                    profileData?.tabCount ??
                    null,

                totalItems:
                    profileData?.totalItems ??
                    null,

                confirmedItemCount:
                    profileData
                        ?.confirmedItemCount ??
                    null,

                /*
                 * UI/판매 데이터에서 사용하는 보유 수.
                 */
                ownedCount:
                    saleOwnedCount,

                /*
                 * 게임에서 원래 읽은 보유 수.
                 */
                rawOwnedCount,

                excludedOwnedCount,

                unownedCount:
                    profileData?.unownedCount ??
                    null,

                unknownCount:
                    profileData?.unknownCount ??
                    null
            },

            categories
        };
    }

    function saleSleep(
        ms
    ) {

        return new Promise(
            resolve =>
                setTimeout(
                    resolve,
                    Math.max(
                        0,
                        Number(
                            ms ||
                            0
                        )
                    )
                )
        );
    }


    async function runCollectorStepWithRetries(
        label,
        task,
        options = {}
    ) {

        const maxRetries =
            Math.max(
                0,
                Math.min(
                    3,
                    Number(
                        options.maxRetries ??
                        3
                    )
                )
            );

        const maxAttempts =
            maxRetries + 1;

        const retryDelay =
            Math.max(
                100,
                Number(
                    options.retryDelay ??
                    350
                )
            );

        const attempts =
            [];

        let lastValue =
            null;


        for (
            let attempt = 1;
            attempt <= maxAttempts;
            attempt += 1
        ) {

            try {

                lastValue =
                    await task(
                        attempt,
                        maxAttempts
                    );

                const ok =
                    typeof options.isSuccess ===
                        'function'
                        ? !!options.isSuccess(
                            lastValue
                          )
                        : !!lastValue?.ok;


                attempts.push({
                    attempt,
                    ok,
                    reason:
                        ok
                            ? null
                            : (
                                lastValue?.reason ||
                                lastValue?.error ||
                                '단계 실패'
                              )
                });


                if (
                    ok
                ) {

                    return {
                        ok: true,
                        value:
                            lastValue,
                        attempts
                    };
                }

            } catch (
                error
            ) {

                attempts.push({
                    attempt,
                    ok: false,
                    reason:
                        error?.message ||
                        String(
                            error
                        )
                });


                lastValue = {
                    ok: false,
                    reason:
                        error?.message ||
                        String(
                            error
                        )
                };


                recordError(
                    `${label} 시도 ${attempt}`,
                    error
                );
            }


            if (
                attempt <
                maxAttempts
            ) {

                try {
                    options.onRetry?.({
                        label,
                        attempt:
                            attempt + 1,
                        maxAttempts,
                        reason:
                            attempts[
                                attempts.length -
                                1
                            ]?.reason
                    });
                } catch {}


                await saleSleep(
                    retryDelay
                );
            }
        }


        return {
            ok: false,
            value:
                lastValue,
            attempts,
            reason:
                attempts[
                    attempts.length -
                    1
                ]?.reason ||
                `${label} 실패`
        };
    }


    function findHeroListRoot() {

        const root =
            scene();

        let found =
            null;


        if (!root)
            return null;


        walk(
            root,
            node => {

                if (
                    found ||
                    !isActive(
                        node
                    )
                )
                    return;


                if (
                    node?.name ===
                    'HeroListPopup2023'
                ) {

                    found =
                        node;
                }
            }
        );


        return found;
    }


    function findHeroOpenButtonRow() {

        if (
            typeof gameButtonRows !==
            'function'
        )
            return null;


        const rows =
            gameButtonRows().filter(
                row => {

                    if (
                        !row?.enabled ||
                        !row?.supported
                    )
                        return false;


                    const hasHeroHandler =
                        (
                            row?.events ||
                            []
                        ).some(
                            event =>
                                event?.handler ===
                                'onHeroClick'
                        );


                    const exactHeroButton =
                        row?.name ===
                            'btnHero' &&
                        /\/NMainUI\/RightBottom\/btnHero$/
                            .test(
                                row?.path ||
                                ''
                            );


                    return (
                        hasHeroHandler ||
                        exactHeroButton
                    );
                }
            );


        rows.sort(
            (a, b) => {

                const score =
                    row =>
                        (
                            /\/NMainUI\/RightBottom\/btnHero$/
                                .test(
                                    row?.path ||
                                    ''
                                )
                                ? 1000
                                : 0
                        ) +
                        (
                            row?.name ===
                                'btnHero'
                                ? 200
                                : 0
                        ) +
                        (
                            (
                                row?.events ||
                                []
                            ).some(
                                event =>
                                    event?.handler ===
                                    'onHeroClick'
                            )
                                ? 100
                                : 0
                        ) +
                        (
                            /NMainUI/
                                .test(
                                    row?.path ||
                                    ''
                                )
                                ? 20
                                : 0
                        );


                return (
                    score(b) -
                    score(a)
                );
            }
        );


        return (
            rows[0] ||
            null
        );
    }


    async function openHeroListScreen(
        options = {}
    ) {

        const already =
            findHeroListRoot();


        if (
            already
        ) {

            return {
                ok: true,
                alreadyOpen:
                    true,
                path:
                    nodePath(
                        already
                    )
            };
        }


        const buttonDeadline =
            Date.now() +
            Math.max(
                500,
                Number(
                    options.buttonTimeout ??
                    options.timeout ??
                    3500
                )
            );


        let target =
            findHeroOpenButtonRow();


        /*
         * 프로필 프레임이 닫힌 직후 MainUI가 다시 활성화되는 데
         * 짧은 지연이 있을 수 있다.
         */
        while (
            !disposed &&
            !target &&
            Date.now() <
                buttonDeadline
        ) {

            await saleSleep(
                100
            );


            target =
                findHeroOpenButtonRow();
        }


        if (!target) {

            return {
                ok: false,
                reason:
                    'NMainUI/RightBottom/btnHero(onHeroClick)를 찾지 못했습니다.',
                heroCandidates:
                    (
                        typeof gameButtonRows ===
                            'function'
                            ? gameButtonRows()
                            : []
                    )
                        .filter(
                            row =>
                                /hero/i.test(
                                    [
                                        row?.name,
                                        row?.path,
                                        row?.text,
                                        ...(
                                            row?.events ||
                                            []
                                        ).map(
                                            event =>
                                                event?.handler
                                        )
                                    ]
                                        .filter(
                                            Boolean
                                        )
                                        .join(
                                            ' '
                                        )
                                )
                        )
                        .map(
                            describeGameButton
                        )
            };
        }


        const pressed =
            await pressGameButton(
                target.id,
                {
                    waitMs:
                        options.waitMs ??
                        500
                }
            );


        if (!pressed.ok) {

            return {
                ok: false,
                reason:
                    pressed.reason ||
                    '영웅 버튼 실행 실패',
                detail:
                    pressed
            };
        }


        const deadline =
            Date.now() +
            Number(
                options.timeout ??
                3500
            );


        let panel =
            findHeroListRoot();


        while (
            !disposed &&
            !panel &&
            Date.now() <
                deadline
        ) {

            await saleSleep(
                100
            );

            panel =
                findHeroListRoot();
        }


        return {
            ok:
                !!panel &&
                !disposed,
            reason:
                panel
                    ? undefined
                    : '영웅 목록 화면 확인 실패',
            path:
                panel
                    ? nodePath(
                        panel
                      )
                    : null,
            target:
                describeGameButton(
                    target
                )
        };
    }


    function findHeroListScrollView() {

        const panel =
            findHeroListRoot();


        if (
            !panel ||
            !window.cc?.ScrollView
        )
            return null;


        const candidates =
            [];


        walk(
            panel,
            node => {

                if (
                    !isActive(
                        node
                    )
                )
                    return;


                let component =
                    null;


                try {

                    component =
                        node.getComponent?.(
                            window.cc.ScrollView
                        );

                } catch {}


                if (!component)
                    return;


                const path =
                    nodePath(
                        node
                    );


                const content =
                    component.content ||
                    null;


                const contentPath =
                    content
                        ? nodePath(
                            content
                          )
                        : '';


                let score =
                    0;


                if (
                    node?.name ===
                    'ScrollView'
                )
                    score += 100;

                if (
                    /\/HeroListPopup2023\/ScrollView(?:\/|$)/
                        .test(
                            path
                        )
                )
                    score += 300;

                if (
                    /\/HeroListPopup2023\/ScrollView\/view\/content$/
                        .test(
                            contentPath
                        )
                )
                    score += 600;

                if (
                    content &&
                    findDescendantByName(
                        content,
                        'itemSpecialContent'
                    )
                )
                    score += 1000;

                if (
                    component.vertical ===
                    true
                )
                    score += 100;


                candidates.push({
                    node,
                    component,
                    content,
                    path,
                    contentPath,
                    score
                });
            }
        );


        candidates.sort(
            (a, b) =>
                b.score -
                a.score
        );


        return (
            candidates[0] ||
            null
        );
    }


    function heroScrollOffset(
        scrollInfo
    ) {

        const component =
            scrollInfo?.component;


        if (!component)
            return null;


        try {

            if (
                typeof component.getScrollOffset ===
                'function'
            ) {

                const offset =
                    component.getScrollOffset();


                return {
                    x:
                        Number(
                            offset?.x ??
                            0
                        ),
                    y:
                        Number(
                            offset?.y ??
                            0
                        )
                };
            }

        } catch {}


        const content =
            component.content ||
            scrollInfo?.content;


        if (content) {

            return {
                x:
                    Number(
                        content.x ??
                        content.position?.x ??
                        0
                    ),
                y:
                    Number(
                        content.y ??
                        content.position?.y ??
                        0
                    )
            };
        }


        return null;
    }


    function heroScrollMoved(
        before,
        after
    ) {

        if (
            !before ||
            !after
        )
            return false;


        return (
            Math.abs(
                Number(
                    after.x ||
                    0
                ) -
                Number(
                    before.x ||
                    0
                )
            ) >
                1 ||
            Math.abs(
                Number(
                    after.y ||
                    0
                ) -
                Number(
                    before.y ||
                    0
                )
            ) >
                1
        );
    }


    async function moveHeroListScroll(
        scrollInfo,
        position,
        options = {}
    ) {

        const component =
            scrollInfo?.component;


        if (!component) {

            return {
                ok: false,
                reason:
                    '영웅 ScrollView 없음'
            };
        }


        const target =
            Math.max(
                0,
                Math.min(
                    1,
                    Number(
                        position ||
                        0
                    )
                )
            );


        const duration =
            Math.max(
                0.15,
                Number(
                    options.scrollDuration ??
                    0.40
                )
            );


        const settleMs =
            Math.max(
                400,
                Number(
                    options.scrollSettleMs ??
                    700
                )
            );


        const before =
            heroScrollOffset(
                scrollInfo
            );


        let method =
            null;

        let error =
            null;


        /*
         * 1차: Cocos ScrollView 정식 percent API.
         * 애니메이션이 화면에 보이도록 0.4초를 기본값으로 사용.
         */
        try {

            if (
                typeof component.scrollToPercentVertical ===
                'function'
            ) {

                component.scrollToPercentVertical(
                    target,
                    duration,
                    false
                );

                method =
                    'scrollToPercentVertical';
            }

        } catch (
            e
        ) {

            error =
                e;
        }


        await saleSleep(
            Math.ceil(
                duration *
                1000
            ) +
            settleMs
        );


        let after =
            heroScrollOffset(
                scrollInfo
            );


        let moved =
            heroScrollMoved(
                before,
                after
            );


        /*
         * 0% 위치는 이미 상단일 수 있으므로 움직이지 않아도 정상.
         * 그 외 위치에서 percent API로 실제 이동이 없으면
         * getMaxScrollOffset + scrollToOffset을 fallback으로 사용.
         */
        if (
            target >
                0.001 &&
            !moved &&
            typeof component.getMaxScrollOffset ===
                'function' &&
            typeof component.scrollToOffset ===
                'function'
        ) {

            try {

                const max =
                    component.getMaxScrollOffset();


                const maxY =
                    Math.abs(
                        Number(
                            max?.y ??
                            0
                        )
                    );


                const offsetY =
                    maxY *
                    target;


                const vector =
                    window.cc?.v2
                        ? window.cc.v2(
                            0,
                            offsetY
                          )
                        : {
                            x: 0,
                            y: offsetY
                          };


                component.scrollToOffset(
                    vector,
                    duration,
                    false
                );


                method =
                    'scrollToOffset';


                await saleSleep(
                    Math.ceil(
                        duration *
                        1000
                    ) +
                    settleMs
                );


                after =
                    heroScrollOffset(
                        scrollInfo
                    );


                moved =
                    heroScrollMoved(
                        before,
                        after
                    );

            } catch (
                e
            ) {

                error =
                    e;
            }
        }


        return {
            ok:
                target <=
                    0.001 ||
                moved,

            target,

            method,

            moved,

            before,

            after,

            error:
                error
                    ? (
                        error?.message ||
                        String(
                            error
                        )
                      )
                    : null
        };
    }


    function mergeHeroRows(
        target,
        source
    ) {

        if (!target)
            return {
                ...source
            };


        const merged = {
            ...target,
            ...source
        };


        /*
         * 뒤쪽 스크롤에서 빈 문자열/NULL이 들어와
         * 앞서 확보한 값을 지우지 않도록 보정.
         */
        for (
            const key
            of [
                'name',
                'levelText',
                'level',
                'star',
                'awakenLevelText',
                'awakenLevel',
                'rarityEvidence'
            ]
        ) {

            if (
                source?.[key] == null ||
                source?.[key] ===
                    ''
            ) {

                merged[key] =
                    target?.[key] ??
                    source?.[key];
            }
        }


        return merged;
    }


    function heroSaleKey(
        item
    ) {

        if (
            Number.isFinite(
                item?.heroIdCandidate
            )
        ) {

            return (
                'id:' +
                item.heroIdCandidate
            );
        }


        if (
            item?.name
        ) {

            return (
                'name:' +
                item.name
            );
        }


        return (
            'path:' +
            (
                item?.path ||
                Math.random()
            )
        );
    }


    async function collectHeroListData(
        options = {}
    ) {

        /*
         * 중요:
         * openHeroListScreen()에서 이미 HeroListPopup2023 진입 성공을
         * 확인했다. 여기서 다시 saleWaitForNode()로 "동일 노드가 N ms 동안
         * 유지되는지"를 검사하면 Cocos 내부에서 프레임/CONTENT가 교체되는
         * 경우 실제 화면이 보이는데도 실패할 수 있다.
         *
         * 따라서 영웅 목록만큼은:
         *   화면 진입 확인 -> 고정 대기 -> 현재 패널 재탐색 -> 스크롤
         * 순서로 간다.
         */
        await saleSleep(
            Math.max(
                800,
                Number(
                    options.heroListOpenDelay ??
                    1200
                )
            )
        );


        let panel =
            findHeroListRoot();


        if (!panel) {

            /*
             * 렌더 지연 가능성을 고려해 짧게 추가 탐색.
             * 노드 identity 안정 판정은 하지 않는다.
             */
            const deadline =
                Date.now() +
                Math.max(
                    1000,
                    Number(
                        options.heroListFindTimeout ??
                        3000
                    )
                );


            while (
                !disposed &&
                !panel &&
                Date.now() <
                    deadline
            ) {

                await saleSleep(
                    100
                );


                panel =
                    findHeroListRoot();
            }
        }


        if (!panel) {

            return {
                ok: false,
                reason:
                    'HeroListPopup2023가 영웅 메뉴 진입 후 사라졌습니다.',
                items:
                    [],
                scrollSupported:
                    false,
                samples:
                    []
            };
        }


        /*
         * 화면에는 패널이 떠 있어도 virtual list의 ScrollView가
         * 한 박자 늦게 생성될 수 있으므로 별도로 기다린다.
         */
        let scrollInfo =
            findHeroListScrollView();


        const scrollDeadline =
            Date.now() +
            Math.max(
                1200,
                Number(
                    options.heroScrollViewTimeout ??
                    3200
                )
            );


        while (
            !disposed &&
            !scrollInfo &&
            Date.now() <
                scrollDeadline
        ) {

            await saleSleep(
                100
            );


            scrollInfo =
                findHeroListScrollView();
        }


        if (!scrollInfo) {

            const scrollCandidates =
                [];


            if (
                window.cc?.ScrollView
            ) {

                walk(
                    panel,
                    node => {

                        let component =
                            null;


                        try {

                            component =
                                node.getComponent?.(
                                    window.cc.ScrollView
                                );

                        } catch {}


                        if (!component)
                            return;


                        scrollCandidates.push({
                            name:
                                node.name ||
                                '',
                            path:
                                nodePath(
                                    node
                                ),
                            vertical:
                                component.vertical ??
                                null,
                            horizontal:
                                component.horizontal ??
                                null,
                            contentPath:
                                component.content
                                    ? nodePath(
                                        component.content
                                      )
                                    : null
                        });
                    }
                );
            }


            return {
                ok: false,
                reason:
                    '영웅 목록 내부 cc.ScrollView를 찾지 못했습니다.',
                count:
                    heroes.size,
                items:
                    [
                        ...heroes.values()
                    ],
                scrollSupported:
                    false,
                samples,
                scrollCandidates
            };
        }


        const heroes =
            new Map();

        const samples =
            [];


        /*
         * 스크롤 전에 현재 화면의 카드부터 반드시 한 번 읽는다.
         * 이 값이 0이면 스크롤 문제와 카드 탐색 문제를 구분할 수 있다.
         */
        const initialVisibleRows =
            inspectVisibleHeroItems();


        samples.push({
            type:
                'initial-visible',
            visible:
                initialVisibleRows.length,
            heroIds:
                initialVisibleRows
                    .map(
                        row =>
                            row?.heroIdCandidate
                    )
                    .filter(
                        value =>
                            Number.isFinite(
                                value
                            )
                    )
                    .slice(
                        0,
                        20
                    )
        });


        for (
            const row
            of initialVisibleRows
        ) {

            const key =
                heroSaleKey(
                    row
                );


            heroes.set(
                key,
                mergeHeroRows(
                    heroes.get(
                        key
                    ),
                    row
                )
            );
        }


        const capture =
            (
                position,
                attempt
            ) => {

                const rows =
                    inspectVisibleHeroItems();


                for (
                    const row
                    of rows
                ) {

                    const enrichedRow =
                        Number.isFinite(
                            position
                        )
                            ? {
                                ...row,
                                listPosition:
                                    position
                              }
                            : row;


                    const key =
                        heroSaleKey(
                            enrichedRow
                        );


                    heroes.set(
                        key,
                        mergeHeroRows(
                            heroes.get(
                                key
                            ),
                            enrichedRow
                        )
                    );
                }


                samples.push({
                    position,
                    attempt,
                    visible:
                        rows.length,
                    totalUnique:
                        heroes.size
                });


                return rows;
            };


        const settleDelay =
            Math.max(
                500,
                Number(
                    options.heroSettleDelay ??
                    700
                )
            );

        const sampleRetries =
            Math.max(
                0,
                Math.min(
                    3,
                    Number(
                        options.maxRetries ??
                        3
                    )
                )
            );


        /*
         * 새로 연 영웅 화면은 상단부터 시작.
         * moveHeroListScroll가 실제 offset 변화까지 확인한다.
         */
        await moveHeroListScroll(
            scrollInfo,
            0,
            {
                scrollDuration:
                    options.heroScrollDuration ??
                    0.40,

                scrollSettleMs:
                    settleDelay
            }
        );


        const positions =
            scrollInfo?.component &&
            typeof scrollInfo.component.scrollToPercentVertical ===
                'function'
                ? Array.from(
                    {
                        length: 13
                    },
                    (_, index) =>
                        index /
                        12
                  )
                : [null];


        for (
            const position
            of positions
        ) {

            if (
                disposed ||
                !findHeroListRoot()
            ) {

                return {
                    ok: false,
                    reason:
                        '영웅 목록 화면이 조사 중 닫혔습니다.',
                    count:
                        heroes.size,
                    items:
                        [
                            ...heroes.values()
                        ],
                    scrollSupported:
                        true,
                    samples
                };
            }


            if (
                position != null &&
                scrollInfo?.component
            ) {

                const scrollMove =
                    await moveHeroListScroll(
                        scrollInfo,
                        position,
                        {
                            scrollDuration:
                                options.heroScrollDuration ??
                                0.40,

                            scrollSettleMs:
                                settleDelay
                        }
                    );


                samples.push({
                    type:
                        'scroll',
                    position,
                    scroll:
                        scrollMove,
                    totalUnique:
                        heroes.size
                });


                /*
                 * 실제 이동이 안 된 구간은 같은 위치에서 한 번 더 시도.
                 */
                if (
                    position >
                        0.001 &&
                    !scrollMove.ok
                ) {

                    await saleSleep(
                        settleDelay
                    );


                    const retryMove =
                        await moveHeroListScroll(
                            scrollInfo,
                            position,
                            {
                                scrollDuration:
                                    options.heroScrollDuration ??
                                    0.40,

                                scrollSettleMs:
                                    settleDelay
                            }
                        );


                    samples.push({
                        type:
                            'scroll-retry',
                        position,
                        scroll:
                            retryMove,
                        totalUnique:
                            heroes.size
                    });
                }
            }


            let rows =
                [];


            for (
                let attempt = 1;
                attempt <=
                    sampleRetries + 1;
                attempt += 1
            ) {

                rows =
                    capture(
                        position,
                        attempt
                    );


                if (
                    rows.length
                )
                    break;


                if (
                    attempt <=
                    sampleRetries
                ) {

                    await saleSleep(
                        settleDelay
                    );
                }
            }
        }


        /*
         * 조사 종료 후 상단으로 되돌린다.
         */
        await moveHeroListScroll(
            scrollInfo,
            0,
            {
                scrollDuration:
                    options.heroScrollDuration ??
                    0.40,

                scrollSettleMs:
                    450
            }
        );


        const rawItems =
            [
                ...heroes.values()
            ].sort(
                (a, b) => {

                    const aid =
                        Number.isFinite(
                            a?.heroIdCandidate
                        )
                            ? a.heroIdCandidate
                            : Number.MAX_SAFE_INTEGER;

                    const bid =
                        Number.isFinite(
                            b?.heroIdCandidate
                        )
                            ? b.heroIdCandidate
                            : Number.MAX_SAFE_INTEGER;


                    return (
                        aid - bid ||
                        String(
                            a?.name ||
                            ''
                        ).localeCompare(
                            String(
                                b?.name ||
                                ''
                            )
                        )
                    );
                }
            );


        const rarityClassification =
            applyHeroRarityClassification(
                rawItems
            );


        const items =
            rarityClassification.items;


        return {
            ok:
                items.length >
                0,

            reason:
                items.length
                    ? undefined
                    : '영웅 카드를 읽지 못했습니다.',

            collectedAt:
                new Date()
                    .toISOString(),

            count:
                items.length,

            raritySummary:
                rarityClassification.summary,

            scrollSupported:
                !!scrollInfo?.component,

            scrollView: {
                path:
                    scrollInfo?.path ||
                    null,

                contentPath:
                    scrollInfo?.contentPath ||
                    null,

                vertical:
                    scrollInfo?.component
                        ?.vertical ??
                    null
            },

            samples,

            items
        };
    }



    /* ============================================================
     * HERO DETAIL SALE COLLECTOR
     *
     * 흐름:
     * 영웅 목록 -> 첫 보유 영웅 상세
     * -> 특성 -> 타이탄 장비 -> 각성
     * -> 다음 영웅
     * -> 전체 완료 후 영웅 상세 / 영웅 목록 닫기
     *
     * 읽기 전용 원칙:
     * - 특성 습득/교환 버튼 호출 금지
     * - 타이탄 편집/프로필 호출 금지
     * - 각성 레벨업/승격 호출 금지
     * ============================================================ */


    function saleUniqueStrings(
        values
    ) {

        const result =
            [];

        const seen =
            new Set();


        for (
            const value
            of (
                values ||
                []
            )
        ) {

            const text =
                String(
                    value ??
                    ''
                )
                    .replace(
                        /<[^>]*>/g,
                        ''
                    )
                    .replace(
                        /&nbsp;/gi,
                        ' '
                    )
                    .replace(
                        /\s+/g,
                        ' '
                    )
                    .trim();


            if (
                !text ||
                seen.has(
                    text
                )
            )
                continue;


            seen.add(
                text
            );

            result.push(
                text
            );
        }


        return result;
    }


    function saleTextBy(
        rows,
        predicate
    ) {

        const row =
            (
                rows ||
                []
            ).find(
                predicate
            );


        return (
            row?.text ||
            ''
        );
    }


    function saleFindNodes(
        root,
        predicate,
        options = {}
    ) {

        const result =
            [];


        if (!root)
            return result;


        const includeInactive =
            options.includeInactive ===
            true;


        const visit =
            node => {

                if (!node)
                    return;


                if (
                    (
                        includeInactive ||
                        isActive(
                            node
                        )
                    ) &&
                    predicate(
                        node
                    )
                ) {

                    result.push(
                        node
                    );
                }


                for (
                    const child
                    of (
                        node.children ||
                        []
                    )
                ) {

                    visit(
                        child
                    );
                }
            };


        visit(
            root
        );


        return result;
    }


    function saleFindButtonRow(
        predicate
    ) {

        if (
            typeof gameButtonRows !==
            'function'
        )
            return null;


        return (
            gameButtonRows()
                .find(
                    predicate
                ) ||
            null
        );
    }


    const SALE_VISIBLE_STABLE_MS =
        650;

    const SALE_VISIBLE_POLL_MS =
        80;


    function saleNodeIsVisiblyActive(
        node
    ) {

        if (!node)
            return false;


        /*
         * Cocos 2.4.x에서는 부모 opacity가 0이어도
         * cascadeOpacity 설정/렌더 구조에 따라 자식 UI가 실제 표시될 수 있다.
         *
         * 따라서 opacity는 "보임" 판정에 사용하지 않는다.
         * 실제 화면 진입 여부는 activeInHierarchy + 안정 시간 +
         * 필요 시 readyCheck(콘텐츠 생성 완료)로 판단한다.
         */
        for (
            let current = node;
            current;
            current = current.parent
        ) {

            if (
                current.active ===
                    false ||
                current.activeInHierarchy ===
                    false
            ) {

                return false;
            }


            if (
                current ===
                scene()
            )
                break;
        }


        return true;
    }


    async function saleWaitForNode(
        name,
        options = {}
    ) {

        const timeout =
            Math.max(
                100,
                Number(
                    options.timeout ??
                    3200
                )
            );

        const minVisibleMs =
            Math.max(
                0,
                Number(
                    options.minVisibleMs ??
                    options.visibleStableMs ??
                    SALE_VISIBLE_STABLE_MS
                )
            );

        const pollMs =
            Math.max(
                30,
                Number(
                    options.pollMs ??
                    SALE_VISIBLE_POLL_MS
                )
            );


        /*
         * timeout은 "화면이 나타날 때까지"의 시간으로 취급하고,
         * 일단 나타난 후에는 minVisibleMs를 채울 시간을 추가로 허용한다.
         */
        const searchDeadline =
            Date.now() +
            timeout;

        const hardDeadline =
            searchDeadline +
            minVisibleMs +
            pollMs * 2;


        let visibleSince =
            0;


        while (
            !disposed &&
            Date.now() <
                hardDeadline
        ) {

            const node =
                findActiveNodeByName(
                    name
                );


            const visible =
                saleNodeIsVisiblyActive(
                    node
                );


            let ready =
                visible;


            if (
                ready &&
                typeof options.readyCheck ===
                    'function'
            ) {

                try {

                    ready =
                        options.readyCheck(
                            node
                        ) !== false;

                } catch {

                    ready =
                        false;
                }
            }


            /*
             * Cocos 가상/동적 UI는 화면이 유지되는 동안에도 같은 이름의
             * Node 객체 자체를 교체할 수 있다.
             *
             * 따라서 객체 identity가 아니라 "동일 의미의 화면이 계속 준비됨"
             * 상태만 안정 시간 동안 유지되면 준비 완료로 판정한다.
             */
            if (ready) {

                if (!visibleSince) {

                    visibleSince =
                        Date.now();
                }


                if (
                    Date.now() -
                    visibleSince >=
                    minVisibleMs
                ) {

                    /*
                     * 안정 시간이 지난 시점의 최신 live node를 반환한다.
                     */
                    return (
                        findActiveNodeByName(
                            name
                        ) ||
                        node
                    );
                }

            } else {

                visibleSince =
                    0;


                if (
                    Date.now() >=
                    searchDeadline
                ) {

                    return null;
                }
            }


            await saleSleep(
                pollMs
            );
        }


        return null;
    }


    function salePanelFrame(
        root
    ) {

        if (!root)
            return null;


        for (
            let node = root;
            node && node !== scene();
            node = node.parent
        ) {

            if (
                /^UIFrame/
                    .test(
                        String(
                            node.name ||
                            ''
                        )
                    )
            ) {

                return node;
            }
        }


        return null;
    }


    function saleCloseRowScore(
        row,
        root,
        scope
    ) {

        if (
            !row?.enabled ||
            !row?.supported
        )
            return -1;


        if (
            scope &&
            !withinGameRoot(
                row.node,
                scope
            )
        )
            return -1;


        const path =
            String(
                row.path ||
                ''
            );

        const name =
            String(
                row.name ||
                ''
            );

        const handlers =
            (
                row.events ||
                []
            ).map(
                event =>
                    String(
                        event?.handler ||
                        ''
                    )
            );


        const closeHandler =
            handlers.some(
                handler =>
                    /^(?:close|closeBtnClick|onCloseClick|onClickClose|onBtnClose|onClose|closePanel|hide|onBack|onClickBack|onBtnBack)$/
                        .test(
                            handler
                        )
            );


        const closeName =
            /^(?:CLOSE|close|btn_close|closeBtn|btnClose|back|btn_back|backBtn)$/i
                .test(
                    name
                );


        if (
            !closeHandler &&
            !closeName
        )
            return -1;


        let score =
            0;


        if (
            /^CLOSE$/i.test(
                name
            )
        )
            score += 1200;

        if (
            /^(?:btn_close|closeBtn|close)$/i
                .test(
                    name
                )
        )
            score += 1000;

        if (
            closeHandler
        )
            score += 700;

        if (
            root &&
            withinGameRoot(
                row.node,
                root
            )
        )
            score += 300;

        if (
            /\/CLOSE$/i.test(
                path
            )
        )
            score += 200;


        return score;
    }


    async function closeSalePanelByName(
        name,
        options = {}
    ) {

        let root =
            findActiveNodeByName(
                name
            );


        if (!root) {

            return {
                ok: true,
                alreadyClosed:
                    true,
                panel:
                    name
            };
        }


        const timeout =
            Math.max(
                300,
                Number(
                    options.timeout ??
                    2200
                )
            );


        const scopes =
            [
                root,
                salePanelFrame(
                    root
                )
            ]
                .filter(
                    Boolean
                );


        for (
            const scope
            of scopes
        ) {

            const candidates =
                (
                    typeof gameButtonRows ===
                        'function'
                        ? gameButtonRows()
                        : []
                )
                    .map(
                        row => ({
                            row,
                            score:
                                saleCloseRowScore(
                                    row,
                                    root,
                                    scope
                                )
                        })
                    )
                    .filter(
                        item =>
                            item.score >=
                            0
                    )
                    .sort(
                        (a, b) =>
                            b.score -
                            a.score
                    );


            if (
                candidates.length
            ) {

                const target =
                    candidates[0].row;


                try {

                    await pressGameButton(
                        target.id,
                        {
                            waitMs:
                                200
                        }
                    );

                } catch {}


                const deadline =
                    Date.now() +
                    timeout;


                root =
                    findActiveNodeByName(
                        name
                    );


                while (
                    !disposed &&
                    root &&
                    Date.now() <
                        deadline
                ) {

                    await saleSleep(
                        80
                    );


                    root =
                        findActiveNodeByName(
                            name
                        );
                }


                if (!root) {

                    return {
                        ok: true,
                        panel:
                            name,
                        method:
                            'button',
                        target:
                            describeGameButton(
                                target
                            )
                    };
                }
            }
        }


        /*
         * Button을 특정하지 못하는 화면은 컴포넌트의 명시적
         * close/back 계열 메서드만 fallback으로 허용한다.
         */
        root =
            findActiveNodeByName(
                name
            );


        if (root) {

            const methodNames = [
                'close',
                'closeBtnClick',
                'onCloseClick',
                'onClickClose',
                'onBtnClose',
                'onClose',
                'closePanel',
                'hide',
                'onBack',
                'onClickBack',
                'onBtnBack'
            ];


            const methodRoots =
                [
                    root,
                    salePanelFrame(
                        root
                    )
                ]
                    .filter(
                        Boolean
                    );


            for (
                const methodRoot
                of methodRoots
            ) {

                for (
                    const component
                    of (
                        methodRoot
                            ?._components ||
                        []
                    )
                ) {

                    for (
                        const methodName
                        of methodNames
                    ) {

                        if (
                            typeof component?.[
                                methodName
                            ] !==
                            'function'
                        )
                            continue;


                        try {

                            component[
                                methodName
                            ].call(
                                component
                            );

                        } catch {

                            continue;
                        }


                        const deadline =
                            Date.now() +
                            timeout;


                        let current =
                            findActiveNodeByName(
                                name
                            );


                        while (
                            !disposed &&
                            current &&
                            Date.now() <
                                deadline
                        ) {

                            await saleSleep(
                                80
                            );


                            current =
                                findActiveNodeByName(
                                    name
                                );
                        }


                        if (!current) {

                            return {
                                ok: true,
                                panel:
                                    name,
                                method:
                                    `component.${methodName}`,
                                component:
                                    componentName(
                                        component
                                    )
                            };
                        }
                    }
                }
            }
        }


        return {
            ok: false,
            panel:
                name,
            reason:
                `${name} 닫기 실패`
        };
    }


    function findHeroDetailRoot() {

        return findActiveNodeByName(
            'HeroDetailPopup2024'
        );
    }


    function readHeroDetailIdentity() {

        const root =
            findHeroDetailRoot();


        if (!root) {

            return {
                ok: false,
                name:
                    '',
                tags:
                    [],
                tag:
                    null,
                level:
                    null,
                levelText:
                    '',
                power:
                    null,
                powerText:
                    ''
            };
        }


        const rows =
            collectTextsUnderNode(
                root,
                500
            );


        const name =
            saleTextBy(
                rows,
                row =>
                    row.name ===
                        'heroName' &&
                    /HeroDetailNameNode/
                        .test(
                            row.path ||
                            ''
                        )
            );


        const tags =
            saleUniqueStrings(
                rows
                    .filter(
                        row =>
                            row.name ===
                                'heroTag' &&
                            /HeroDetailNameNode/
                                .test(
                                    row.path ||
                                    ''
                                )
                    )
                    .map(
                        row =>
                            row.text
                    )
            );


        const levelText =
            saleTextBy(
                rows,
                row =>
                    row.name ===
                        'heroLevelLabel'
            );


        /*
         * HeroPowerUI는 전투력 숫자를 한 자리씩 여러 cc.Label로
         * 출력한다. 활성 Label의 순서를 유지한 채 이어 붙인다.
         */
        const powerDigits =
            rows
                .filter(
                    row =>
                        row.name ===
                            'num' &&
                        /HeroDetailNameNode\/powernode\/numlayout\/powerLab\/num$/
                            .test(
                                row.path ||
                                ''
                            )
                )
                .map(
                    row =>
                        String(
                            row.text ||
                            ''
                        )
                            .replace(
                                /\D/g,
                                ''
                            )
                )
                .filter(
                    Boolean
                );


        const powerText =
            powerDigits.join(
                ''
            );


        return {
            ok:
                !!name,
            name,
            tags,
            tag:
                tags[0] ||
                null,
            levelText,
            level:
                parseNumberText(
                    levelText
                ),
            powerText,
            power:
                powerText
                    ? Number(
                        powerText
                    )
                    : null
        };
    }


    function collectCurrentHeroSkills() {

        const detailRoot =
            findHeroDetailRoot();


        if (!detailRoot) {

            return {
                ok: false,
                available:
                    false,
                reason:
                    'HeroDetailPopup2024 없음',
                count:
                    0,
                items:
                    []
            };
        }


        const skillRoot =
            findActiveNodeByName(
                'HeroDetailSkillNode'
            );


        if (!skillRoot) {

            return {
                ok: true,
                available:
                    false,
                reason:
                    'HeroDetailSkillNode 없음',
                count:
                    0,
                items:
                    []
            };
        }


        const skillNodes =
            saleFindNodes(
                skillRoot,
                node =>
                    node.name ===
                        'skill' &&
                    /HeroDetailSkillNode\/skillsnode\/skillsnode\/skill$/
                        .test(
                            nodePath(
                                node
                            )
                        )
            );


        const items =
            [];


        for (
            let index = 0;
            index < skillNodes.length;
            index += 1
        ) {

            const node =
                skillNodes[index];

            const rows =
                collectTextsUnderNode(
                    node,
                    80
                );


            const levelText =
                saleTextBy(
                    rows,
                    row =>
                        row.name ===
                        'LabLevel'
                );


            /*
             * LabLevel이 없는 활성 skill 노드는 빈 슬롯일 수 있으므로
             * 실제 판매 정보에서는 제외한다.
             */
            if (!levelText)
                continue;


            items.push({
                slot:
                    items.length + 1,
                nodeIndex:
                    index,
                levelText,
                level:
                    parseNumberText(
                        levelText
                    ),
                path:
                    nodePath(
                        node
                    )
            });
        }


        /*
         * 현재 화면에서 직접 보이지 않는 내부 ID 후보가 있으면
         * 이미지/텍스처는 건드리지 않고 primitive 필드만 보조 저장.
         */
        const componentData =
            compactRelevantComponentFields(
                skillRoot,
                /Skill/i,
                /(id|skill|level|lv|hero|group|index|slot|type|select|current)/i
            )
                .slice(
                    0,
                    20
                );


        return {
            ok: true,
            available:
                true,
            count:
                items.length,
            items,
            componentData
        };
    }


    function findHeroDetailButton(
        options = {}
    ) {

        const root =
            findHeroDetailRoot();


        if (!root)
            return null;


        const pathIncludes =
            options.pathIncludes ||
            '';

        const name =
            options.name;

        const handler =
            options.handler;

        const text =
            options.text;


        return saleFindButtonRow(
            row => {

                if (
                    !row?.enabled ||
                    !row?.supported ||
                    !withinGameRoot(
                        row.node,
                        root
                    )
                )
                    return false;


                if (
                    name != null &&
                    row.name !==
                        name
                )
                    return false;


                if (
                    text != null &&
                    row.text !==
                        text
                )
                    return false;


                if (
                    pathIncludes &&
                    !String(
                        row.path ||
                        ''
                    ).includes(
                        pathIncludes
                    )
                )
                    return false;


                if (
                    handler &&
                    !(
                        row.events ||
                        []
                    ).some(
                        event =>
                            event?.handler ===
                            handler
                    )
                )
                    return false;


                return true;
            }
        );
    }


    async function selectHeroDetailToggle(
        name,
        options = {}
    ) {

        const row =
            findHeroDetailButton({
                name,
                handler:
                    'onToggleClick'
            });


        if (!row) {

            return {
                ok: false,
                available:
                    false,
                reason:
                    `${name} 탭 없음`
            };
        }


        if (
            row.checked ===
            true
        ) {

            return {
                ok: true,
                available:
                    true,
                alreadySelected:
                    true
            };
        }


        const pressed =
            await pressGameButton(
                row.id,
                {
                    waitMs:
                        options.waitMs ??
                        220
                }
            );


        return {
            ok:
                !!pressed?.ok,
            available:
                true,
            detail:
                pressed
        };
    }


    function compactRelevantComponentFields(
        root,
        componentPattern,
        keyPattern
    ) {

        const result =
            [];


        if (!root)
            return result;


        const nodes =
            saleFindNodes(
                root,
                () => true
            );


        for (
            const node
            of nodes
        ) {

            for (
                const component
                of (
                    node?._components ||
                    []
                )
            ) {

                const name =
                    componentName(
                        component
                    );


                if (
                    !componentPattern
                        .test(
                            name
                        )
                )
                    continue;


                const fields =
                    primitiveComponentFields(
                        component,
                        {
                            maxFields:
                                80
                        }
                    );

                const compact =
                    {};


                for (
                    const [
                        key,
                        value
                    ]
                    of Object.entries(
                        fields
                    )
                ) {

                    if (
                        keyPattern
                            .test(
                                key
                            )
                    ) {

                        compact[key] =
                            value;
                    }
                }


                if (
                    Object.keys(
                        compact
                    ).length
                ) {

                    result.push({
                        node:
                            node.name ||
                            '',
                        path:
                            nodePath(
                                node
                            ),
                        component:
                            name,
                        fields:
                            compact
                    });
                }


                if (
                    result.length >=
                    24
                )
                    return result;
            }
        }


        return result;
    }


    async function waitForHeroDetailReady(
        options = {}
    ) {

        const timeout =
            Math.max(
                800,
                Number(
                    options.timeout ??
                    3600
                )
            );

        const stableMs =
            Math.max(
                250,
                Number(
                    options.stableMs ??
                    options.screenVisibleStableMs ??
                    650
                )
            );

        const pollMs =
            Math.max(
                60,
                Number(
                    options.pollMs ??
                    100
                )
            );

        const differentFrom =
            String(
                options.differentFrom ??
                ''
            ).trim();


        const expectedName =
            String(
                options.expectedName ??
                ''
            ).trim();


        const deadline =
            Date.now() +
            timeout;


        let stableName =
            '';

        let stableSince =
            0;

        let lastIdentity =
            null;


        while (
            !disposed &&
            Date.now() <
                deadline
        ) {

            const root =
                findHeroDetailRoot();


            if (!root) {

                stableName =
                    '';

                stableSince =
                    0;

                await saleSleep(
                    pollMs
                );

                continue;
            }


            let identity =
                null;


            try {

                identity =
                    readHeroDetailIdentity();

            } catch (
                error
            ) {

                lastIdentity = {
                    ok: false,
                    error:
                        error?.message ||
                        String(
                            error
                        )
                };

                stableName =
                    '';

                stableSince =
                    0;

                await saleSleep(
                    pollMs
                );

                continue;
            }


            lastIdentity =
                identity;


            const name =
                String(
                    identity?.name ||
                    ''
                ).trim();


            if (
                !name ||
                (
                    differentFrom &&
                    name ===
                        differentFrom
                ) ||
                (
                    expectedName &&
                    name !==
                        expectedName
                )
            ) {

                stableName =
                    '';

                stableSince =
                    0;

                await saleSleep(
                    pollMs
                );

                continue;
            }


            if (
                name !==
                stableName
            ) {

                stableName =
                    name;

                stableSince =
                    Date.now();

            } else if (
                Date.now() -
                    stableSince >=
                stableMs
            ) {

                return {
                    ok: true,
                    root,
                    identity,
                    stableMs,
                    waitedMs:
                        timeout -
                        Math.max(
                            0,
                            deadline -
                            Date.now()
                        )
                };
            }


            await saleSleep(
                pollMs
            );
        }


        return {
            ok: false,
            reason:
                expectedName
                    ? `영웅 상세가 ${expectedName}(으)로 안정화되지 않음`
                    : (
                        differentFrom
                            ? `영웅 상세가 ${differentFrom}에서 다음 영웅으로 안정화되지 않음`
                            : '영웅 상세 이름이 안정적으로 표시되지 않음'
                      ),
            identity:
                lastIdentity,
            stableName:
                stableName ||
                null
        };
    }


    async function openFirstOwnedHeroDetail(
        heroItems,
        options = {}
    ) {

        if (
            findHeroDetailRoot()
        ) {

            return {
                ok: true,
                alreadyOpen:
                    true
            };
        }


        const knownIds =
            new Set(
                (
                    heroItems ||
                    []
                )
                    .filter(
                        item =>
                            Number.isFinite(
                                item
                                    ?.heroIdCandidate
                            ) &&
                            Number.isFinite(
                                item
                                    ?.level
                            )
                    )
                    .map(
                        item =>
                            Number(
                                item
                                    .heroIdCandidate
                            )
                    )
            );


        const deadline =
            Date.now() +
            Math.max(
                600,
                Number(
                    options.timeout ??
                    3000
                )
            );


        let target =
            null;


        while (
            !disposed &&
            !target &&
            Date.now() <
                deadline
        ) {

            const candidates =
                (
                    typeof gameButtonRows ===
                        'function'
                        ? gameButtonRows()
                        : []
                )
                    .filter(
                        row => {

                            if (
                                !row?.enabled ||
                                !row?.supported ||
                                row.name !==
                                    'frameBg' ||
                                !/HeroListPopup2023/
                                    .test(
                                        row.path ||
                                        ''
                                    ) ||
                                !(
                                    row.events ||
                                    []
                                ).some(
                                    event =>
                                        event?.handler ===
                                        'onItemClick'
                                )
                            )
                                return false;


                            const match =
                                String(
                                    row.path ||
                                    ''
                                ).match(
                                    /itemSpecialContent\/(\d+)\/HeroListItem2026/
                                );


                            if (!match)
                                return false;


                            return knownIds.has(
                                Number(
                                    match[1]
                                )
                            );
                        }
                    );


            target =
                candidates[0] ||
                null;


            if (!target) {

                await saleSleep(
                    100
                );
            }
        }


        if (!target) {

            return {
                ok: false,
                reason:
                    '화면에 표시된 보유 영웅 카드의 onItemClick 버튼을 찾지 못했습니다.'
            };
        }


        const pressed =
            await pressGameButton(
                target.id,
                {
                    waitMs:
                        250
                }
            );


        if (!pressed?.ok) {

            return {
                ok: false,
                reason:
                    pressed?.reason ||
                    '첫 영웅 상세 진입 실패'
            };
        }


        /*
         * 클릭 직후 바로 노드를 읽지 않는다.
         * HeroDetailPopup2024가 생기고 heroName이 실제 표시된 뒤
         * 일정 시간 같은 이름이 유지될 때까지 기다린다.
         */
        const ready =
            await waitForHeroDetailReady({
                timeout:
                    options.timeout ??
                    4200,

                stableMs:
                    options.stableMs ??
                    650
            });


        return {
            ok:
                !!ready?.ok,
            reason:
                ready?.ok
                    ? null
                    : (
                        ready?.reason ||
                        'HeroDetailPopup2024 준비 실패'
                      ),
            identity:
                ready?.identity ||
                null,
            target:
                describeGameButton(
                    target
                )
        };
    }


    function findCurrentTraitPanel() {

        const named =
            findActiveNodeByName(
                'HeroStrengthenPanelNew'
            );


        if (
            named &&
            saleNodeIsVisiblyActive(
                named
            )
        ) {

            const hasTalentNode =
                !!findDescendantByName(
                    named,
                    'HeroTalentNode'
                );

            const hasTalentItem =
                saleFindNodes(
                    named,
                    node =>
                        node.name ===
                        'heroTalentItem'
                ).length >
                0;


            if (
                hasTalentNode ||
                hasTalentItem
            ) {

                return named;
            }
        }


        let found =
            null;


        walk(
            scene(),
            node => {

                if (
                    found ||
                    !isActive(
                        node
                    )
                )
                    return;


                const name =
                    String(
                        node?.name ||
                        ''
                    );


                if (
                    !/panel|popup|content|talent/i
                        .test(
                            name
                        )
                )
                    return;


                const hasTalentNode =
                    !!findDescendantByName(
                        node,
                        'HeroTalentNode'
                    );

                const hasTalentItem =
                    saleFindNodes(
                        node,
                        child =>
                            child.name ===
                            'heroTalentItem'
                    ).length >
                    0;


                if (
                    hasTalentNode ||
                    hasTalentItem
                ) {

                    found =
                        node;
                }
            }
        );


        return found;
    }


    async function waitForCurrentTraitPanel(
        options = {}
    ) {

        const timeout =
            Math.max(
                300,
                Number(
                    options.timeout ??
                    2600
                )
            );

        const stableMs =
            Math.max(
                0,
                Number(
                    options.stableMs ??
                    250
                )
            );

        const deadline =
            Date.now() +
            timeout;


        let readySince =
            0;


        while (
            !disposed &&
            Date.now() <
                deadline
        ) {

            const panel =
                findCurrentTraitPanel();


            if (panel) {

                if (!readySince)
                    readySince =
                        Date.now();


                if (
                    Date.now() -
                    readySince >=
                    stableMs
                ) {

                    return (
                        findCurrentTraitPanel() ||
                        panel
                    );
                }

            } else {

                readySince =
                    0;
            }


            await saleSleep(
                80
            );
        }


        return null;
    }


    async function collectCurrentHeroTraits(
        options = {}
    ) {

        /*
         * 진단 결과:
         * - HeroStrengthenPanelNew가 이미 열린 상태일 수 있음
         * - 내부 HeroTalentNode / heroTalentItem이 실제 특성 데이터의 근거
         *
         * 따라서:
         * 1) 이미 열린 특성 패널이 있으면 즉시 재사용
         * 2) 없을 때만 toggle3 -> detailBtn 실행
         * 3) 패널 이름 단독이 아니라 특성 내용 노드로 최종 판정
         */
        let panel =
            findCurrentTraitPanel();


        let openedByCollector =
            false;


        if (!panel) {

            const toggle =
                await selectHeroDetailToggle(
                    'toggle3',
                    options
                );


            if (
                toggle.available ===
                false
            ) {

                return {
                    ok: true,
                    available:
                        false,
                    reason:
                        '특성 탭 없음',
                    items:
                        []
                };
            }


            if (!toggle.ok) {

                return {
                    ok: false,
                    available:
                        true,
                    reason:
                        '특성 탭 선택 실패'
                };
            }


            const detailDeadline =
                Date.now() +
                Math.max(
                    800,
                    Number(
                        options.tabVisibleTimeout ??
                        2200
                    )
                );


            let detailButton =
                null;


            while (
                !disposed &&
                Date.now() <
                    detailDeadline
            ) {

                /*
                 * toggle3 전환 직후 패널이 이미 열렸다면
                 * detailBtn을 다시 누르지 않고 바로 사용.
                 */
                panel =
                    findCurrentTraitPanel();


                if (panel)
                    break;


                detailButton =
                    findHeroDetailButton({
                        name:
                            'detailBtn',
                        handler:
                            'detailsClick'
                    });


                if (detailButton)
                    break;


                await saleSleep(
                    100
                );
            }


            if (
                !panel &&
                !detailButton
            ) {

                return {
                    ok: false,
                    available:
                        true,
                    detailAvailable:
                        false,
                    reason:
                        '특성 detailBtn(detailsClick) 확인 실패',
                    items:
                        []
                };
            }


            if (!panel) {

                const pressed =
                    await pressGameButton(
                        detailButton.id,
                        {
                            waitMs:
                                350
                        }
                    );


                if (!pressed?.ok) {

                    return {
                        ok: false,
                        available:
                            true,
                        reason:
                            pressed?.reason ||
                            '특성 세부 사항 진입 실패'
                    };
                }


                openedByCollector =
                    true;


                panel =
                    await waitForCurrentTraitPanel({
                        timeout:
                            options.panelTimeout ??
                            2800,
                        stableMs:
                            options.traitPanelStableMs ??
                            250
                    });
            }
        }


        if (!panel) {

            return {
                ok: false,
                available:
                    true,
                reason:
                    '특성 패널 확인 실패: HeroTalentNode/heroTalentItem 없음'
            };
        }


        let result;


        try {

            const allTexts =
                collectTextsUnderNode(
                    panel,
                    500
                );


            const talentTexts =
                allTexts.filter(
                    row =>
                        /\/Talentnode\/HeroTalentNode\//
                            .test(
                                row.path ||
                                ''
                            )
                );


            const equipped =
                saleUniqueStrings(
                    talentTexts
                        .filter(
                            row =>
                                /\/talentnode\/talent\/skill\/name$/
                                    .test(
                                        row.path ||
                                        ''
                                    )
                        )
                        .map(
                            row =>
                                row.text
                        )
                );


            const itemNodes =
                saleFindNodes(
                    panel,
                    node =>
                        node.name ===
                        'heroTalentItem'
                );


            const items =
                itemNodes
                    .map(
                        node => {

                            const rows =
                                collectTextsUnderNode(
                                    node,
                                    80
                                );


                            const name =
                                saleTextBy(
                                    rows,
                                    row =>
                                        row.name ===
                                        'Itemname'
                                )
                                ||
                                saleTextBy(
                                    rows,
                                    row =>
                                        row.name ===
                                            'name'
                                );


                            const addText =
                                saleTextBy(
                                    rows,
                                    row =>
                                        row.name ===
                                        'addNum'
                                );


                            const progressTexts =
                                saleUniqueStrings(
                                    rows
                                        .filter(
                                            row =>
                                                /\d+\s*\/\s*\d+/
                                                    .test(
                                                        row.text ||
                                                        ''
                                                    )
                                        )
                                        .map(
                                            row =>
                                                row.text
                                        )
                                );


                            let componentData =
                                null;


                            for (
                                const component
                                of (
                                    node
                                        ?._components ||
                                    []
                                )
                            ) {

                                if (
                                    componentName(
                                        component
                                    ) ===
                                    'HeroTalentItem'
                                ) {

                                    const fields =
                                        primitiveComponentFields(
                                            component,
                                            {
                                                maxFields:
                                                    100
                                            }
                                        );


                                    componentData = {};


                                    for (
                                        const [
                                            key,
                                            value
                                        ]
                                        of Object.entries(
                                            fields
                                        )
                                    ) {

                                        if (
                                            /(id|hero|talent|level|lv|value|num|quality|grade|rank|type|state|lock|own|have)/i
                                                .test(
                                                    key
                                                )
                                        ) {

                                            componentData[
                                                key
                                            ] = value;
                                        }
                                    }
                                }
                            }


                            return {
                                name:
                                    name ||
                                    null,
                                addText:
                                    addText ||
                                    null,
                                addValue:
                                    parseNumberText(
                                        addText
                                    ),
                                progressTexts,
                                texts:
                                    saleUniqueStrings(
                                        rows.map(
                                            row =>
                                                row.text
                                        )
                                    ).slice(
                                        0,
                                        16
                                    ),
                                componentData
                            };
                        }
                    )
                    .filter(
                        item =>
                            item.name ||
                            item.addText ||
                            item.progressTexts
                                .length ||
                            item.componentData
                    );


            result = {
                ok: true,
                available:
                    true,
                detailAvailable:
                    true,
                equipped,
                items,
                textCount:
                    talentTexts.length
            };

        } finally {

            if (
                openedByCollector
            ) {

                await closeSalePanelByName(
                    'HeroStrengthenPanelNew',
                    {
                        timeout:
                            options.closeTimeout ??
                            2200
                    }
                );


                await saleWaitForNode(
                    'HeroDetailPopup2024',
                    {
                        timeout:
                            options.returnVisibleTimeout ??
                            1800,

                        minVisibleMs:
                            options.returnVisibleStableMs ??
                            450
                    }
                );
            }
        }


        return result;
    }


    function collectTitanDetailData(
        slot
    ) {

        const root =
            findActiveNodeByName(
                'HeroEquipDetailPop'
            );


        if (!root) {

            return {
                ok: false,
                slot,
                reason:
                    'HeroEquipDetailPop 없음'
            };
        }


        const rows =
            collectTextsUnderNode(
                root,
                420
            );


        const name =
            saleTextBy(
                rows,
                row =>
                    row.name ===
                        'labName' &&
                    /\/titleNode\/New Layout\/labName$/
                        .test(
                            row.path ||
                            ''
                        )
            );


        const levelText =
            saleTextBy(
                rows,
                row =>
                    row.name ===
                        'lVLab'
            );


        const score =
            {};


        for (
            const type
            of [
                'land',
                'navy',
                'air'
            ]
        ) {

            const value =
                saleTextBy(
                    rows,
                    row =>
                        new RegExp(
                            `/scoreNode/${type}/scoreLabel$`
                        ).test(
                            row.path ||
                            ''
                        )
                );


            if (value) {

                score[type] =
                    parseNumberText(
                        value
                    );
            }
        }


        const optionGroup =
            section => {

                const names =
                    rows.filter(
                        row =>
                            row.name ===
                                'buffdes' &&
                            String(
                                row.path ||
                                ''
                            ).includes(
                                `/${section}/`
                            )
                    );

                const values =
                    rows.filter(
                        row =>
                            (
                                row.name ===
                                    'num1' ||
                                row.name ===
                                    'num2'
                            ) &&
                            String(
                                row.path ||
                                ''
                            ).includes(
                                `/${section}/`
                            )
                    );


                return {
                    names:
                        saleUniqueStrings(
                            names.map(
                                row =>
                                    row.text
                            )
                        ),
                    values:
                        saleUniqueStrings(
                            values.map(
                                row =>
                                    row.text
                            )
                        )
                };
            };


        const effectName =
            saleTextBy(
                rows,
                row =>
                    row.name ===
                        'effectName'
            );


        const effectTexts =
            saleUniqueStrings(
                rows
                    .filter(
                        row =>
                            /\/effectNode\//
                                .test(
                                    row.path ||
                                    ''
                                ) &&
                            (
                                row.type ===
                                    'cc.RichText' ||
                                row.name ===
                                    'RICHTEXT_CHILD'
                            )
                    )
                    .map(
                        row =>
                            row.text
                    )
            );


        const magicStoneCandidates =
            saleUniqueStrings(
                rows
                    .filter(
                        row =>
                            /(마석|magic.?stone|stone|gem|chip|crystal|moshi|mashi)/i
                                .test(
                                    [
                                        row.name,
                                        row.path,
                                        row.text
                                    ]
                                        .filter(
                                            Boolean
                                        )
                                        .join(
                                            ' '
                                        )
                                )
                    )
                    .map(
                        row =>
                            row.text
                    )
            );


        const componentData =
            compactRelevantComponentFields(
                root,
                /(HeroEquip|Equip|PropItem)/i,
                /(id|uid|level|lv|quality|grade|rank|type|part|slot|hero|stone|gem|chip|magic|crystal|buff|effect)/i
            );


        const qualityCandidates =
            [];


        for (
            const row
            of componentData
        ) {

            for (
                const [
                    key,
                    value
                ]
                of Object.entries(
                    row.fields ||
                    {}
                )
            ) {

                if (
                    /(quality|grade|rank)/i
                        .test(
                            key
                        )
                ) {

                    qualityCandidates.push({
                        component:
                            row.component,
                        key,
                        value
                    });
                }
            }
        }


        return {
            ok: true,
            slot,
            equipped:
                !!name ||
                !!levelText,
            name:
                name ||
                null,
            levelText:
                levelText ||
                null,
            level:
                parseNumberText(
                    levelText
                ),
            score,
            baseOptions:
                optionGroup(
                    'basebuffNode'
                ),
            randomOptions:
                optionGroup(
                    'randBuffNode'
                ),
            specialEffect: {
                name:
                    effectName ||
                    null,
                texts:
                    effectTexts
            },
            qualityCandidates,
            magicStoneCandidates,
            componentData:
                componentData.slice(
                    0,
                    12
                )
        };
    }


    async function collectCurrentHeroTitan(
        options = {}
    ) {

        const entry =
            findHeroDetailButton({
                name:
                    'btn_heroEquip',
                handler:
                    'onClickHeroEquipBtn'
            });


        if (!entry) {

            return {
                ok: true,
                available:
                    false,
                reason:
                    '타이탄 장비 진입 버튼 없음',
                slots:
                    []
            };
        }


        const pressed =
            await pressGameButton(
                entry.id,
                {
                    waitMs:
                        250
                }
            );


        if (!pressed?.ok) {

            return {
                ok: false,
                available:
                    true,
                reason:
                    pressed?.reason ||
                    '타이탄 장비 진입 실패'
            };
        }


        const panel =
            await saleWaitForNode(
                'HeroEquipWearPanel',
                {
                    timeout:
                        options.panelTimeout ??
                        3000,

                    minVisibleMs:
                        options.screenVisibleStableMs ??
                        SALE_VISIBLE_STABLE_MS
                }
            );


        if (!panel) {

            /*
             * 버튼이 존재해도 요구 레벨이 부족한 영웅은
             * 실제 장비 화면이 열리지 않을 수 있다.
             */
            return {
                ok: true,
                available:
                    false,
                reason:
                    'HeroEquipWearPanel 미표시',
                slots:
                    []
            };
        }


        const slots =
            [];


        try {

            for (
                let slot = 1;
                slot <= 6;
                slot += 1
            ) {

                const slotText =
                    String(
                        slot
                    ).padStart(
                        2,
                        '0'
                    );


                const slotStep =
                    await runCollectorStepWithRetries(
                        `타이탄 ${slotText}번 부위`,
                        async () => {

                            if (
                                findActiveNodeByName(
                                    'HeroEquipDetailPop'
                                )
                            ) {

                                await closeSalePanelByName(
                                    'HeroEquipDetailPop'
                                );
                            }


                            const liveRow =
                                saleFindButtonRow(
                                    row =>
                                        row?.enabled &&
                                        row?.supported &&
                                        new RegExp(
                                            `/HeroEquipWearPanel/wearNode/ui/${slotText}/Item$`
                                        ).test(
                                            row.path ||
                                            ''
                                        ) &&
                                        (
                                            row.events ||
                                            []
                                        ).some(
                                            event =>
                                                event?.handler ===
                                                'onItemClick'
                                        )
                                );


                            if (!liveRow) {

                                return {
                                    ok: true,
                                    slot,
                                    equipped:
                                        false,
                                    reason:
                                        '착용 장비 없음'
                                };
                            }


                            const openResult =
                                await pressGameButton(
                                    liveRow.id,
                                    {
                                        waitMs:
                                            180
                                    }
                                );


                            if (!openResult?.ok) {

                                return {
                                    ok: false,
                                    slot,
                                    reason:
                                        openResult?.reason ||
                                        '장비 상세 버튼 실행 실패'
                                };
                            }


                            const detail =
                                await saleWaitForNode(
                                    'HeroEquipDetailPop',
                                    {
                                        timeout:
                                            options.detailTimeout ??
                                            2200,

                                        minVisibleMs:
                                            options.screenVisibleStableMs ??
                                            SALE_VISIBLE_STABLE_MS
                                    }
                                );


                            if (!detail) {

                                if (
                                    !String(
                                        liveRow.text ||
                                        ''
                                    ).trim()
                                ) {

                                    return {
                                        ok: true,
                                        slot,
                                        equipped:
                                            false,
                                        reason:
                                            '착용 장비 없음'
                                    };
                                }


                                return {
                                    ok: false,
                                    slot,
                                    reason:
                                        'HeroEquipDetailPop 확인 실패'
                                };
                            }


                            const data =
                                collectTitanDetailData(
                                    slot
                                );


                            await closeSalePanelByName(
                                'HeroEquipDetailPop',
                                {
                                    timeout:
                                        options.closeTimeout ??
                                        1800
                                }
                            );


                            return data;
                        },
                        {
                            maxRetries:
                                options.maxRetries ??
                                3,
                            retryDelay:
                                options.retryDelay ??
                                350,
                            isSuccess:
                                value =>
                                    value?.ok ===
                                    true
                        }
                    );


                const slotData =
                    slotStep.value || {
                        ok: false,
                        slot,
                        reason:
                            slotStep.reason ||
                            '장비 수집 실패'
                    };


                slots.push({
                    ...slotData,
                    attempts:
                        slotStep
                            .attempts
                });
            }


            return {
                ok:
                    slots.every(
                        item =>
                            item.ok ===
                            true
                    ),
                available:
                    true,
                equippedCount:
                    slots.filter(
                        item =>
                            item.equipped
                    ).length,
                slots
            };

        } finally {

            if (
                findActiveNodeByName(
                    'HeroEquipDetailPop'
                )
            ) {

                await closeSalePanelByName(
                    'HeroEquipDetailPop'
                );
            }


            await closeSalePanelByName(
                'HeroEquipWearPanel',
                {
                    timeout:
                        options.closeTimeout ??
                        2200
                }
            );


            await saleWaitForNode(
                'HeroDetailPopup2024',
                {
                    timeout:
                        options.returnVisibleTimeout ??
                        1800,

                    minVisibleMs:
                        options.returnVisibleStableMs ??
                        450
                }
            );
        }
    }


    function awakenEffectTexts(
        rows,
        copyOnly = null
    ) {

        const selected =
            (
                rows ||
                []
            ).filter(
                row => {

                    const path =
                        String(
                            row.path ||
                            ''
                        );


                    if (
                        !/\/basebuffNode(?: copy)?\/layout\/desc\/lbl/
                            .test(
                                path
                            )
                    )
                        return false;


                    if (
                        copyOnly ===
                        true &&
                        !/\/basebuffNode copy\//
                            .test(
                                path
                            )
                    )
                        return false;


                    if (
                        copyOnly ===
                        false &&
                        /\/basebuffNode copy\//
                            .test(
                                path
                            )
                    )
                        return false;


                    return (
                        row.type ===
                            'cc.RichText' ||
                        row.name ===
                            'RICHTEXT_CHILD'
                    );
                }
            );


        const rich =
            saleUniqueStrings(
                selected
                    .filter(
                        row =>
                            row.type ===
                            'cc.RichText'
                    )
                    .map(
                        row =>
                            row.text
                    )
            );


        if (
            rich.length
        )
            return rich;


        return saleUniqueStrings(
            selected.map(
                row =>
                    row.text
            )
        );
    }


    function compactAwakenInspection(
        inspected,
        fallback = {}
    ) {

        if (!inspected) {

            return {
                ok: false,
                ...fallback,
                reason:
                    '각성 스킬 조사 결과 없음'
            };
        }


        return {
            ok:
                !!inspected.ok,
            index:
                inspected.skill
                    ?.skillIndex ??
                fallback.index ??
                null,
            title:
                inspected.title ||
                fallback.title ||
                null,
            skillId:
                inspected.skill
                    ?.skillId ??
                null,
            heroId:
                inspected.skill
                    ?.heroId ??
                null,
            currentLevel:
                inspected.skill
                    ?.currentLevel ??
                fallback.currentLevel ??
                null,
            currentStage:
                inspected.stage
                    ?.current ??
                fallback.currentStage ??
                null,
            nextStage:
                inspected.stage
                    ?.next ??
                null,
            observedMaxStage:
                inspected.maxPreview
                    ?.observedMaxStage ??
                null,
            currentEffect:
                awakenEffectTexts(
                    inspected.texts,
                    false
                ),
            nextEffect:
                awakenEffectTexts(
                    inspected.texts,
                    true
                ),
            maxPreviewEffect:
                awakenEffectTexts(
                    inspected.maxPreview
                        ?.snapshot
                        ?.texts ||
                    [],
                    null
                ),
            unlockTexts:
                saleUniqueStrings(
                    (
                        inspected.unlockTexts ||
                        []
                    ).map(
                        row =>
                            row.text
                    )
                ),
            extraEffects:
                saleUniqueStrings(
                    (
                        inspected.extraEffects ||
                        []
                    ).map(
                        row =>
                            row.text
                    )
                ),
            restore: {
                restored:
                    inspected.maxPreview
                        ?.restored ??
                    true,
                restoreMode:
                    inspected.maxPreview
                        ?.restoreMode ??
                    null
            }
        };
    }


    async function collectCurrentHeroAwakening(
        options = {}
    ) {

        const toggle =
            await selectHeroDetailToggle(
                'toggle4',
                options
            );


        if (
            toggle.available ===
            false
        ) {

            return {
                ok: true,
                available:
                    false,
                reason:
                    '각성 탭 없음',
                level:
                    null,
                skills:
                    []
            };
        }


        if (!toggle.ok) {

            return {
                ok: false,
                available:
                    true,
                reason:
                    '각성 탭 선택 실패',
                skills:
                    []
            };
        }


        const root =
            await saleWaitForNode(
                'HeroDetailAwaken',
                {
                    timeout:
                        options.tabVisibleTimeout ??
                        2400,

                    minVisibleMs:
                        options.screenVisibleStableMs ??
                        SALE_VISIBLE_STABLE_MS
                }
            );


        if (!root) {

            return {
                ok: false,
                available:
                    true,
                reason:
                    'HeroDetailAwaken 확인 실패',
                skills:
                    []
            };
        }


        const mainTexts =
            collectTextsUnderNode(
                root,
                300
            );


        const awakenLevelText =
            saleTextBy(
                mainTexts,
                row =>
                    row.name ===
                        'labAwakenLevel' &&
                    /\/MainNode\/awakenedNode\/labAwakenLevel$/
                        .test(
                            row.path ||
                            ''
                        )
            );


        const skills =
            [];


        for (
            let index = 0;
            index < 4;
            index += 1
        ) {

            const skillNode =
                saleFindNodes(
                    root,
                    node =>
                        node.name ===
                            String(
                                index
                            ) &&
                        new RegExp(
                            `/Skillcontent1/${index}$`
                        ).test(
                            nodePath(
                                node
                            )
                        )
                )[0] ||
                null;


            if (!skillNode) {

                skills.push({
                    ok: true,
                    index,
                    available:
                        false,
                    unlocked:
                        false,
                    reason:
                        '각성 스킬 슬롯 없음'
                });

                continue;
            }


            const slotTexts =
                collectTextsUnderNode(
                    skillNode,
                    80
                );


            const currentLevelText =
                saleTextBy(
                    slotTexts,
                    row =>
                        row.name ===
                            'labLevel'
                );


            const lockText =
                saleTextBy(
                    slotTexts,
                    row =>
                        row.name ===
                            'labLockLevel'
                )
                ||
                saleTextBy(
                    slotTexts,
                    row =>
                        /도달 시 해제/
                            .test(
                                row.text ||
                                ''
                            )
                );


            const skillStep =
                await runCollectorStepWithRetries(
                    `각성 스킬 ${index + 1}`,
                    async () => {

                        if (
                            findActiveNodeByName(
                                'HeroAwakenSkillUpPop'
                            )
                        ) {

                            await closeSalePanelByName(
                                'HeroAwakenSkillUpPop'
                            );
                        }


                        const row =
                            saleFindButtonRow(
                                item =>
                                    item?.enabled &&
                                    item?.supported &&
                                    new RegExp(
                                        `/HeroDetailAwaken/MainNode/awakenedNode/Skillcontent1/${index}$`
                                    ).test(
                                        item.path ||
                                        ''
                                    ) &&
                                    (
                                        item.events ||
                                        []
                                    ).some(
                                        event =>
                                            event?.handler ===
                                            'onItemClick'
                                    )
                            );


                        if (!row) {

                            if (lockText) {

                                return {
                                    ok: true,
                                    available:
                                        true,
                                    index,
                                    unlocked:
                                        false,
                                    lockText,
                                    currentLevelText:
                                        currentLevelText ||
                                        null,
                                    currentStage:
                                        parseStageNumber(
                                            currentLevelText
                                        )
                                };
                            }


                            return {
                                ok: false,
                                index,
                                reason:
                                    '각성 스킬 onItemClick 버튼 없음'
                            };
                        }


                        await pressGameButton(
                            row.id,
                            {
                                waitMs:
                                    180
                            }
                        );


                        const popup =
                            await saleWaitForNode(
                                'HeroAwakenSkillUpPop',
                                {
                                    timeout:
                                        options.skillPopupTimeout ??
                                        1900,

                                    minVisibleMs:
                                        options.screenVisibleStableMs ??
                                        SALE_VISIBLE_STABLE_MS
                                }
                            );


                        if (!popup) {

                            if (lockText) {

                                return {
                                    ok: true,
                                    available:
                                        true,
                                    index,
                                    unlocked:
                                        false,
                                    lockText,
                                    currentLevelText:
                                        currentLevelText ||
                                        null,
                                    currentStage:
                                        parseStageNumber(
                                            currentLevelText
                                        )
                                };
                            }


                            return {
                                ok: false,
                                index,
                                reason:
                                    'HeroAwakenSkillUpPop 확인 실패'
                            };
                        }


                        const inspected =
                            await inspectAwakenSkillData({
                                includeMaxPreview:
                                    true
                            });


                        const compact =
                            compactAwakenInspection(
                                inspected,
                                {
                                    index,
                                    currentStage:
                                        parseStageNumber(
                                            currentLevelText
                                        )
                                }
                            );


                        if (
                            findActiveNodeByName(
                                'HeroAwakenSkillUpPop'
                            )
                        ) {

                            await closeSalePanelByName(
                                'HeroAwakenSkillUpPop'
                            );


                            await saleWaitForNode(
                                'HeroDetailAwaken',
                                {
                                    timeout:
                                        options.returnVisibleTimeout ??
                                        1600,

                                    minVisibleMs:
                                        options.returnVisibleStableMs ??
                                        400
                                }
                            );
                        }


                        return {
                            ...compact,
                            available:
                                true,
                            unlocked:
                                true,
                            lockText:
                                lockText ||
                                null
                        };
                    },
                    {
                        maxRetries:
                            options.maxRetries ??
                            3,
                        retryDelay:
                            options.retryDelay ??
                            350,
                        isSuccess:
                            value =>
                                value?.ok ===
                                true
                    }
                );


            skills.push({
                ...(
                    skillStep.value ||
                    {
                        ok: false,
                        index,
                        reason:
                            skillStep.reason ||
                            '각성 스킬 수집 실패'
                    }
                ),
                attempts:
                    skillStep
                        .attempts
            });
        }


        if (
            findActiveNodeByName(
                'HeroAwakenSkillUpPop'
            )
        ) {

            await closeSalePanelByName(
                'HeroAwakenSkillUpPop'
            );
        }


        await saleWaitForNode(
            'HeroDetailAwaken',
            {
                timeout:
                    options.returnVisibleTimeout ??
                    1600,

                minVisibleMs:
                    options.returnVisibleStableMs ??
                    400
            }
        );


        return {
            ok:
                skills.every(
                    skill =>
                        skill.ok ===
                        true
                ),
            available:
                true,
            levelText:
                awakenLevelText ||
                null,
            level:
                parseNumberText(
                    awakenLevelText
                ),
            skills
        };
    }


    async function moveToNextHeroDetail(
        previousName,
        options = {}
    ) {

        const next =
            findHeroDetailButton({
                name:
                    'btn_fanye_2',
                handler:
                    'onNextHeroClick',
                pathIncludes:
                    '/changeBtnsNode/'
            });


        if (!next) {

            return {
                ok: false,
                reason:
                    '다음 영웅 버튼 없음'
            };
        }


        const pressed =
            await pressGameButton(
                next.id,
                {
                    waitMs:
                        180
                }
            );


        if (!pressed?.ok) {

            return {
                ok: false,
                reason:
                    pressed?.reason ||
                    '다음 영웅 버튼 실행 실패'
            };
        }


        /*
         * 다음 영웅으로 이름이 바뀐 것만 확인하지 않고,
         * 바뀐 이름이 일정 시간 유지된 뒤에 다음 수집으로 넘긴다.
         */
        const ready =
            await waitForHeroDetailReady({
                timeout:
                    options.timeout ??
                    4200,

                stableMs:
                    options.stableMs ??
                    650,

                differentFrom:
                    previousName
            });


        return {
            ok:
                !!ready?.ok,
            reason:
                ready?.ok
                    ? null
                    : (
                        ready?.reason ||
                        '다음 영웅으로 변경되지 않음'
                      ),
            identity:
                ready?.identity ||
                null
        };
    }


    function findHeroListCardButtonById(
        heroId
    ) {

        const id =
            Number(
                heroId
            );


        if (!Number.isFinite(id))
            return null;


        const pattern =
            new RegExp(
                `/itemSpecialContent/${id}/HeroListItem2026(?:/|$)`
            );


        return (
            gameButtonRows()
                .find(
                    row =>
                        row?.enabled &&
                        row?.supported &&
                        row.name ===
                            'frameBg' &&
                        pattern.test(
                            String(
                                row.path ||
                                ''
                            )
                        ) &&
                        (
                            row.events ||
                            []
                        ).some(
                            event =>
                                event?.handler ===
                                'onItemClick'
                        )
                ) ||
            null
        );
    }


    async function closeHeroDetailForListFallback(
        options = {}
    ) {

        if (!findHeroDetailRoot()) {

            return {
                ok: true,
                alreadyClosed:
                    true
            };
        }


        return closeSalePanelByName(
            'HeroDetailPopup2024',
            {
                timeout:
                    options.timeout ??
                    2600
            }
        );
    }


    async function openHeroFromListItem(
        hero,
        options = {}
    ) {

        const heroId =
            Number(
                hero?.heroIdCandidate
            );

        const expectedName =
            String(
                hero?.name ||
                ''
            ).trim();


        if (
            !Number.isFinite(
                heroId
            ) ||
            !expectedName
        ) {

            return {
                ok: false,
                reason:
                    '목록 fallback 대상 영웅 정보 부족'
            };
        }


        const closeResult =
            await closeHeroDetailForListFallback(
                options
            );


        if (!closeResult?.ok) {

            return {
                ok: false,
                reason:
                    closeResult?.reason ||
                    '현재 영웅 상세 닫기 실패'
            };
        }


        if (!findHeroListRoot()) {

            return {
                ok: false,
                reason:
                    'fallback 중 영웅 목록 화면 없음'
            };
        }


        const scrollInfo =
            findHeroListScrollView();


        if (!scrollInfo) {

            return {
                ok: false,
                reason:
                    'fallback 중 영웅 목록 ScrollView 없음'
            };
        }


        const settleMs =
            Math.max(
                450,
                Number(
                    options.heroFallbackSettleMs ??
                    650
                )
            );


        const tryOpenCurrent =
            async () => {

                const button =
                    findHeroListCardButtonById(
                        heroId
                    );


                if (!button)
                    return null;


                const pressed =
                    await pressGameButton(
                        button.id,
                        {
                            waitMs:
                                220
                        }
                    );


                if (!pressed?.ok) {

                    return {
                        ok: false,
                        reason:
                            pressed?.reason ||
                            `${expectedName} 카드 클릭 실패`
                    };
                }


                const ready =
                    await waitForHeroDetailReady({
                        timeout:
                            options.heroDetailOpenTimeout ??
                            4500,

                        stableMs:
                            options.screenVisibleStableMs ??
                            650,

                        expectedName
                    });


                return {
                    ok:
                        !!ready?.ok,
                    reason:
                        ready?.ok
                            ? null
                            : (
                                ready?.reason ||
                                `${expectedName} 상세 열기 실패`
                              ),
                    identity:
                        ready?.identity ||
                        null
                };
            };


        const preferred =
            Number(
                hero?.listPosition
            );


        if (
            Number.isFinite(
                preferred
            )
        ) {

            await moveHeroListScroll(
                scrollInfo,
                preferred,
                {
                    scrollDuration:
                        options.heroScrollDuration ??
                        0.40,

                    scrollSettleMs:
                        settleMs
                }
            );


            const direct =
                await tryOpenCurrent();


            if (direct)
                return direct;
        }


        const scanSteps =
            Math.max(
                8,
                Math.min(
                    24,
                    Number(
                        options.heroFallbackScanSteps ??
                        12
                    )
                )
            );


        for (
            let index = 0;
            index <= scanSteps;
            index += 1
        ) {

            const position =
                index /
                scanSteps;


            await moveHeroListScroll(
                scrollInfo,
                position,
                {
                    scrollDuration:
                        options.heroScrollDuration ??
                        0.40,

                    scrollSettleMs:
                        settleMs
                }
            );


            const result =
                await tryOpenCurrent();


            if (result)
                return result;
        }


        return {
            ok: false,
            reason:
                `영웅 목록에서 ${expectedName}(${heroId}) 카드를 찾지 못함`
        };
    }


    async function openNextUnvisitedHeroFromList(
        known,
        visited,
        options = {}
    ) {

        const target =
            (
                known ||
                []
            ).find(
                hero =>
                    hero?.name &&
                    !visited.has(
                        hero.name
                    )
            );


        if (!target) {

            return {
                ok: false,
                reason:
                    '미수집 영웅 없음'
            };
        }


        const opened =
            await openHeroFromListItem(
                target,
                options
            );


        return {
            ...opened,
            fallback:
                true,
            target: {
                heroIdCandidate:
                    target.heroIdCandidate,
                name:
                    target.name,
                listPosition:
                    target.listPosition ??
                    null
            }
        };
    }


    function parseTraitProgress(
        text
    ) {

        const match =
            String(
                text ||
                ''
            ).match(
                /(\d+)\s*\/\s*(\d+)/
            );


        if (!match)
            return null;


        const current =
            Number(
                match[1]
            );

        const max =
            Number(
                match[2]
            );


        if (
            !Number.isFinite(
                current
            ) ||
            !Number.isFinite(
                max
            ) ||
            max <= 0
        ) {

            return null;
        }


        return {
            current,
            max,
            full:
                current >= max
        };
    }


    function inspectTraitCompletion(
        trait
    ) {

        const sourceItems =
            Array.isArray(
                trait?.items
            )
                ? trait.items
                : [];


        /*
         * 특성 이름 기준으로 중복 제거.
         * 같은 화면의 숨은/재사용 노드가 중복으로 잡혀도
         * 실제 4개 특성만 판정하도록 한다.
         */
        const unique =
            new Map();


        for (
            const item
            of sourceItems
        ) {

            const name =
                String(
                    item?.name ||
                    ''
                ).trim();


            if (!name)
                continue;


            const progressList =
                (
                    Array.isArray(
                        item?.progressTexts
                    )
                        ? item.progressTexts
                        : []
                )
                    .map(
                        parseTraitProgress
                    )
                    .filter(
                        Boolean
                    );


            /*
             * 동일 item에서 여러 progress가 잡힌 경우
             * 가장 큰 max값을 대표 progress로 사용.
             */
            const progress =
                progressList
                    .sort(
                        (a, b) =>
                            b.max -
                            a.max
                    )[0] ||
                null;


            const row = {
                name,
                progressText:
                    (
                        item?.progressTexts ||
                        []
                    )[0] ||
                    null,
                current:
                    progress?.current ??
                    null,
                max:
                    progress?.max ??
                    null,
                full:
                    progress?.full ===
                    true
            };


            const previous =
                unique.get(
                    name
                );


            if (
                !previous ||
                (
                    row.max != null &&
                    (
                        previous.max ==
                            null ||
                        row.max >
                            previous.max
                    )
                )
            ) {

                unique.set(
                    name,
                    row
                );
            }
        }


        const items =
            [
                ...unique.values()
            ];


        const expectedCount =
            4;


        const hasAllFour =
            items.length ===
            expectedCount;


        const allFull =
            hasAllFour &&
            items.every(
                item =>
                    item.full ===
                    true
            );


        return {
            expectedCount,
            actualCount:
                items.length,
            hasAllFour,
            allFull,
            fullCount:
                items.filter(
                    item =>
                        item.full ===
                        true
                ).length,
            items
        };
    }


    /*
     * 상세 조사 대상 영웅 화이트리스트.
     *
     * 국제화를 위해 영웅 이름은 코드에 저장하지 않는다.
     * heroIdCandidate만 판정 기준으로 사용한다.
     *
     * 스킬/특성/타이탄/각성 상세 진입은 아래 ID만 수행한다.
     */
    const TARGET_DETAIL_HERO_IDS =
        new Set([
        169,
        174,
        170,
        172,
        173,
        165,
        234,
        241,
        240,
        239,
        232,
        237,
        334,
        338,
        332,
        337,
        336,
        333
        ]);


    async function collectDetailedHeroSaleData(
        heroItems,
        options = {}
    ) {

        const allKnown =
            Array.isArray(
                heroItems
            )
                ? heroItems
                : [];


        /*
         * 상세 조사는 heroId 화이트리스트에 포함된 영웅만 수행한다.
         *
         * rarity/name을 상세 조사 대상 판정에 사용하지 않는다.
         * 따라서 클라이언트 언어가 바뀌어도 대상 영웅이 바뀌지 않는다.
         */
        const known =
            allKnown.filter(
                item =>
                    TARGET_DETAIL_HERO_IDS.has(
                        Number(
                            item?.heroIdCandidate
                        )
                    )
            );


        const raritySkipped = {
            sr:
                allKnown.filter(
                    item =>
                        item?.rarity ===
                        'SR'
                ).length,

            r:
                allKnown.filter(
                    item =>
                        item?.rarity ===
                        'R'
                ).length,

            nonSsr:
                allKnown.filter(
                    item =>
                        item?.rarity ===
                        'NON_SSR'
                ).length,

            unknown:
                allKnown.filter(
                    item =>
                        item?.rarity ===
                        'UNKNOWN'
                ).length
        };


        const byName =
            new Map(
                known
                    .filter(
                        item =>
                            item?.name
                    )
                    .map(
                        item => [
                            item.name,
                            item
                        ]
                    )
            );


        const foundTargetHeroIds =
            new Set(
                known
                    .map(
                        item =>
                            Number(
                                item?.heroIdCandidate
                            )
                    )
                    .filter(
                        Number.isFinite
                    )
            );


        const missingTargetHeroIds =
            [
                ...TARGET_DETAIL_HERO_IDS
            ]
                .filter(
                    heroId =>
                        !foundTargetHeroIds.has(
                            heroId
                        )
                );


        const targetCount =
            known.length;


        const enriched =
            new Map();

        const visited =
            new Set();


        const summary = {
            sourceHeroCount:
                allKnown.length,

            targetMode:
                'HERO_ID_WHITELIST',

            configuredTargetCount:
                TARGET_DETAIL_HERO_IDS.size,

            targetHeroIds:
                [
                    ...TARGET_DETAIL_HERO_IDS
                ],

            foundTargetHeroIds:
                [
                    ...foundTargetHeroIds
                ],

            missingTargetHeroIds,

            targetCount,

            raritySkipped,

            processedCount:
                0,
            skills: {
                available:
                    0,
                unavailable:
                    0,
                failed:
                    0,
                heroesWithSkills:
                    0,
                totalSkillCount:
                    0,
                level5PlusCount:
                    0,
                levelCounts:
                    {}
            },
            trait: {
                available:
                    0,
                unavailable:
                    0,
                skipped:
                    0,
                failed:
                    0,
                allMaxedHeroCount:
                    0
            },
            titan: {
                available:
                    0,
                unavailable:
                    0,
                skipped:
                    0,
                unknown:
                    0,
                failed:
                    0,
                equippedHeroCount:
                    0
            },
            awakening: {
                available:
                    0,
                unavailable:
                    0,
                skipped:
                    0,
                unknown:
                    0,
                failed:
                    0,
                awakenedHeroCount:
                    0
            }
        };


        const navigation = {
            openFirst:
                null,
            nextFailures:
                [],
            fallbackOpens:
                [],
            closeDetail:
                null,
            closeList:
                null
        };


        let fatalError =
            null;


        const report =
            (type, detail) => {

                try {
                    options.onProgress?.(
                        type,
                        detail
                    );
                } catch {}
            };


        try {

            const first =
                await runCollectorStepWithRetries(
                    '첫 영웅 상세 진입',
                    () =>
                        (
                            known[0]
                                ? openHeroFromListItem(
                                    known[0],
                                    {
                                        ...options,
                                        heroDetailOpenTimeout:
                                            options.heroDetailOpenTimeout ??
                                            4500,

                                        screenVisibleStableMs:
                                            options.screenVisibleStableMs ??
                                            650
                                    }
                                  )
                                : Promise.resolve({
                                    ok: false,
                                    reason:
                                        '상세 조사 대상 영웅을 찾지 못했습니다.'
                                  })
                        ),
                    {
                        maxRetries:
                            options.maxRetries ??
                            3,
                        retryDelay:
                            options.retryDelay ??
                            350
                    }
                );


            navigation.openFirst =
                first;


            if (!first.ok) {

                fatalError =
                    first.reason ||
                    '첫 영웅 상세 진입 실패';

            } else {

                for (
                    let sequence = 0;
                    sequence < targetCount;
                    sequence += 1
                ) {

                    /*
                     * 프레임 노드 identity가 바뀌는지 여부는 보지 않는다.
                     * 화면에 실제 heroName이 표시되고 같은 이름이
                     * 최소 안정시간 동안 유지되는지만 확인한다.
                     */
                    const detailReady =
                        await waitForHeroDetailReady({
                            timeout:
                                options.heroDetailVisibleTimeout ??
                                4200,

                            stableMs:
                                options.screenVisibleStableMs ??
                                650
                        });


                    if (!detailReady.ok) {

                        fatalError =
                            detailReady.reason ||
                            '영웅 상세 화면 준비 실패';

                        break;
                    }


                    const identity =
                        detailReady.identity;


                    if (!identity?.name) {

                        fatalError =
                            '현재 영웅 이름 확인 실패';

                        break;
                    }


                    /*
                     * 다음 화살표가 화이트리스트 외 영웅으로 이동한 경우
                     * 상세조사를 하지 않고 다음 미수집 대상 영웅을 목록에서 연다.
                     */
                    if (
                        !byName.has(
                            identity.name
                        )
                    ) {

                        const nonSsrFallback =
                            await openNextUnvisitedHeroFromList(
                                known,
                                visited,
                                options
                            );


                        navigation
                            .fallbackOpens
                            .push({
                                from:
                                    identity.name,
                                reason:
                                    '화이트리스트 외 영웅 상세 스킵',
                                ok:
                                    !!nonSsrFallback?.ok,
                                value:
                                    nonSsrFallback
                            });


                        if (!nonSsrFallback?.ok) {

                            fatalError =
                                nonSsrFallback?.reason ||
                                '다음 대상 영웅 목록 fallback 실패';

                            break;
                        }


                        sequence -=
                            1;

                        continue;
                    }


                    if (
                        visited.has(
                            identity.name
                        )
                    ) {

                        const repeatFallback =
                            await openNextUnvisitedHeroFromList(
                                known,
                                visited,
                                options
                            );


                        navigation
                            .fallbackOpens
                            .push({
                                from:
                                    identity.name,
                                reason:
                                    `영웅 순회가 ${identity.name}에서 반복됨`,
                                ok:
                                    !!repeatFallback?.ok,
                                value:
                                    repeatFallback
                            });


                        if (!repeatFallback?.ok) {

                            fatalError =
                                repeatFallback?.reason ||
                                `영웅 순회가 ${identity.name}에서 반복됨`;

                            break;
                        }


                        sequence -=
                            1;

                        continue;
                    }


                    visited.add(
                        identity.name
                    );


                    const base =
                        byName.get(
                            identity.name
                        ) || {
                            name:
                                identity.name,
                            level:
                                identity.level,
                            levelText:
                                identity.levelText
                        };


                    const skillStep =
                        await runCollectorStepWithRetries(
                            `${identity.name} 장착 스킬`,
                            async () =>
                                collectCurrentHeroSkills(),
                            {
                                maxRetries:
                                    options.maxRetries ??
                                    3,
                                retryDelay:
                                    options.retryDelay ??
                                    350,
                                isSuccess:
                                    value =>
                                        value?.ok ===
                                        true
                            }
                        );


                    const skills =
                        skillStep.value || {
                            ok: false,
                            available:
                                true,
                            reason:
                                skillStep.reason ||
                                '장착 스킬 수집 실패',
                            count:
                                0,
                            items:
                                []
                        };


                    skills.attempts =
                        skillStep
                            .attempts;


                    if (!skills.ok) {

                        summary.skills.failed +=
                            1;

                    } else if (
                        skills.available ===
                        false
                    ) {

                        summary.skills.unavailable +=
                            1;

                    } else {

                        summary.skills.available +=
                            1;
                    }


                    /*
                     * 스킬 판매 가치는 "몇 개 있나"보다 레벨이 중요하므로
                     * 실제 장착 스킬 level을 누적 집계한다.
                     */
                    const skillLevels =
                        (
                            Array.isArray(
                                skills?.items
                            )
                                ? skills.items
                                : []
                        )
                            .map(
                                item =>
                                    Number(
                                        item?.level
                                    )
                            )
                            .filter(
                                Number.isFinite
                            );


                    if (
                        skillLevels.length
                    ) {

                        summary.skills.heroesWithSkills +=
                            1;

                        summary.skills.totalSkillCount +=
                            skillLevels.length;


                        for (
                            const level
                            of skillLevels
                        ) {

                            const key =
                                String(
                                    level
                                );


                            summary.skills.levelCounts[key] =
                                (
                                    summary.skills.levelCounts[key] ||
                                    0
                                ) +
                                1;


                            if (
                                level >=
                                5
                            ) {

                                summary.skills.level5PlusCount +=
                                    1;
                            }
                        }
                    }


                    report(
                        'skills',
                        {
                            index:
                                sequence + 1,
                            total:
                                targetCount,
                            name:
                                identity.name,
                            count:
                                skills.count ||
                                0,
                            summary:
                                {
                                    ...summary.skills
                                }
                        }
                    );


                    /*
                     * 영웅 상세 탭 진입 조건 최적화
                     * - 특성: 5성 + 120레벨
                     * - 타이탄: 5성 + 120레벨 + 특성 4개 모두 최대치
                     * - 특성/타이탄: 5성 + 120레벨
                     * - 각성: 5성 + 120레벨 + 2번 슬롯 전속 스킬 Lv5 이상
                     *
                     * 조건 미충족 영웅은 해당 탭 자체를 누르지 않는다.
                     */
                    const heroStar =
                        Number(
                            base?.star ??
                            0
                        );


                    const heroLevel =
                        Number(
                            identity?.level ??
                            base?.level ??
                            0
                        );


                    const traitEligible =
                        heroStar === 5 &&
                        heroLevel === 120;


                    const equippedSkills =
                        Array.isArray(
                            skills?.items
                        )
                            ? skills.items
                            : [];


                    const equippedSkillLevels =
                        equippedSkills
                            .map(
                                item =>
                                    Number(
                                        item?.level ??
                                        0
                                    )
                            )
                            .filter(
                                Number.isFinite
                            );


                    const maxEquippedSkillLevel =
                        equippedSkillLevels.length
                            ? Math.max(
                                ...equippedSkillLevels
                              )
                            : 0;


                    /*
                     * 각성 조건에서 중요한 것은 "아무 스킬 Lv5+"가 아니다.
                     * 장착 스킬의 두 번째 칸(slot === 2)이 전속 스킬이며,
                     * 이 전속 스킬이 Lv5 이상이어야 각성이 존재할 수 있다.
                     */
                    const exclusiveSkill =
                        equippedSkills.find(
                            item =>
                                Number(
                                    item?.slot
                                ) ===
                                2
                        ) ||
                        null;


                    const exclusiveSkillLevel =
                        exclusiveSkill
                            ? Number(
                                exclusiveSkill.level
                              )
                            : null;


                    const exclusiveSkillLevelKnown =
                        !!exclusiveSkill &&
                        Number.isFinite(
                            exclusiveSkillLevel
                        );


                    const awakeningBaseEligible =
                        traitEligible &&
                        exclusiveSkillLevelKnown &&
                        exclusiveSkillLevel >= 5;


                    const eligibility = {
                        star:
                            heroStar,
                        level:
                            heroLevel,
                        trait: {
                            eligible:
                                traitEligible,
                            requirement:
                                '5성 · 120레벨'
                        },
                        titan: {
                            eligible:
                                false,
                            requirement:
                                '5성 · 120레벨 · 특성 4개 모두 최대치'
                        },
                        awakening: {
                            eligible:
                                false,
                            baseEligible:
                                awakeningBaseEligible,
                            requirement:
                                '5성 · 120레벨 · 2번 슬롯 전속 스킬 5레벨 이상',
                            exclusiveSkillSlot:
                                2,
                            exclusiveSkillLevelKnown,
                            exclusiveSkillLevel,
                            exclusiveSkill:
                                exclusiveSkill
                                    ? {
                                        slot:
                                            exclusiveSkill.slot,
                                        level:
                                            exclusiveSkill.level,
                                        levelText:
                                            exclusiveSkill.levelText ??
                                            null
                                      }
                                    : null,
                            maxEquippedSkillLevel
                        }
                    };


                    let traitStep =
                        null;


                    let trait =
                        null;


                    if (!traitEligible) {

                        trait = {
                            ok: true,
                            available: false,
                            skipped: true,
                            reason:
                                '특성 조건 미충족: 5성 · 120레벨 필요',
                            eligibility: {
                                star:
                                    heroStar,
                                level:
                                    heroLevel
                            },
                            items: [],
                            attempts: []
                        };

                    } else {

                        traitStep =
                            await runCollectorStepWithRetries(
                                `${identity.name} 특성`,
                                () =>
                                    collectCurrentHeroTraits({
                                        ...options,
                                        maxRetries:
                                            options.traitMaxRetries ??
                                            1
                                    }),
                                {
                                    /*
                                     * 특성 UI readiness를 수정했으므로
                                     * 실패 시 무의미한 4회 반복 대신 최대 2회만 시도.
                                     */
                                    maxRetries:
                                        options.traitMaxRetries ??
                                        1,
                                    retryDelay:
                                        options.retryDelay ??
                                        350,
                                    isSuccess:
                                        value =>
                                            value?.ok ===
                                            true
                                }
                            );


                        trait =
                            traitStep.value || {
                                ok: false,
                                available:
                                    true,
                                reason:
                                    traitStep.reason ||
                                    '특성 수집 실패'
                            };


                        trait.attempts =
                            traitStep
                                .attempts;
                    }


                    if (!trait.ok) {

                        summary.trait.failed +=
                            1;

                    } else if (
                        trait.skipped ===
                        true
                    ) {

                        summary.trait.skipped +=
                            1;

                    } else if (
                        trait.available ===
                        false
                    ) {

                        summary.trait.unavailable +=
                            1;

                    } else {

                        summary.trait.available +=
                            1;
                    }


                    report(
                        'traits',
                        {
                            index:
                                sequence + 1,
                            total:
                                targetCount,
                            name:
                                identity.name,
                            summary:
                                {
                                    ...summary.trait
                                }
                        }
                    );


                    /*
                     * 특성 판정은 3상태로 분리한다.
                     *
                     * 1) KNOWN + 데이터 있음
                     * 2) KNOWN + 실제로 비어 있음
                     * 3) UNKNOWN = 특성 수집 자체 실패
                     *
                     * UNKNOWN을 "특성 0개"로 오판하면 실제 타이탄/각성 보유 영웅을
                     * 전부 0개로 만들어버리므로 절대 empty로 취급하지 않는다.
                     */
                    const traitKnown =
                        trait?.ok ===
                        true;


                    const traitCompletion =
                        traitKnown
                            ? inspectTraitCompletion(
                                trait
                              )
                            : {
                                expectedCount:
                                    4,
                                actualCount:
                                    null,
                                hasAllFour:
                                    null,
                                allFull:
                                    null,
                                fullCount:
                                    null,
                                items:
                                    []
                              };


                    const traitHasData =
                        traitKnown &&
                        Number(
                            traitCompletion.actualCount
                        ) >
                            0;


                    const traitAllMaxed =
                        traitKnown &&
                        traitCompletion.allFull ===
                            true;


                    /*
                     * v0.9.1부터 조사 조건을 단순화한다.
                     *
                     * SSR 상세 조사 대상 중:
                     * - 특성: 5성 + 120레벨이면 조사
                     * - 타이탄: 5성 + 120레벨이면 조사
                     * - 각성: 5성 + 120레벨 +
                     *         2번 슬롯 전속 스킬 Lv5 이상일 때 조사
                     *
                     * 특성 개수/완성도는 조사 gate로 사용하지 않는다.
                     * 각성에 한해서 2번 슬롯 전속 스킬 레벨만 gate로 사용한다.
                     */
                    const titanEligible =
                        traitEligible;


                    const awakeningEligible =
                        awakeningBaseEligible;


                    eligibility.trait.known =
                        traitKnown;


                    eligibility.trait.hasData =
                        traitKnown
                            ? traitHasData
                            : null;


                    eligibility.trait.completion =
                        traitCompletion;


                    eligibility.trait.allMaxed =
                        traitKnown
                            ? traitAllMaxed
                            : null;


                    if (
                        traitAllMaxed
                    ) {

                        summary.trait.allMaxedHeroCount +=
                            1;
                    }


                    eligibility.titan.eligible =
                        titanEligible;


                    eligibility.titan.requirement =
                        '5성 · 120레벨';


                    eligibility.titan.traitGateUsed =
                        false;


                    eligibility.titan.traitKnown =
                        traitKnown;


                    eligibility.titan.traitAllMaxed =
                        traitKnown
                            ? traitAllMaxed
                            : null;


                    eligibility.titan.traitCompletion =
                        traitCompletion;


                    eligibility.awakening.eligible =
                        awakeningEligible;


                    eligibility.awakening.requirement =
                        '5성 · 120레벨 · 2번 슬롯 전속 스킬 5레벨 이상';


                    eligibility.awakening.traitGateUsed =
                        false;


                    eligibility.awakening.skillLevelGateUsed =
                        true;


                    eligibility.awakening.exclusiveSkillSlot =
                        2;


                    eligibility.awakening.exclusiveSkillLevelKnown =
                        exclusiveSkillLevelKnown;


                    eligibility.awakening.exclusiveSkillLevel =
                        exclusiveSkillLevel;


                    eligibility.awakening.traitKnown =
                        traitKnown;


                    eligibility.awakening.traitHasData =
                        traitKnown
                            ? traitHasData
                            : null;


                    eligibility.awakening.traitCompletion =
                        traitCompletion;


                    let titanStep =
                        null;


                    let titan =
                        null;


                    if (!titanEligible) {

                        titan = {
                            ok: true,
                            available: false,
                            skipped: true,
                            reason:
                                '타이탄 조건 미충족: 5성 · 120레벨 필요',
                            eligibility: {
                                star:
                                    heroStar,
                                level:
                                    heroLevel
                            },
                            slots: [],
                            attempts: []
                        };
                    } else {

                        titanStep =
                            await runCollectorStepWithRetries(
                                `${identity.name} 타이탄`,
                                () =>
                                    collectCurrentHeroTitan({
                                        ...options,
                                        maxRetries:
                                            options.maxRetries ??
                                            3
                                    }),
                                {
                                    maxRetries:
                                        options.maxRetries ??
                                        3,
                                    retryDelay:
                                        options.retryDelay ??
                                        350,
                                    isSuccess:
                                        value =>
                                            value?.ok ===
                                            true
                                }
                            );


                        titan =
                            titanStep.value || {
                                ok: false,
                                available:
                                    true,
                                reason:
                                    titanStep.reason ||
                                    '타이탄 수집 실패',
                                slots:
                                    []
                            };


                        titan.attempts =
                            titanStep
                                .attempts;
                    }


                    if (
                        titan.unknown ===
                        true
                    ) {

                        summary.titan.unknown +=
                            1;

                    } else if (!titan.ok) {

                        summary.titan.failed +=
                            1;

                    } else if (
                        titan.skipped ===
                        true
                    ) {

                        summary.titan.skipped +=
                            1;

                    } else if (
                        titan.available ===
                        false
                    ) {

                        summary.titan.unavailable +=
                            1;

                    } else {

                        summary.titan.available +=
                            1;


                        if (
                            Number(
                                titan.equippedCount ||
                                0
                            ) >
                            0
                        ) {

                            summary.titan.equippedHeroCount +=
                                1;
                        }
                    }


                    report(
                        'equipment',
                        {
                            index:
                                sequence + 1,
                            total:
                                targetCount,
                            name:
                                identity.name,
                            summary:
                                {
                                    ...summary.titan
                                }
                        }
                    );


                    let awakenStep =
                        null;


                    let awakening =
                        null;


                    if (!awakeningEligible) {

                        if (
                            traitEligible &&
                            !exclusiveSkillLevelKnown
                        ) {

                            /*
                             * 5성 120레벨인데 2번 슬롯 전속 스킬 레벨을
                             * 읽지 못한 경우 "미각성"으로 단정하지 않는다.
                             */
                            awakening = {
                                ok: false,
                                available: null,
                                skipped: false,
                                unknown: true,
                                blocked: true,
                                reason:
                                    '각성 판정 불가: 2번 슬롯 전속 스킬 레벨 확인 실패',
                                eligibility: {
                                    star:
                                        heroStar,
                                    level:
                                        heroLevel,
                                    exclusiveSkillSlot:
                                        2,
                                    exclusiveSkillLevelKnown:
                                        false,
                                    exclusiveSkillLevel:
                                        null,
                                    maxEquippedSkillLevel
                                },
                                level:
                                    null,
                                skills:
                                    [],
                                attempts:
                                    []
                            };

                        } else {

                            awakening = {
                                ok: true,
                                available: false,
                                skipped: true,
                                reason:
                                    !traitEligible
                                        ? '각성 조건 미충족: 5성 · 120레벨 필요'
                                        : `각성 조건 미충족: 2번 슬롯 전속 스킬 Lv${exclusiveSkillLevel} (<5)`,
                                eligibility: {
                                    star:
                                        heroStar,
                                    level:
                                        heroLevel,
                                    exclusiveSkillSlot:
                                        2,
                                    exclusiveSkillLevelKnown,
                                    exclusiveSkillLevel,
                                    maxEquippedSkillLevel
                                },
                                level:
                                    null,
                                skills:
                                    [],
                                attempts:
                                    []
                            };
                        }

                    } else {

                        awakenStep =
                            await runCollectorStepWithRetries(
                                `${identity.name} 각성`,
                                () =>
                                    collectCurrentHeroAwakening({
                                        ...options,
                                        maxRetries:
                                            options.maxRetries ??
                                            3
                                    }),
                                {
                                    maxRetries:
                                        options.maxRetries ??
                                        3,
                                    retryDelay:
                                        options.retryDelay ??
                                        350,
                                    isSuccess:
                                        value =>
                                            value?.ok ===
                                            true
                                }
                            );


                        awakening =
                            awakenStep.value || {
                                ok: false,
                                available:
                                    true,
                                reason:
                                    awakenStep.reason ||
                                    '각성 수집 실패',
                                skills:
                                    []
                            };


                        awakening.attempts =
                            awakenStep
                                .attempts;
                    }


                    if (
                        awakening.unknown ===
                        true
                    ) {

                        summary.awakening.unknown +=
                            1;

                    } else if (!awakening.ok) {

                        summary.awakening.failed +=
                            1;

                    } else if (
                        awakening.skipped ===
                        true
                    ) {

                        summary.awakening.skipped +=
                            1;

                    } else if (
                        awakening.available ===
                        false
                    ) {

                        summary.awakening.unavailable +=
                            1;

                    } else {

                        summary.awakening.available +=
                            1;


                        const awakened =
                            Number(
                                awakening.level ||
                                0
                            ) >
                                0
                            ||
                            (
                                awakening.skills ||
                                []
                            ).some(
                                skill =>
                                    Number(
                                        skill?.currentStage ||
                                        0
                                    ) >
                                    0
                            );


                        awakening.awakened =
                            awakened;


                        if (awakened) {

                            summary.awakening.awakenedHeroCount +=
                                1;
                        }
                    }


                    report(
                        'awakening',
                        {
                            index:
                                sequence + 1,
                            total:
                                targetCount,
                            name:
                                identity.name,
                            summary:
                                {
                                    ...summary.awakening
                                }
                        }
                    );


                    enriched.set(
                        identity.name,
                        {
                            ...base,
                            detail: {
                                name:
                                    identity.name,
                                tags:
                                    identity.tags ||
                                    [],
                                tag:
                                    identity.tag ||
                                    null,
                                level:
                                    identity.level,
                                levelText:
                                    identity.levelText,
                                power:
                                    identity.power,
                                powerText:
                                    identity.powerText
                            },
                            eligibility,
                            skills,
                            traits:
                                trait,
                            titan,
                            awakening
                        }
                    );


                    summary.processedCount =
                        enriched.size;


                    report(
                        'heroes',
                        {
                            index:
                                sequence + 1,
                            total:
                                targetCount,
                            name:
                                identity.name,
                            processed:
                                enriched.size
                        }
                    );


                    if (
                        enriched.size >=
                        targetCount
                    )
                        break;


                    const nextStep =
                        await runCollectorStepWithRetries(
                            `${identity.name} 다음 영웅`,
                            () =>
                                moveToNextHeroDetail(
                                    identity.name,
                                    {
                                        timeout:
                                            options.heroChangeTimeout ??
                                            2600,

                                        stableMs:
                                            options.screenVisibleStableMs ??
                                            650
                                    }
                                ),
                            {
                                /*
                                 * 동일 화면 반복을 막기 위해 화살표는 한 번만 시도.
                                 */
                                maxRetries:
                                    0,
                                retryDelay:
                                    0
                            }
                        );


                    if (!nextStep.ok) {

                        navigation
                            .nextFailures
                            .push({
                                hero:
                                    identity.name,
                                attempts:
                                    nextStep.attempts,
                                reason:
                                    nextStep.reason,
                                fallback:
                                    true
                            });


                        const fallbackStep =
                            await runCollectorStepWithRetries(
                                `${identity.name} 목록 fallback`,
                                () =>
                                    openNextUnvisitedHeroFromList(
                                        known,
                                        visited,
                                        {
                                            ...options,
                                            heroDetailOpenTimeout:
                                                options.heroDetailOpenTimeout ??
                                                4500
                                        }
                                    ),
                                {
                                    maxRetries:
                                        1,
                                    retryDelay:
                                        options.retryDelay ??
                                        350,
                                    isSuccess:
                                        value =>
                                            value?.ok ===
                                            true
                                }
                            );


                        navigation
                            .fallbackOpens
                            .push({
                                from:
                                    identity.name,
                                ok:
                                    fallbackStep.ok,
                                reason:
                                    fallbackStep.reason,
                                value:
                                    fallbackStep.value ||
                                    null,
                                attempts:
                                    fallbackStep.attempts
                            });


                        if (!fallbackStep.ok) {

                            fatalError =
                                fallbackStep.reason ||
                                nextStep.reason ||
                                '다음 미수집 영웅 목록 fallback 실패';

                            break;
                        }
                    }
                }
            }

        } catch (
            error
        ) {

            fatalError =
                error?.message ||
                String(
                    error
                );

            recordError(
                '영웅 상세 전체 수집',
                error
            );

        } finally {

            /*
             * 남아 있을 수 있는 하위 팝업부터 역순으로 정리.
             */
            for (
                const panelName
                of [
                    'HeroAwakenSkillUpPop',
                    'HeroEquipDetailPop',
                    'HeroEquipWearPanel',
                    'HeroStrengthenPanelNew'
                ]
            ) {

                if (
                    findActiveNodeByName(
                        panelName
                    )
                ) {

                    await closeSalePanelByName(
                        panelName
                    );
                }
            }


            if (
                findHeroDetailRoot()
            ) {

                navigation.closeDetail =
                    await closeSalePanelByName(
                        'HeroDetailPopup2024',
                        {
                            timeout:
                                options.finalCloseTimeout ??
                                2600
                        }
                    );
            } else {

                navigation.closeDetail = {
                    ok: true,
                    alreadyClosed:
                        true
                };
            }


            if (
                findHeroListRoot()
            ) {

                navigation.closeList =
                    await closeSalePanelByName(
                        'HeroListPopup2023',
                        {
                            timeout:
                                options.finalCloseTimeout ??
                                2600
                        }
                    );
            } else {

                navigation.closeList = {
                    ok: true,
                    alreadyClosed:
                        true
                };
            }
        }


        /*
         * 상세 순회 순서와 영웅 목록의 정렬 순서는 다를 수 있으므로
         * 최종 출력은 최초 목록 순서에 다시 맞춘다.
         */
        const items =
            known.map(
                item =>
                    enriched.get(
                        item.name
                    ) || {
                        ...item,
                        detail:
                            null,
                        skills: {
                            ok: false,
                            available:
                                null,
                            reason:
                                '상세 미수집',
                            count:
                                0,
                            items:
                                []
                        },
                        traits: {
                            ok: false,
                            available:
                                null,
                            reason:
                                '상세 미수집'
                        },
                        titan: {
                            ok: false,
                            available:
                                null,
                            reason:
                                '상세 미수집',
                            slots:
                                []
                        },
                        awakening: {
                            ok: false,
                            available:
                                null,
                            reason:
                                '상세 미수집',
                            skills:
                                []
                        }
                    }
            );


        const complete =
            targetCount ===
                0 ||
            enriched.size >=
                targetCount;


        const closed =
            !!navigation.closeDetail
                ?.ok &&
            !!navigation.closeList
                ?.ok;


        const qualityOk =
            summary.skills.failed ===
                0 &&
            summary.trait.failed ===
                0 &&
            summary.titan.failed ===
                0 &&
            summary.titan.unknown ===
                0 &&
            summary.awakening.failed ===
                0 &&
            summary.awakening.unknown ===
                0;


        /*
         * 영웅 상세 수집 성공 여부와 하위 Collector 품질을 분리한다.
         *
         * ok/traversalOk:
         *   영웅 자체 순회가 끝까지 완료됐는가
         *
         * qualityOk:
         *   스킬/특성/타이탄/각성 등 하위 상세까지 모두 문제없는가
         *
         * 특성 실패 하나 때문에 영웅 전체를 실패로 표시하지 않는다.
         */
        return {
            ok:
                complete &&
                !fatalError,
            traversalOk:
                complete &&
                !fatalError,
            qualityOk,
            closed,
            fatalError,
            count:
                items.length,
            collectedCount:
                enriched.size,
            summary,
            navigation,
            items
        };
    }


    async function collectCharacterSaleData(options = {}) {
        const startedAt = Date.now();

        const maxRetries =
            Math.max(
                0,
                Math.min(
                    3,
                    Number(
                        options.maxRetries ??
                        3
                    )
                )
            );

        const retryDelay =
            Math.max(
                100,
                Number(
                    options.retryDelay ??
                    350
                )
            );

        const notify =
            (key, status, detail = null) => {
                try {
                    options.onProgress?.({
                        key,
                        status,
                        detail,
                        at: Date.now()
                    });
                } catch {}
            };

        /*
         * 프로필이 실제로 열린 시점에 기본 Label을 먼저 확보한다.
         * 따라서 UI의 '프로필 기본 정보' 완료도 전체 8개 탭이 끝난 뒤가 아니라
         * 프로필 화면이 준비된 즉시 표시된다.
         */
        let headerLabels = [];
        let basicCandidates = {
            nickname: [],
            server: [],
            level: [],
            vip: [],
            power: []
        };
        let profileReady = false;

        notify(
            'profileBasic',
            'running'
        );

        const suppliedProfileOptions =
            options.profile &&
            typeof options.profile === 'object'
                ? options.profile
                : options;

        const profileOptions = {
            ...suppliedProfileOptions,

            maxRetries,

            retryDelay,

            onProgress:
                event => {

                    /*
                     * 기존 사용자가 profile.onProgress를 별도로 넘겼다면 같이 전달.
                     */
                    try {
                        suppliedProfileOptions
                            ?.onProgress
                            ?.(event);
                    } catch {}

                    if (
                        event?.type ===
                        'profile-ready'
                    ) {
                        profileReady = true;

                        headerLabels =
                            collectProfileHeaderLabels();

                        basicCandidates =
                            classifyProfileHeaderLabels(
                                headerLabels
                            );

                        notify(
                            'profileBasic',
                            'done',
                            {
                                labelCount:
                                    headerLabels.length
                            }
                        );

                        return;
                    }

                    if (
                        event?.type ===
                            'profile-open-retry'
                    ) {

                        notify(
                            'profileBasic',
                            'running',
                            {
                                attempt:
                                    event.attempt,
                                maxAttempts:
                                    event.maxAttempts,
                                reason:
                                    event.reason
                            }
                        );

                        return;
                    }


                    if (
                        event?.type ===
                            'tab-retry'
                    ) {

                        notify(
                            event.toggle,
                            'running',
                            {
                                index:
                                    event.index,

                                total:
                                    event.total,

                                label:
                                    event.label,

                                attempt:
                                    event.attempt,

                                maxAttempts:
                                    event.maxAttempts,

                                reason:
                                    event.reason
                            }
                        );

                        return;
                    }


                    if (
                        event?.type ===
                        'tab-start'
                    ) {
                        notify(
                            event.toggle,
                            'running',
                            {
                                index:
                                    event.index,

                                total:
                                    event.total,

                                label:
                                    event.label
                            }
                        );

                        return;
                    }

                    if (
                        event?.type ===
                        'tab-complete'
                    ) {
                        notify(
                            event.toggle,
                            event.ok
                                ? 'done'
                                : 'error',
                            {
                                index:
                                    event.index,

                                total:
                                    event.total,

                                label:
                                    event.label,

                                ownedCount:
                                    saleOwnedProfileItems(
                                        event.toggle,
                                        event.data
                                            ?.items
                                    ).length,

                                rawOwnedCount:
                                    event.data
                                        ?.ownedCount ??
                                    null,

                                attempts:
                                    event.data
                                        ?.attempts
                                        ?.length ??
                                    1
                            }
                        );
                    }
                }
        };

        const profileData =
            await profileModule.collectAll(
                profileOptions
            );

        /*
         * 프로필 진입 자체가 실패한 경우에는 profile-ready가 오지 않는다.
         */
        if (!profileReady) {
            notify(
                'profileBasic',
                'error',
                {
                    reason:
                        profileData?.reason ||
                        profileData?.detail?.reason ||
                        '프로필 화면 준비 실패'
                }
            );
        }

        /*
         * 방어적으로 마지막 시점에도 Label을 확보한다.
         */
        if (
            profileReady &&
            !headerLabels.length
        ) {
            headerLabels =
                collectProfileHeaderLabels();

            basicCandidates =
                classifyProfileHeaderLabels(
                    headerLabels
                );
        }

        /*
         * 프로필 수집이 끝났으면 프로필을 닫고 영웅 목록으로 이동한다.
         * 닫기 / 영웅 화면 진입 / 영웅 목록 수집 각각 실패 시
         * 최초 시도 이후 최대 3회 재시도한다.
         */
        /*
         * 프로필 수집이 실패했다면 화면을 닫지 않는다.
         * 오류 화면을 그대로 남겨 진단 가능하게 하고,
         * 영웅 단계로도 진행하지 않는다.
         */
        const profileCollectOk =
            !!profileData?.ok;


        const profileFailureReason =
            profileData?.reason ||
            profileData?.detail?.reason ||
            (
                profileCollectOk
                    ? null
                    : '프로필 수집 실패'
            );


        const profileCloseStep =
            profileCollectOk
                ? await runCollectorStepWithRetries(
                    '프로필 닫기',
                    async () => {

                        if (
                            !findProfileRoot()
                        ) {

                            return {
                                ok: true,
                                alreadyClosed:
                                    true
                            };
                        }


                        return closeOwnProfile({
                            timeout:
                                options
                                    .profileCloseTimeout ??
                                3000
                        });
                    },
                    {
                        maxRetries,
                        retryDelay
                    }
                )
                : {
                    ok: false,
                    skipped:
                        true,
                    reason:
                        profileFailureReason,
                    value: {
                        ok: false,
                        skipped:
                            true,
                        reason:
                            profileFailureReason
                    },
                    attempts: []
                };


        let heroOpenStep =
            {
                ok: false,
                value: null,
                attempts: [],
                reason:
                    profileCloseStep.ok
                        ? '영웅 화면 진입 전'
                        : (
                            !profileCollectOk
                                ? `프로필 수집 실패: ${profileFailureReason}`
                                : '프로필 닫기 실패'
                          )
            };

        let heroCollectStep =
            {
                ok: false,
                value: {
                    ok: false,
                    reason:
                        profileCloseStep.ok
                            ? '영웅 조사 전'
                            : (
                                !profileCollectOk
                                    ? `프로필 수집 실패: ${profileFailureReason}`
                                    : '프로필 닫기 실패'
                              ),
                    count:
                        0,
                    items:
                        []
                },
                attempts: []
            };


        notify(
            'heroes',
            'running',
            {
                phase:
                    'open'
            }
        );


        if (
            profileCloseStep.ok
        ) {

            heroOpenStep =
                await runCollectorStepWithRetries(
                    '영웅 화면 진입',
                    () =>
                        openHeroListScreen({
                            timeout:
                                options
                                    .heroOpenTimeout ??
                                3500
                        }),
                    {
                        maxRetries,
                        retryDelay,
                        onRetry:
                            retry =>
                                notify(
                                    'heroes',
                                    'running',
                                    {
                                        phase:
                                            'open',
                                        attempt:
                                            retry.attempt,
                                        maxAttempts:
                                            retry.maxAttempts
                                    }
                                )
                    }
                );
        }


        if (
            heroOpenStep.ok
        ) {

            notify(
                'heroes',
                'running',
                {
                    phase:
                        'collect'
                }
            );


            heroCollectStep =
                await runCollectorStepWithRetries(
                    '영웅 목록 수집',
                    () =>
                        collectHeroListData({
                            ...options,
                            maxRetries
                        }),
                    {
                        maxRetries,
                        retryDelay,
                        isSuccess:
                            value =>
                                !!value?.ok &&
                                Number(
                                    value?.count ||
                                    0
                                ) >
                                0,
                        onRetry:
                            retry =>
                                notify(
                                    'heroes',
                                    'running',
                                    {
                                        phase:
                                            'collect',
                                        attempt:
                                            retry.attempt,
                                        maxAttempts:
                                            retry.maxAttempts
                                    }
                                )
                    }
                );
        }


        const heroData =
            heroCollectStep.value || {
                ok: false,
                reason:
                    heroCollectStep.reason ||
                    heroOpenStep.reason ||
                    '영웅 조사 실패',
                count:
                    0,
                items:
                    []
            };


        let heroDetailData = {
            ok: false,
            traversalOk:
                false,
            qualityOk:
                false,
            closed:
                false,
            count:
                heroData?.count ??
                0,
            collectedCount:
                0,
            items:
                Array.isArray(
                    heroData?.items
                )
                    ? heroData.items
                    : [],
            summary: {
                targetCount:
                    heroData?.count ??
                    0,
                processedCount:
                    0,
                skills: {
                    available: 0,
                    unavailable: 0,
                    failed: 0,
                    heroesWithSkills: 0,
                    totalSkillCount: 0,
                    level5PlusCount: 0,
                    levelCounts: {}
                },
                trait: {
                    available: 0,
                    unavailable: 0,
                    skipped: 0,
                    failed: 0,
                    allMaxedHeroCount: 0
                },
                titan: {
                    available: 0,
                    unavailable: 0,
                    skipped: 0,
                    unknown: 0,
                    failed: 0,
                    equippedHeroCount: 0
                },
                awakening: {
                    available: 0,
                    unavailable: 0,
                    skipped: 0,
                    unknown: 0,
                    failed: 0,
                    awakenedHeroCount: 0
                }
            },
            navigation: {},
            fatalError:
                heroCollectStep.ok
                    ? '영웅 상세 조사 전'
                    : '영웅 목록 수집 실패'
        };


        if (
            heroCollectStep.ok &&
            Array.isArray(
                heroData?.items
            ) &&
            heroData.items.length
        ) {

            notify(
                'skills',
                'running'
            );

            notify(
                'traits',
                'running'
            );

            notify(
                'equipment',
                'running'
            );

            notify(
                'awakening',
                'running'
            );


            heroDetailData =
                await collectDetailedHeroSaleData(
                    heroData.items,
                    {
                        ...options,
                        maxRetries,
                        retryDelay,

                        onProgress:
                            (key, detail) => {

                                notify(
                                    key,
                                    'running',
                                    detail
                                );
                            }
                    }
                );


            const skillSummary =
                heroDetailData.summary
                    ?.skills ||
                {};


            const skillLevelEntries =
                Object.entries(
                    skillSummary.levelCounts ||
                    {}
                )
                    .map(
                        ([level, count]) => [
                            Number(level),
                            Number(count)
                        ]
                    )
                    .filter(
                        ([level, count]) =>
                            Number.isFinite(level) &&
                            Number.isFinite(count) &&
                            count >
                                0
                    )
                    .sort(
                        (a, b) =>
                            b[0] -
                            a[0]
                    );


            const skillLevelText =
                skillLevelEntries.length
                    ? skillLevelEntries
                        .map(
                            ([level, count]) =>
                                `Lv${level} ${count}개`
                        )
                        .join(
                            ' · '
                        )
                    : '레벨 데이터 없음';


            notify(
                'skills',
                skillSummary.failed
                    ? 'error'
                    : 'done',
                {
                    displayText:
                        skillLevelText,
                    ...skillSummary
                }
            );


            const traitSummary =
                heroDetailData.summary
                    ?.trait ||
                {};


            notify(
                'traits',
                traitSummary.failed
                    ? 'error'
                    : 'done',
                {
                    displayText:
                        `조사 ${traitSummary.available || 0}명 · 4/4 MAX ${traitSummary.allMaxedHeroCount || 0}명` +
                        (
                            traitSummary.failed
                                ? ` · 실패 ${traitSummary.failed}명`
                                : ''
                        ),
                    ...traitSummary
                }
            );


            const titanSummary =
                heroDetailData.summary
                    ?.titan ||
                {};


            notify(
                'equipment',
                (
                    titanSummary.failed ||
                    titanSummary.unknown
                )
                    ? 'error'
                    : 'done',
                {
                    displayText:
                        `장착 ${titanSummary.equippedHeroCount || 0}명` +
                        (
                            titanSummary.unknown
                                ? ` · 판정불가 ${titanSummary.unknown}명`
                                : ''
                        ),
                    ...titanSummary
                }
            );


            const awakeningSummary =
                heroDetailData.summary
                    ?.awakening ||
                {};


            notify(
                'awakening',
                (
                    awakeningSummary.failed ||
                    awakeningSummary.unknown
                )
                    ? 'error'
                    : 'done',
                {
                    displayText:
                        `각성 ${awakeningSummary.awakenedHeroCount || 0}명` +
                        (
                            awakeningSummary.unknown
                                ? ` · 판정불가 ${awakeningSummary.unknown}명`
                                : ''
                        ),
                    ...awakeningSummary
                }
            );
        }


        notify(
            'heroes',
            heroCollectStep.ok &&
            heroDetailData.traversalOk
                ? 'done'
                : 'error',
            {
                ownedCount:
                    heroDetailData?.collectedCount ??
                    heroData?.count ??
                    0,

                unit:
                    '명',

                displayText:
                    `${heroDetailData?.collectedCount ?? 0}명 수집 완료`,

                count:
                    heroData?.count ??
                    0,

                detailCollectedCount:
                    heroDetailData?.collectedCount ??
                    0,

                openAttempts:
                    heroOpenStep
                        ?.attempts
                        ?.length ??
                    0,

                collectAttempts:
                    heroCollectStep
                        ?.attempts
                        ?.length ??
                    0,

                reason:
                    heroDetailData?.fatalError ||
                    heroData?.reason ||
                    heroCollectStep?.reason ||
                    heroOpenStep?.reason ||
                    null
            }
        );


        const saleData = {
            /*
             * 전체 수집 성공은 핵심 구조(프로필 + 영웅 목록 + 영웅 순회) 기준.
             * 하위 상세 품질 문제는 qualityOk 및 각 세부 항목에서 별도 표현한다.
             */
            ok:
                !!profileData?.ok &&
                !!heroCollectStep?.ok &&
                !!heroDetailData?.traversalOk,

            qualityOk:
                !!heroDetailData?.qualityOk,

            schemaVersion:
                SALE_SCHEMA_VERSION,

            collectedAt:
                new Date().toISOString(),

            elapsedMs:
                Date.now() - startedAt,

            source: {
                version:
                    VERSION,

                navigatorVersion:
                    VERSION,

                profileCollectorVersion:
                    VERSION,

                heroCollectorVersion:
                    VERSION,

                schemaVersion:
                    VERSION,

                integrationVersion:
                    VERSION
            },

            account: {
                nickname: null,
                server: null,
                level: null,
                vip: null,
                power: null,

                candidates:
                    basicCandidates
            },

            profile:
                normalizeSaleProfile(
                    profileData
                ),

            heroes: {
                ok:
                    !!heroCollectStep?.ok &&
                    !!heroDetailData?.traversalOk,

                detailOk:
                    !!heroDetailData?.traversalOk,

                detailQualityOk:
                    !!heroDetailData?.qualityOk,

                closed:
                    !!heroDetailData?.closed,

                count:
                    heroData?.count ??
                    0,

                collectedCount:
                    heroDetailData
                        ?.collectedCount ??
                    0,

                items:
                    Array.isArray(
                        heroDetailData?.items
                    )
                        ? heroDetailData.items
                        : (
                            Array.isArray(
                                heroData?.items
                            )
                                ? heroData.items
                                : []
                          ),

                detailSummary:
                    heroDetailData
                        ?.summary ||
                    null,

                fatalError:
                    heroDetailData
                        ?.fatalError ??
                    null,

                detailQualityIssues: {
                    skillsFailed:
                        heroDetailData?.summary?.skills?.failed ??
                        0,
                    traitsFailed:
                        heroDetailData?.summary?.trait?.failed ??
                        0,
                    titanUnknown:
                        heroDetailData?.summary?.titan?.unknown ??
                        0,
                    awakeningUnknown:
                        heroDetailData?.summary?.awakening?.unknown ??
                        0
                },

                scrollSupported:
                    !!heroData?.scrollSupported,

                samples:
                    heroData?.samples ||
                    [],

                navigation: {
                    profileClose:
                        profileCloseStep,

                    heroOpen:
                        heroOpenStep,

                    heroCollectAttempts:
                        heroCollectStep
                            ?.attempts ||
                        [],

                    heroDetails:
                        heroDetailData
                            ?.navigation ||
                        null
                }
            },

            diagnostics: {
                profileHeaderLabels:
                    headerLabels,

                profileOk:
                    !!profileData?.ok,

                profileStage:
                    profileData?.stage ||
                    null,

                profileError:
                    profileData?.reason ||
                    profileData?.detail?.reason ||
                    null,

                profileCloseSkipped:
                    !!profileCloseStep?.skipped,

                heroOk:
                    !!heroCollectStep?.ok,

                heroDetailTraversalOk:
                    !!heroDetailData
                        ?.traversalOk,

                heroDetailQualityOk:
                    !!heroDetailData
                        ?.qualityOk,

                heroDetailStructuralOk:
                    !!heroDetailData
                        ?.traversalOk,

                heroTabsClosed:
                    !!heroDetailData
                        ?.closed,

                heroDetailFatalError:
                    heroDetailData
                        ?.fatalError ??
                    null,

                heroDetailCollectedCount:
                    heroDetailData
                        ?.collectedCount ??
                    0,

                retryPolicy: {
                    maxRetries,
                    maxAttempts:
                        maxRetries + 1,
                    retryDelay
                }
            },

            pendingCollectors: [
                'inventory'
            ]
        };

        window.TOPWAR_CHARACTER_SALE_DATA =
            saleData;

        console.log(
            '[TOPWAR_CHARACTER_SALE] 수집 완료',
            saleData
        );

        return saleData;
    }

    function getCharacterSaleData() {
        return window.TOPWAR_CHARACTER_SALE_DATA || null;
    }

    async function copyTextToClipboard(text) {
        const value = String(text ?? '');

        try {
            if (navigator.clipboard?.writeText) {
                await navigator.clipboard.writeText(value);
                return { ok: true, method: 'clipboard' };
            }
        } catch {}

        try {
            const textarea = document.createElement('textarea');
            textarea.value = value;
            textarea.style.cssText =
                'position:fixed;left:-10000px;top:-10000px;opacity:0';

            document.body.appendChild(textarea);
            textarea.focus();
            textarea.select();

            const ok = document.execCommand?.('copy') === true;
            textarea.remove();

            return {
                ok,
                method: 'execCommand',
                reason: ok ? undefined : '복사 명령 실패'
            };
        } catch (error) {
            return {
                ok: false,
                reason: error?.message || String(error)
            };
        }
    }

    async function copyCharacterSaleJson() {
        const data = getCharacterSaleData();

        if (!data) {
            return {
                ok: false,
                reason: '먼저 판매 정보를 수집하세요.'
            };
        }

        const copied =
            await copyTextToClipboard(
                JSON.stringify(
                    data,
                    null,
                    2
                )
            );

        return {
            ...copied,
            data
        };
    }

    function inspectCharacterSaleLabels() {
        const labels = collectProfileHeaderLabels();

        return {
            ok: !!profileModule.findProfileRoot(),
            labels,
            candidates:
                classifyProfileHeaderLabels(
                    labels
                )
        };
    }


    /* ============================================================
     * HERO TEXT INSPECTOR
     *
     * 영웅 Collector 구현 전 조사용.
     * 이미지/Sprite는 수집하지 않는다.
     *
     * 수집 대상:
     * - 현재 활성 화면의 cc.Label / cc.RichText
     * - Node 경로
     * - 해당 Node의 Component 이름
     * - Hero/General/Commander 계열 경로 후보
     * - 영웅 관련 버튼 이벤트 후보
     *
     * 결과:
     *   window.TOPWAR_HERO_TEXT_INSPECTION
     * ============================================================ */

    const HERO_TEXT_HINT =
        /(hero|general|commander)/i;


    /*
     * 조사 중 게임 화면 오조작 방지용 보호기.
     * 화면 전체를 덮어 클릭/터치를 차단하고, 보호기 내부의 중지 버튼만 허용한다.
     */
    let activeInspectionGuard =
        null;


    function openInspectionGuard(
        options = {}
    ) {

        if (
            activeInspectionGuard
        ) {

            try {
                if (
                    activeInspectionGuard.element &&
                    typeof activeInspectionGuard.element.remove === 'function'
                ) {
                    activeInspectionGuard.element.remove();
                }
            } catch {}

            activeInspectionGuard =
                null;
        }


        const guard = {
            cancelled:
                false,

            element:
                null,

            message:
                null,

            stopButton:
                null
        };


        const overlay =
            document.createElement(
                'div'
            );

        overlay.style.cssText = [
            'position:fixed',
            'inset:0',
            'z-index:2147483647',
            'display:flex',
            'align-items:center',
            'justify-content:center',
            'background:rgba(0,0,0,.62)',
            'backdrop-filter:blur(2px)',
            'pointer-events:auto',
            'touch-action:none',
            'user-select:none'
        ].join(';');


        const box =
            document.createElement(
                'div'
            );

        box.style.cssText = [
            'min-width:280px',
            'max-width:min(90vw,460px)',
            'padding:18px',
            'border-radius:12px',
            'border:1px solid rgba(255,255,255,.22)',
            'background:#171b1d',
            'box-shadow:0 12px 40px rgba(0,0,0,.55)',
            'color:#fff',
            'font-family:Arial,sans-serif',
            'text-align:center'
        ].join(';');

        overlay.appendChild(
            box
        );


        const title =
            document.createElement(
                'div'
            );

        title.textContent =
            options.title ||
            '정보 조사 중';

        title.style.cssText =
            'font-size:16px;font-weight:700;margin-bottom:10px';

        box.appendChild(
            title
        );


        const spinner =
            document.createElement(
                'div'
            );

        spinner.style.cssText = [
            'width:28px',
            'height:28px',
            'margin:4px auto 12px',
            'border:3px solid #555',
            'border-top-color:#ddd',
            'border-radius:50%',
            'animation:topwar-sale-spin .75s linear infinite'
        ].join(';');

        box.appendChild(
            spinner
        );


        const message =
            document.createElement(
                'div'
            );

        message.textContent =
            options.message ||
            '조사 중에는 게임 화면 클릭이 차단됩니다.';

        message.style.cssText =
            'font-size:12px;line-height:1.55;color:#d8d8d8;margin-bottom:14px;white-space:pre-line';

        box.appendChild(
            message
        );


        const stopButton =
            document.createElement(
                'button'
            );

        stopButton.type =
            'button';

        stopButton.textContent =
            '조사 중지';

        stopButton.style.cssText = [
            'min-width:120px',
            'height:36px',
            'border:1px solid #b65b5b',
            'border-radius:7px',
            'background:#733939',
            'color:#fff',
            'font-weight:700',
            'cursor:pointer'
        ].join(';');

        box.appendChild(
            stopButton
        );


        stopButton.addEventListener(
            'click',
            event => {

                event.preventDefault();
                event.stopPropagation();

                if (
                    guard.cancelled
                )
                    return;


                guard.cancelled =
                    true;

                stopButton.disabled =
                    true;

                stopButton.textContent =
                    '중지 요청됨';

                message.textContent =
                    '현재 조사 단계를 안전하게 중지하고 있습니다...';
            }
        );


        /*
         * 오버레이 자체가 게임 Canvas 위를 덮기 때문에 일반 클릭/터치는 여기서 끝난다.
         * 우클릭 메뉴도 막아서 조사 중 실수로 게임 조작이 들어가는 것을 방지한다.
         */
        overlay.addEventListener(
            'contextmenu',
            event => {
                event.preventDefault();
            }
        );


        document.body.appendChild(
            overlay
        );


        guard.element =
            overlay;

        guard.message =
            message;

        guard.stopButton =
            stopButton;


        activeInspectionGuard =
            guard;


        return guard;
    }


    function closeInspectionGuard(
        guard
    ) {

        if (!guard)
            return;


        try {
            if (
                guard.element &&
                typeof guard.element.remove === 'function'
            ) {
                guard.element.remove();
            }
        } catch {}


        if (
            activeInspectionGuard ===
            guard
        ) {

            activeInspectionGuard =
                null;
        }
    }


    function stopActiveInspection() {

        if (
            !activeInspectionGuard
        ) {

            return {
                ok: false,
                reason:
                    '현재 진행 중인 조사가 없습니다.'
            };
        }


        activeInspectionGuard.cancelled =
            true;


        if (
            activeInspectionGuard
                .stopButton
        ) {

            activeInspectionGuard
                .stopButton
                .disabled =
                true;

            activeInspectionGuard
                .stopButton
                .textContent =
                '중지 요청됨';
        }


        if (
            activeInspectionGuard
                .message
        ) {

            activeInspectionGuard
                .message
                .textContent =
                '현재 조사 단계를 안전하게 중지하고 있습니다...';
        }


        return {
            ok: true
        };
    }


    async function inspectionYield() {

        await new Promise(
            resolve =>
                setTimeout(
                    resolve,
                    0
                )
        );
    }


    function activeComponentNames(node) {

        const names =
            [];

        try {

            for (
                const component
                of (
                    node?._components ||
                    []
                )
            ) {

                const name =
                    componentName(
                        component
                    );

                if (
                    name &&
                    !names.includes(
                        name
                    )
                ) {

                    names.push(
                        name
                    );
                }
            }

        } catch {}


        return names;
    }


    function readNodeTextComponents(node) {

        const rows =
            [];


        try {

            const label =
                (
                    node &&
                    typeof node.getComponent === 'function' &&
                    window.cc &&
                    window.cc.Label
                )
                    ? node.getComponent(window.cc.Label)
                    : null;

            const value =
                String(
                    label?.string ??
                    ''
                ).trim();

            if (value) {

                rows.push({
                    type:
                        'cc.Label',

                    text:
                        value
                });
            }

        } catch {}


        try {

            const rich =
                (
                    node &&
                    typeof node.getComponent === 'function' &&
                    window.cc &&
                    window.cc.RichText
                )
                    ? node.getComponent(window.cc.RichText)
                    : null;

            const value =
                String(
                    rich?.string ??
                    ''
                ).trim();

            if (value) {

                rows.push({
                    type:
                        'cc.RichText',

                    text:
                        value
                });
            }

        } catch {}


        return rows;
    }


    function primitiveComponentFields(
        component,
        options = {}
    ) {

        const maxFields =
            Math.max(
                20,
                Math.min(
                    300,
                    Number(
                        options.maxFields ??
                        120
                    )
                )
            );


        const result = {};
        let count = 0;


        const importantKey =
            /(hero|id|level|lv|star|grade|quality|rank|awake|awaken|skill|data|info|model|exp|state|own|have|lock)/i;


        const put =
            (key, value) => {

                if (
                    count >=
                    maxFields
                )
                    return;


                if (
                    value == null ||
                    typeof value === 'string' ||
                    typeof value === 'number' ||
                    typeof value === 'boolean'
                ) {

                    result[key] =
                        value;

                    count += 1;
                }
            };


        try {

            for (
                const key
                of Object.keys(
                    component || {}
                )
            ) {

                if (
                    count >=
                    maxFields
                )
                    break;


                let value;

                try {
                    value =
                        component[key];
                } catch {
                    continue;
                }


                if (
                    value == null ||
                    typeof value === 'string' ||
                    typeof value === 'number' ||
                    typeof value === 'boolean'
                ) {

                    /*
                     * Cocos 내부 플래그가 너무 많이 섞이므로,
                     * 일반 필드 또는 영웅 관련 이름의 필드를 우선 보존한다.
                     */
                    if (
                        !key.startsWith('_') ||
                        importantKey.test(key)
                    ) {

                        put(
                            key,
                            value
                        );
                    }

                    continue;
                }


                /*
                 * data/info/model 류의 평범한 Object는 한 단계만 펼친다.
                 * Node/Component/Sprite 같은 객체는 건드리지 않는다.
                 */
                if (
                    importantKey.test(key) &&
                    typeof value === 'object' &&
                    !Array.isArray(value) &&
                    value?.constructor === Object
                ) {

                    for (
                        const [childKey, childValue]
                        of Object.entries(
                            value
                        )
                    ) {

                        if (
                            count >=
                            maxFields
                        )
                            break;


                        if (
                            childValue == null ||
                            typeof childValue === 'string' ||
                            typeof childValue === 'number' ||
                            typeof childValue === 'boolean'
                        ) {

                            put(
                                `${key}.${childKey}`,
                                childValue
                            );
                        }
                    }
                }
            }

        } catch {}


        return result;
    }


    function directChildStates(node) {

        return (
            node?.children ||
            []
        ).map(
            child => ({
                name:
                    String(
                        child?.name ||
                        ''
                    ),

                active:
                    !!child?.active,

                activeInHierarchy:
                    !!child?.activeInHierarchy
            })
        );
    }


    function findDirectChild(
        node,
        name
    ) {

        return (
            node?.children ||
            []
        ).find(
            child =>
                child?.name ===
                name
        ) || null;
    }


    function findDescendantByName(
        root,
        name
    ) {

        if (!root)
            return null;


        let found =
            null;


        walk(
            root,
            node => {

                if (
                    found ||
                    node === root
                )
                    return;


                if (
                    node?.name ===
                    name
                ) {

                    found =
                        node;
                }
            },
            {
                includeInactive:
                    true
            }
        );


        return found;
    }


    function nodeLabelText(
        node
    ) {

        if (!node)
            return '';


        try {

            const label =
                node.getComponent?.(
                    window.cc?.Label
                );


            return String(
                label?.string ??
                ''
            ).trim();

        } catch {

            return '';
        }
    }


    function parseNumberText(
        value
    ) {

        const match =
            String(
                value ||
                ''
            )
                .replace(
                    /,/g,
                    ''
                )
                .match(
                    /-?\d+(?:\.\d+)?/
                );


        return match
            ? Number(
                match[0]
              )
            : null;
    }


    function heroRarityPrimitiveEvidence(
        value,
        options = {}
    ) {

        const maxDepth =
            Math.max(
                1,
                Math.min(
                    4,
                    Number(
                        options.maxDepth ??
                        3
                    )
                )
            );


        const maxRows =
            Math.max(
                20,
                Math.min(
                    300,
                    Number(
                        options.maxRows ??
                        120
                    )
                )
            );


        const rows =
            [];

        const seen =
            new WeakSet();


        const keyPattern =
            /(rarity|quality|heroquality|hero_quality|qualityid|quality_id|rarityid|rarity_id|grade|heroGrade)/i;


        const visit =
            (
                current,
                path,
                depth
            ) => {

                if (
                    current == null ||
                    depth >
                        maxDepth ||
                    rows.length >=
                        maxRows
                )
                    return;


                if (
                    typeof current !==
                    'object'
                )
                    return;


                try {

                    if (
                        seen.has(
                            current
                        )
                    )
                        return;


                    seen.add(
                        current
                    );

                } catch {}


                let keys =
                    [];


                try {

                    keys =
                        Object.keys(
                            current
                        );

                } catch {

                    return;
                }


                for (
                    const key
                    of keys
                ) {

                    if (
                        rows.length >=
                        maxRows
                    )
                        break;


                    let child;


                    try {

                        child =
                            current[key];

                    } catch {

                        continue;
                    }


                    const childPath =
                        path
                            ? `${path}.${key}`
                            : key;


                    if (
                        keyPattern.test(
                            key
                        ) &&
                        (
                            child == null ||
                            typeof child ===
                                'string' ||
                            typeof child ===
                                'number' ||
                            typeof child ===
                                'boolean'
                        )
                    ) {

                        rows.push({
                            source:
                                'component-field',
                            key:
                                childPath,
                            value:
                                child
                        });
                    }


                    if (
                        depth <
                            maxDepth &&
                        child &&
                        typeof child ===
                            'object' &&
                        !Array.isArray(
                            child
                        )
                    ) {

                        /*
                         * Node/Component 전체 그래프를 무한히 타지 않도록
                         * 영웅/데이터/품질 관련 경로만 더 깊게 본다.
                         */
                        if (
                            /(hero|data|info|model|config|cfg|quality|rarity|grade)/i
                                .test(
                                    key
                                )
                        ) {

                            visit(
                                child,
                                childPath,
                                depth + 1
                            );
                        }
                    }
                }
            };


        visit(
            value,
            '',
            0
        );


        return rows;
    }


    function heroRaritySpriteEvidence(
        root
    ) {

        const rows =
            [];


        if (
            !root ||
            !window.cc?.Sprite
        )
            return rows;


        walk(
            root,
            node => {

                let sprite =
                    null;


                try {

                    sprite =
                        node.getComponent?.(
                            window.cc.Sprite
                        );

                } catch {}


                if (!sprite)
                    return;


                const frame =
                    sprite.spriteFrame;


                const frameName =
                    String(
                        frame?.name ||
                        frame?._name ||
                        ''
                    ).trim();


                if (
                    !frameName
                )
                    return;


                if (
                    /(ssr|rarity|quality|grade|hero.*frame|frame.*hero|orange|gold)/i
                        .test(
                            frameName
                        )
                ) {

                    rows.push({
                        source:
                            'sprite-frame',
                        node:
                            node.name ||
                            '',
                        path:
                            nodePath(
                                node
                            ),
                        value:
                            frameName
                    });
                }
            },
            {
                includeInactive:
                    true
            }
        );


        return rows;
    }


    function heroRarityTextEvidence(
        root
    ) {

        const rows =
            [];


        if (!root)
            return rows;


        walk(
            root,
            node => {

                const text =
                    nodeLabelText(
                        node
                    );


                if (
                    /^(?:SSR|SR|R)$/i
                        .test(
                            text
                        )
                ) {

                    rows.push({
                        source:
                            'label',
                        node:
                            node.name ||
                            '',
                        path:
                            nodePath(
                                node
                            ),
                        value:
                            text.toUpperCase()
                    });
                }
            },
            {
                includeInactive:
                    true
            }
        );


        return rows;
    }


    function collectHeroRarityEvidence(
        listItemNode,
        heroItemNode
    ) {

        const rows =
            [];


        for (
            const node
            of [
                listItemNode,
                heroItemNode
            ]
        ) {

            for (
                const component
                of (
                    node?._components ||
                    []
                )
            ) {

                const componentRows =
                    heroRarityPrimitiveEvidence(
                        component
                    );


                for (
                    const row
                    of componentRows
                ) {

                    rows.push({
                        ...row,
                        component:
                            componentName(
                                component
                            )
                    });
                }
            }
        }


        rows.push(
            ...heroRaritySpriteEvidence(
                heroItemNode
            )
        );


        rows.push(
            ...heroRarityTextEvidence(
                heroItemNode
            )
        );


        return rows;
    }


    function directHeroRarityFromEvidence(
        evidence
    ) {

        const values =
            (
                evidence ||
                []
            ).map(
                row =>
                    String(
                        row?.value ??
                        ''
                    ).trim()
            );


        for (
            const value
            of values
        ) {

            if (
                /(^|[^A-Z])SSR([^A-Z]|$)/i
                    .test(
                        value
                    )
            ) {

                return {
                    rarity:
                        'SSR',
                    confidence:
                        'DIRECT',
                    evidence:
                        value
                };
            }
        }


        for (
            const value
            of values
        ) {

            if (
                /(^|[^A-Z])SR([^A-Z]|$)/i
                    .test(
                        value
                    )
            ) {

                return {
                    rarity:
                        'SR',
                    confidence:
                        'DIRECT',
                    evidence:
                        value
                };
            }
        }


        for (
            const value
            of values
        ) {

            if (
                /^(?:R)$/i
                    .test(
                        value
                    )
            ) {

                return {
                    rarity:
                        'R',
                    confidence:
                        'DIRECT',
                    evidence:
                        value
                };
            }
        }


        return null;
    }


    function numericHeroQualityCandidates(
        item
    ) {

        return (
            item?.rarityEvidence ||
            []
        )
            .filter(
                row =>
                    /(quality|rarity)/i
                        .test(
                            String(
                                row?.key ||
                                ''
                            )
                        )
            )
            .map(
                row =>
                    Number(
                        row?.value
                    )
            )
            .filter(
                value =>
                    Number.isFinite(
                        value
                    )
            );
    }


    function applyHeroRarityClassification(
        items
    ) {

        const rows =
            (
                items ||
                []
            ).map(
                item => ({
                    ...item
                })
            );


        /*
         * 1. SSR/SR/R 문자열이 UI/컴포넌트에 직접 있으면 그 값을 최우선 사용.
         */
        for (
            const item
            of rows
        ) {

            const direct =
                directHeroRarityFromEvidence(
                    item.rarityEvidence
                );


            if (direct) {

                item.rarity =
                    direct.rarity;

                item.rarityConfidence =
                    direct.confidence;

                item.rarityBasis =
                    direct.evidence;
            }
        }


        /*
         * 2. quality/rarity가 숫자로만 들어있는 경우:
         *    전체 영웅에서 서로 다른 값이 2개 이상이면 가장 큰 값을 SSR로 본다.
         *
         * TopWar 내부 enum 값 자체를 하드코딩하지 않기 때문에
         * 게임 버전이 바뀌어도 최고 rarity tier를 동적으로 선택한다.
         */
        const numericValues =
            [];


        for (
            const item
            of rows
        ) {

            for (
                const value
                of numericHeroQualityCandidates(
                    item
                )
            ) {

                numericValues.push(
                    value
                );
            }
        }


        const uniqueNumericValues =
            [
                ...new Set(
                    numericValues
                )
            ].sort(
                (a, b) =>
                    a - b
            );


        const maxNumericQuality =
            uniqueNumericValues.length >=
                2
                ? uniqueNumericValues[
                    uniqueNumericValues.length -
                    1
                  ]
                : null;


        for (
            const item
            of rows
        ) {

            if (
                item.rarity
            )
                continue;


            const candidates =
                numericHeroQualityCandidates(
                    item
                );


            if (
                maxNumericQuality != null &&
                candidates.includes(
                    maxNumericQuality
                )
            ) {

                item.rarity =
                    'SSR';

                item.rarityConfidence =
                    'NUMERIC_MAX';

                item.rarityBasis =
                    maxNumericQuality;

            } else if (
                maxNumericQuality != null &&
                candidates.length
            ) {

                item.rarity =
                    'NON_SSR';

                item.rarityConfidence =
                    'NUMERIC_LOWER';

                item.rarityBasis =
                    Math.max(
                        ...candidates
                    );

            } else {

                item.rarity =
                    'UNKNOWN';

                item.rarityConfidence =
                    'NONE';

                item.rarityBasis =
                    null;
            }
        }


        const summary = {
            total:
                rows.length,

            ssr:
                rows.filter(
                    item =>
                        item.rarity ===
                        'SSR'
                ).length,

            nonSsr:
                rows.filter(
                    item =>
                        item.rarity ===
                        'NON_SSR' ||
                        item.rarity ===
                        'SR' ||
                        item.rarity ===
                        'R'
                ).length,

            unknown:
                rows.filter(
                    item =>
                        item.rarity ===
                        'UNKNOWN'
                ).length,

            numericQualityValues:
                uniqueNumericValues,

            maxNumericQuality
        };


        return {
            items:
                rows,
            summary
        };
    }


    function inspectVisibleHeroItems() {

        const root =
            scene();


        if (!root)
            return [];


        const rows = [];


        walk(
            root,
            node => {

                if (
                    !isActive(node) ||
                    node?.name !==
                        'HeroListItem2026'
                )
                    return;


                const heroNode =
                    findDirectChild(
                        node,
                        'heroNode'
                    );


                const heroItemNode =
                    findDirectChild(
                        heroNode,
                        'HeroItem2026'
                    );


                if (!heroItemNode)
                    return;


                const nameNode =
                    findDirectChild(
                        heroItemNode,
                        'name'
                    );


                let heroName = '';

                try {
                    let nameLabel = null;

                    if (
                        nameNode &&
                        typeof nameNode.getComponent === 'function' &&
                        window.cc &&
                        window.cc.Label
                    ) {

                        nameLabel =
                            nameNode.getComponent(
                                window.cc.Label
                            );
                    }


                    heroName =
                        String(
                            nameLabel &&
                            nameLabel.string != null
                                ? nameLabel.string
                                : ''
                        ).trim();
                } catch {}


                const starNode =
                    findDirectChild(
                        heroItemNode,
                        'starNode'
                    );


                const normalNode =
                    findDirectChild(
                        heroItemNode,
                        'normal'
                    );


                const frameBg =
                    findDirectChild(
                        heroItemNode,
                        'frameBg'
                    );


                const levelNode =
                    findDescendantByName(
                        normalNode,
                        'level'
                    );


                const levelText =
                    nodeLabelText(
                        levelNode
                    );


                const awakenNode =
                    findDirectChild(
                        heroItemNode,
                        'awakenNode'
                    );


                const awakenLevelNode =
                    findDescendantByName(
                        awakenNode,
                        'awakenLevel'
                    );


                const awakenLevelText =
                    nodeLabelText(
                        awakenLevelNode
                    );


                const star =
                    (
                        starNode
                            ?.children ||
                        []
                    ).filter(
                        child =>
                            child
                                ?.activeInHierarchy
                    ).length;


                const components = {};


                for (
                    const component
                    of (
                        heroItemNode
                            ?._components ||
                        []
                    )
                ) {

                    const name =
                        componentName(
                            component
                        );


                    if (
                        ![
                            'HeroItem2026',
                            'HeroAwakenNode'
                        ].includes(name)
                    )
                        continue;


                    components[name] =
                        primitiveComponentFields(
                            component
                        );
                }


                for (
                    const component
                    of (
                        node?._components ||
                        []
                    )
                ) {

                    const name =
                        componentName(
                            component
                        );


                    if (
                        name !==
                        'HeroListItem2026'
                    )
                        continue;


                    components[name] =
                        primitiveComponentFields(
                            component
                        );
                }


                const numericContainer =
                    node.parent;


                const containerName =
                    String(
                        numericContainer
                            ?.name ||
                        ''
                    );


                const rarityEvidence =
                    collectHeroRarityEvidence(
                        node,
                        heroItemNode
                    );


                rows.push({
                    heroIdCandidate:
                        /^\d+$/.test(
                            containerName
                        )
                            ? Number(
                                containerName
                              )
                            : null,

                    containerName,

                    name:
                        heroName,

                    levelText,

                    level:
                        parseNumberText(
                            levelText
                        ),

                    star,

                    awakenLevelText,

                    awakenLevel:
                        parseNumberText(
                            awakenLevelText
                        ),

                    rarityEvidence,

                    path:
                        nodePath(
                            node
                        ),

                    components,

                    starNode: {
                        childCount:
                            starNode
                                ?.children
                                ?.length ??
                            0,

                        activeChildCount:
                            (
                                starNode
                                    ?.children ||
                                []
                            ).filter(
                                child =>
                                    child
                                        ?.activeInHierarchy
                            ).length,

                        children:
                            directChildStates(
                                starNode
                            )
                    },

                    normalNode: {
                        active:
                            !!normalNode
                                ?.active,

                        activeInHierarchy:
                            !!normalNode
                                ?.activeInHierarchy,

                        children:
                            directChildStates(
                                normalNode
                            )
                    },

                    frameBg: {
                        active:
                            !!frameBg
                                ?.active,

                        activeInHierarchy:
                            !!frameBg
                                ?.activeInHierarchy
                    }
                });
            }
        );


        return rows;
    }


    async function inspectHeroScreenTexts(
        options = {}
    ) {

        const root =
            scene();


        if (!root) {

            return {
                ok: false,
                reason:
                    '현재 Cocos Scene을 찾지 못했습니다.'
            };
        }


        const isCancelled =
            () => {

                try {

                    return (
                        typeof options.shouldStop ===
                        'function'
                    )
                        ? !!options.shouldStop()
                        : false;

                } catch {

                    return false;
                }
            };


        const maxTexts =
            Math.max(
                50,
                Math.min(
                    2000,
                    Number(
                        options.maxTexts ??
                        800
                    )
                )
            );


        const texts =
            [];

        const seen =
            new Set();

        const heroCandidateNodes =
            [];


        /*
         * 기존 walk() 대신 직접 Stack을 돌려 중간중간 이벤트 루프를 양보한다.
         * 그래야 보호기의 '조사 중지' 버튼이 실제로 반응할 수 있다.
         */
        const stack =
            [root];

        let visited =
            0;


        while (
            stack.length
        ) {

            if (
                isCancelled()
            ) {

                return {
                    ok: false,
                    cancelled: true,
                    reason:
                        '사용자가 조사를 중지했습니다.',
                    partial: {
                        totalActiveTexts:
                            texts.length,
                        heroLikeTexts:
                            texts.filter(
                                row =>
                                    row.heroLike
                            ).length,
                        heroCandidateNodes:
                            heroCandidateNodes.length
                    }
                };
            }


            const node =
                stack.pop();


            if (!node)
                continue;


            const children =
                node.children ||
                [];


            for (
                let index =
                    children.length - 1;
                index >= 0;
                index -= 1
            ) {

                stack.push(
                    children[index]
                );
            }


            if (
                !isActive(
                    node
                )
            )
                continue;


            const path =
                nodePath(
                    node
                );

            const components =
                activeComponentNames(
                    node
                );


            const heroLike =
                HERO_TEXT_HINT.test(
                    [
                        node?.name || '',
                        path,
                        ...components
                    ].join(' ')
                );


            if (heroLike) {

                heroCandidateNodes.push({
                    name:
                        String(
                            node?.name ||
                            ''
                        ),

                    path,

                    components
                });
            }


            for (
                const item
                of readNodeTextComponents(
                    node
                )
            ) {

                if (
                    texts.length >=
                    maxTexts
                )
                    break;


                const key =
                    JSON.stringify([
                        path,
                        item.type,
                        item.text
                    ]);


                if (
                    seen.has(
                        key
                    )
                )
                    continue;


                seen.add(
                    key
                );


                texts.push({
                    name:
                        String(
                            node?.name ||
                            ''
                        ),

                    path,

                    type:
                        item.type,

                    text:
                        item.text,

                    components,

                    heroLike
                });
            }


            visited += 1;


            /*
             * 일정 노드마다 브라우저 이벤트 루프에 제어권을 돌려준다.
             */
            if (
                visited % 120 ===
                0
            ) {

                await inspectionYield();
            }
        }


        if (
            isCancelled()
        ) {

            return {
                ok: false,
                cancelled: true,
                reason:
                    '사용자가 조사를 중지했습니다.'
            };
        }


        const heroTexts =
            texts.filter(
                row =>
                    row.heroLike
            );


        const buttonRows =
            typeof listGameButtons ===
                'function'
                ? listGameButtons()
                : [];


        const heroButtons =
            buttonRows.filter(
                row =>
                    HERO_TEXT_HINT.test(
                        [
                            row?.name || '',
                            row?.path || '',
                            row?.text || '',
                            JSON.stringify(
                                row?.events ||
                                []
                            )
                        ].join(' ')
                    )
            );


        if (
            isCancelled()
        ) {

            return {
                ok: false,
                cancelled: true,
                reason:
                    '사용자가 조사를 중지했습니다.'
            };
        }


        /*
         * 카드 세부 정보는 텍스트 순회가 끝난 뒤 조사한다.
         */
        const heroItems =
            inspectVisibleHeroItems();


        await inspectionYield();


        if (
            isCancelled()
        ) {

            return {
                ok: false,
                cancelled: true,
                reason:
                    '사용자가 조사를 중지했습니다.'
            };
        }


        const result = {
            ok: true,

            inspectedAt:
                new Date()
                    .toISOString(),

            scene: {
                name:
                    String(
                        root?.name ||
                        ''
                    ),

                path:
                    nodePath(
                        root
                    )
            },

            summary: {
                totalActiveTexts:
                    texts.length,

                heroLikeTexts:
                    heroTexts.length,

                heroCandidateNodes:
                    heroCandidateNodes.length,

                heroRelatedButtons:
                    heroButtons.length,

                heroItems:
                    heroItems.length,

                truncated:
                    texts.length >=
                    maxTexts
            },

            heroTexts,

            allActiveTexts:
                texts,

            candidateNodes:
                heroCandidateNodes,

            relatedButtons:
                heroButtons,

            /*
             * Sprite 정보는 읽지 않고 HeroItem 컴포넌트의 primitive 데이터와
             * star/normal 노드의 활성 상태만 조사한다.
             */
            heroItems,

            notes: [
                'Sprite/이미지는 수집하지 않음',
                'HeroListItem2026 / HeroItem2026 / HeroAwakenNode primitive 필드 조사 포함',
                'starNode는 이미지 대신 자식 노드의 개수와 active 상태만 조사',
                'levelBg는 이미지 정보를 읽지 않으며 HeroItem 컴포넌트 데이터에서 레벨 후보를 찾음',
                '영웅 화면을 연 상태에서 다시 조사하면 목록/상세 구조를 비교할 수 있음'
            ]
        };


        window.TOPWAR_HERO_TEXT_INSPECTION =
            result;


        console.log(
            '[TOPWAR_HERO_TEXT_INSPECTION]',
            result
        );


        return result;
    }


    /* ============================================================
     * AWAKEN SKILL DATA INSPECTOR
     *
     * 목적:
     * - 각성 스킬의 현재/다음 단계
     * - 단계 해제 추가 효과
     * - 전속 스킬 연동 조건
     * - 승격 비용
     * - HeroAwakenSkillItem / HeroAwakenSkillUpPop 관련
     *   component 내부 config/data 후보
     *
     * 주의:
     * - 승격/레벨업 버튼을 누르지 않는다.
     * - Sprite/Texture/Asset 데이터는 수집하지 않는다.
     * - 단계 수를 5로 고정하지 않는다.
     *
     * 결과:
     *   window.TOPWAR_AWAKEN_SKILL_INSPECTION
     * ============================================================ */

    const AWAKEN_SKILL_COMPONENT_HINT =
        /(HeroAwakenSkillItem|HeroAwakenSkillUpPop|HeroDetailAwaken|Awaken.*Skill|Skill.*Awaken)/i;

    const AWAKEN_DATA_KEY_HINT =
        /(skill|awaken|stage|level|lv|max|id|config|cfg|data|info|effect|buff|value|cost|exp|need|unlock|hero|exclusive|special|quality|rank)/i;


    function isPlainObjectValue(value) {

        if (
            !value ||
            typeof value !== 'object'
        )
            return false;


        const proto =
            Object.getPrototypeOf(
                value
            );


        return (
            proto === Object.prototype ||
            proto === null
        );
    }


    function awakenSafeValue(
        value,
        depth = 0,
        state = null
    ) {

        const ctx =
            state || {
                seen:
                    new WeakSet(),

                count:
                    0,

                maxCount:
                    600
            };


        if (
            value == null ||
            typeof value === 'string' ||
            typeof value === 'number' ||
            typeof value === 'boolean'
        ) {

            if (
                typeof value === 'string' &&
                value.length > 1200
            ) {

                return (
                    value.slice(
                        0,
                        1200
                    ) +
                    '…'
                );
            }


            return value;
        }


        if (
            typeof value === 'function' ||
            typeof value === 'symbol' ||
            typeof value === 'bigint'
        ) {

            return undefined;
        }


        if (
            depth >= 3 ||
            ctx.count >=
                ctx.maxCount
        ) {

            return undefined;
        }


        if (
            typeof value !==
            'object'
        ) {

            return undefined;
        }


        try {

            if (
                ctx.seen.has(
                    value
                )
            ) {

                return '[Circular]';
            }


            ctx.seen.add(
                value
            );

        } catch {}


        const constructorName =
            String(
                value
                    ?.constructor
                    ?.name ||
                ''
            );


        /*
         * Cocos/리소스 객체는 순환 참조가 크고 이미지 정보까지 포함할 수 있으므로 제외한다.
         */
        if (
            /(Node|Component|Sprite|Texture|Asset|Material|Label|Button|Toggle|Animation|Camera|Widget|Layout|ScrollView)/i
                .test(
                    constructorName
                )
        ) {

            return undefined;
        }


        ctx.count += 1;


        if (
            Array.isArray(
                value
            )
        ) {

            const result =
                [];


            for (
                let index = 0;
                index < value.length &&
                index < 60;
                index += 1
            ) {

                const child =
                    awakenSafeValue(
                        value[index],
                        depth + 1,
                        ctx
                    );


                if (
                    child !==
                    undefined
                ) {

                    result.push(
                        child
                    );
                }
            }


            return result;
        }


        if (
            !isPlainObjectValue(
                value
            )
        ) {

            return undefined;
        }


        const result =
            {};


        for (
            const key
            of Object.keys(
                value
            )
        ) {

            if (
                ctx.count >=
                ctx.maxCount
            )
                break;


            let childValue;

            try {
                childValue =
                    value[key];
            } catch {
                continue;
            }


            /*
             * object/array는 관련성이 높은 key만 펼친다.
             * primitive는 작은 설정 객체를 놓치지 않기 위해 그대로 허용한다.
             */
            const primitive =
                (
                    childValue == null ||
                    typeof childValue === 'string' ||
                    typeof childValue === 'number' ||
                    typeof childValue === 'boolean'
                );


            if (
                !primitive &&
                !AWAKEN_DATA_KEY_HINT
                    .test(
                        key
                    )
            ) {

                continue;
            }


            const child =
                awakenSafeValue(
                    childValue,
                    depth + 1,
                    ctx
                );


            if (
                child !==
                undefined
            ) {

                result[key] =
                    child;
            }
        }


        return result;
    }


    function inspectAwakenComponent(
        component
    ) {

        const result =
            {};

        const ctx = {
            seen:
                new WeakSet(),

            count:
                0,

            maxCount:
                600
        };


        for (
            const key
            of Object.keys(
                component ||
                {}
            )
        ) {

            let value;

            try {
                value =
                    component[key];
            } catch {
                continue;
            }


            const primitive =
                (
                    value == null ||
                    typeof value === 'string' ||
                    typeof value === 'number' ||
                    typeof value === 'boolean'
                );


            /*
             * primitive 필드는 대부분 보존.
             * object/array는 각성/스킬/config/data 관련 key만 조사.
             */
            if (
                !primitive &&
                !AWAKEN_DATA_KEY_HINT
                    .test(
                        key
                    )
            ) {

                continue;
            }


            const safe =
                awakenSafeValue(
                    value,
                    0,
                    ctx
                );


            if (
                safe !==
                undefined
            ) {

                result[key] =
                    safe;
            }
        }


        return result;
    }


    function findActiveNodeByName(
        name
    ) {

        const root =
            scene();

        let found =
            null;


        if (!root)
            return null;


        walk(
            root,
            node => {

                if (
                    found ||
                    !isActive(
                        node
                    )
                )
                    return;


                if (
                    node?.name ===
                    name
                ) {

                    found =
                        node;
                }
            }
        );


        return found;
    }


    function collectTextsUnderNode(
        root,
        maxTexts = 400
    ) {

        const rows =
            [];

        const seen =
            new Set();


        if (!root)
            return rows;


        walk(
            root,
            node => {

                if (
                    rows.length >=
                    maxTexts ||
                    !isActive(
                        node
                    )
                )
                    return;


                const path =
                    nodePath(
                        node
                    );


                for (
                    const item
                    of readNodeTextComponents(
                        node
                    )
                ) {

                    const key =
                        [
                            path,
                            item.type,
                            item.text
                        ].join(
                            '\u0000'
                        );


                    if (
                        seen.has(
                            key
                        )
                    )
                        continue;


                    seen.add(
                        key
                    );


                    rows.push({
                        name:
                            String(
                                node?.name ||
                                ''
                            ),

                        path,

                        type:
                            item.type,

                        text:
                            item.text
                    });
                }
            }
        );


        return rows;
    }


    function firstTextByNodeName(
        rows,
        name
    ) {

        const found =
            (
                rows ||
                []
            ).find(
                row =>
                    row?.name ===
                    name
            );


        return (
            found?.text ||
            ''
        );
    }


    function parseStageNumber(
        value
    ) {

        const match =
            String(
                value ||
                ''
            ).match(
                /(\d+)\s*단계/
            );


        return match
            ? Number(
                match[1]
              )
            : null;
    }


    function awakenSkillPopupComponent(
        popup
    ) {

        if (!popup)
            return null;


        for (
            const component
            of (
                popup._components ||
                []
            )
        ) {

            if (
                componentName(
                    component
                ) ===
                'HeroAwakenSkillUpPop'
            ) {

                return component;
            }
        }


        return null;
    }


    function awakenStageCandidates(
        rows
    ) {

        const stages =
            [];


        for (
            const row
            of (
                rows ||
                []
            )
        ) {

            const matches =
                String(
                    row?.text ||
                    ''
                ).matchAll(
                    /(\d+)\s*단계/g
                );


            for (
                const match
                of matches
            ) {

                const stage =
                    Number(
                        match[1]
                    );


                if (
                    Number.isFinite(
                        stage
                    ) &&
                    !stages.includes(
                        stage
                    )
                ) {

                    stages.push(
                        stage
                    );
                }
            }
        }


        return stages.sort(
            (a, b) =>
                a - b
        );
    }


    function findAwakenSkillPopupCloseButtonRow() {

        if (
            typeof gameButtonRows !==
            'function'
        )
            return null;


        const matches =
            gameButtonRows().filter(
                row => {

                    if (
                        !/HeroAwakenSkillUpPop/
                            .test(
                                row?.path ||
                                ''
                            )
                    )
                        return false;


                    if (
                        !(
                            row?.name ===
                                'btn_close' ||
                            row?.name ===
                                'closeBtn'
                        )
                    )
                        return false;


                    return (
                        row?.events ||
                        []
                    ).some(
                        event =>
                            event?.handler ===
                            'onCloseClick'
                    );
                }
            );


        return (
            matches.length
                ? matches[0]
                : null
        );
    }


    function findAwakenMaxPreviewButtonRow() {

        if (
            typeof gameButtonRows !==
            'function'
        )
            return null;


        const matches =
            gameButtonRows().filter(
                row => {

                    if (
                        row?.name !==
                        'btn_max_preview_0'
                    )
                        return false;


                    if (
                        !/HeroAwakenSkillUpPop/
                            .test(
                                row?.path ||
                                ''
                            )
                    )
                        return false;


                    return (
                        row?.events ||
                        []
                    ).some(
                        event =>
                            event?.handler ===
                            'onMaxLevelPreviewClick'
                    );
                }
            );


        return (
            matches.length === 1
                ? matches[0]
                : null
        );
    }


    function awakenPopupSnapshot(
        popup
    ) {

        const rows =
            collectTextsUnderNode(
                popup,
                600
            );


        return {
            title:
                firstTextByNodeName(
                    rows,
                    'labTitle'
                ),

            currentStageText:
                firstTextByNodeName(
                    rows,
                    'lv1'
                ),

            nextStageText:
                firstTextByNodeName(
                    rows,
                    'lv2'
                ),

            stageCandidates:
                awakenStageCandidates(
                    rows
                ),

            comparisonTexts:
                rows.filter(
                    row =>
                        />>/
                            .test(
                                row?.text ||
                                ''
                            )
                ),

            unlockTexts:
                rows.filter(
                    row =>
                        /도달 시 해제|단계 해제|레벨.*해제|해제되지 않았습니다/
                            .test(
                                row?.text ||
                                ''
                            )
                ),

            extraEffects:
                rows.filter(
                    row =>
                        /skillEffectExtra/i
                            .test(
                                row?.path ||
                                ''
                            ) &&
                        row?.type ===
                            'cc.RichText'
                ),

            texts:
                rows
        };
    }


    async function inspectAwakenSkillData(
        options = {}
    ) {

        const popup =
            await saleWaitForNode(
                'HeroAwakenSkillUpPop',
                {
                    timeout:
                        options.popupVisibleTimeout ??
                        1800,

                    minVisibleMs:
                        options.screenVisibleStableMs ??
                        SALE_VISIBLE_STABLE_MS
                }
            );


        if (!popup) {

            return {
                ok: false,
                reason:
                    '각성 스킬 상세창이 열려 있지 않습니다. 각성 스킬을 하나 선택한 뒤 다시 조사하세요.'
            };
        }


        const isCancelled =
            () => {

                try {

                    return (
                        typeof options.shouldStop ===
                        'function'
                    )
                        ? !!options.shouldStop()
                        : false;

                } catch {

                    return false;
                }
            };


        const baseSnapshot =
            awakenPopupSnapshot(
                popup
            );


        const popupTexts =
            baseSnapshot.texts;


        if (
            isCancelled()
        ) {

            return {
                ok: false,
                cancelled: true,
                reason:
                    '사용자가 각성 스킬 조사를 중지했습니다.'
            };
        }


        const componentRows =
            [];

        const root =
            scene();

        const stack =
            root
                ? [root]
                : [];

        let visited =
            0;


        while (
            stack.length
        ) {

            if (
                isCancelled()
            ) {

                return {
                    ok: false,
                    cancelled: true,
                    reason:
                        '사용자가 각성 스킬 조사를 중지했습니다.',
                    partial: {
                        components:
                            componentRows.length
                    }
                };
            }


            const node =
                stack.pop();


            if (!node)
                continue;


            const children =
                node.children ||
                [];


            for (
                let index =
                    children.length - 1;
                index >= 0;
                index -= 1
            ) {

                stack.push(
                    children[index]
                );
            }


            if (
                !isActive(
                    node
                )
            )
                continue;


            const path =
                nodePath(
                    node
                );


            const nodeRelevant =
                (
                    /HeroAwakenSkillUpPop|Skillcontent1|HeroDetailAwaken/i
                        .test(
                            path
                        )
                );


            for (
                const component
                of (
                    node?._components ||
                    []
                )
            ) {

                const name =
                    componentName(
                        component
                    );


                if (
                    !name
                )
                    continue;


                if (
                    !nodeRelevant &&
                    !AWAKEN_SKILL_COMPONENT_HINT
                        .test(
                            name
                        )
                )
                    continue;


                /*
                 * cc.Label 등의 일반 UI 컴포넌트는 텍스트 목록에서 이미 확보되므로
                 * component dump에서는 사용자/게임 로직 컴포넌트를 우선한다.
                 */
                if (
                    /^cc\./i.test(
                        name
                    ) &&
                    !AWAKEN_SKILL_COMPONENT_HINT
                        .test(
                            name
                        )
                )
                    continue;


                const fields =
                    inspectAwakenComponent(
                        component
                    );


                if (
                    Object.keys(
                        fields
                    ).length ===
                    0
                )
                    continue;


                componentRows.push({
                    nodeName:
                        String(
                            node?.name ||
                            ''
                        ),

                    path,

                    component:
                        name,

                    fields
                });
            }


            visited += 1;


            if (
                visited % 100 ===
                0
            ) {

                await inspectionYield();
            }
        }


        const relatedButtons =
            (
                typeof listGameButtons ===
                    'function'
                    ? listGameButtons()
                    : []
            ).filter(
                row =>
                    /HeroAwakenSkillUpPop|Skillcontent1|HeroDetailAwaken/i
                        .test(
                            row?.path ||
                            ''
                        )
            );


        const currentStageText =
            baseSnapshot
                .currentStageText;

        const nextStageText =
            baseSnapshot
                .nextStageText;


        const extraEffects =
            baseSnapshot
                .extraEffects;

        const unlockTexts =
            baseSnapshot
                .unlockTexts;

        const comparisonTexts =
            baseSnapshot
                .comparisonTexts;


        const logicComponent =
            awakenSkillPopupComponent(
                popup
            );


        const skillMeta = {
            heroId:
                Number.isFinite(
                    Number(
                        logicComponent?._heroId
                    )
                )
                    ? Number(
                        logicComponent._heroId
                      )
                    : null,

            skillIndex:
                Number.isFinite(
                    Number(
                        logicComponent?._skillIndex
                    )
                )
                    ? Number(
                        logicComponent._skillIndex
                      )
                    : null,

            skillId:
                Number.isFinite(
                    Number(
                        logicComponent?._skillId
                    )
                )
                    ? Number(
                        logicComponent._skillId
                      )
                    : null,

            currentLevel:
                Number.isFinite(
                    Number(
                        logicComponent?._skillLevel
                    )
                )
                    ? Number(
                        logicComponent._skillLevel
                      )
                    : null,

            maxLevelPreview:
                !!logicComponent
                    ? !!logicComponent._maxLevelPreview
                    : null
        };


        const result = {
            ok: true,

            inspectedAt:
                new Date()
                    .toISOString(),

            title:
                baseSnapshot.title,

            skill:
                skillMeta,

            stage: {
                currentText:
                    currentStageText,

                current:
                    parseStageNumber(
                        currentStageText
                    ),

                nextText:
                    nextStageText,

                next:
                    parseStageNumber(
                        nextStageText
                    ),

                visibleCandidates:
                    baseSnapshot
                        .stageCandidates
            },

            cost: {
                need:
                    firstTextByNodeName(
                        popupTexts,
                        'upgradeOneNeedExpLab(红色色值#FF6C6C)'
                    ),

                owned:
                    firstTextByNodeName(
                        popupTexts,
                        'totalHaveExpLab'
                    )
            },

            /*
             * 현재 효과/다음 효과는 RichText가 여러 Label child로 분리될 수 있으므로
             * 원문 순서를 그대로 보존한다.
             */
            texts:
                popupTexts,

            comparisonTexts,

            unlockTexts,

            extraEffects,

            components:
                componentRows,

            relatedButtons,

            maxPreview: {
                available:
                    false,

                initiallyEnabled:
                    skillMeta
                        .maxLevelPreview,

                activated:
                    false,

                observedMaxStage:
                    null,

                restoreMode:
                    null,

                restoreAttempted:
                    false,

                popupClosedForRestore:
                    false,

                restored:
                    true,

                snapshot:
                    null,

                componentBefore:
                    logicComponent
                        ? inspectAwakenComponent(
                            logicComponent
                          )
                        : null,

                componentDuring:
                    null,

                componentAfter:
                    null
            },

            notes: [
                '게임 상태를 변경하는 승격/레벨업 동작은 실행하지 않음',
                'Sprite/Texture/Asset은 조사 대상에서 제외',
                '각성 스킬 최대 단계를 5로 가정하지 않음',
                '게임 내 최대 단계 미리보기 UI가 있으면 자동으로 읽고 원래 상태로 복원',
                '미리보기 토글 해제가 실패하면 각성 스킬 상세 팝업을 닫아 안전하게 복원',
                '승격(onSkillUpClick)은 절대 호출하지 않음',
                '스크랩 전 화면/팝업이 activeInHierarchy 상태이며 핵심 콘텐츠가 생성된 뒤 최소 안정 시간 동안 유지되는지 확인',
                'components의 config/data/info/effect/level/stage/id 계열 필드에서 단계별 원본 설정 후보를 찾기 위한 조사 결과'
            ]
        };


        /*
         * 게임이 제공하는 "최대 단계 미리보기"만 사용한다.
         * 실제 승격(onSkillUpClick)은 절대 호출하지 않는다.
         */
        if (
            options.includeMaxPreview !==
                false &&
            !isCancelled()
        ) {

            const previewRow =
                findAwakenMaxPreviewButtonRow();


            result.maxPreview.available =
                !!previewRow;


            if (
                previewRow
            ) {

                const initiallyEnabled =
                    !!(
                        logicComponent &&
                        logicComponent
                            ._maxLevelPreview
                    );


                result.maxPreview.initiallyEnabled =
                    initiallyEnabled;


                try {

                    if (
                        !initiallyEnabled
                    ) {

                        const previewResult =
                            await pressGameButton(
                                previewRow.id,
                                {
                                    waitMs:
                                        300
                                }
                            );


                        if (
                            previewResult.ok
                        ) {

                            result.maxPreview.activated =
                                true;
                        }


                        await inspectionYield();


                        await saleWaitForNode(
                            'HeroAwakenSkillUpPop',
                            {
                                timeout:
                                    options.previewVisibleTimeout ??
                                    1400,

                                /*
                                 * popup 노드는 그대로여도 내부 내용은 최대 단계
                                 * 미리보기로 바뀌므로 버튼 클릭 시점부터 다시 기다린다.
                                 */
                                minVisibleMs:
                                    options.screenVisibleStableMs ??
                                    SALE_VISIBLE_STABLE_MS
                            }
                        );
                    }


                    if (
                        !isCancelled()
                    ) {

                        const livePopup =
                            findActiveNodeByName(
                                'HeroAwakenSkillUpPop'
                            );


                        const liveComponent =
                            awakenSkillPopupComponent(
                                livePopup
                            );


                        if (
                            livePopup
                        ) {

                            result.maxPreview.snapshot =
                                awakenPopupSnapshot(
                                    livePopup
                                );


                            const stages =
                                result
                                    .maxPreview
                                    .snapshot
                                    ?.stageCandidates ||
                                [];


                            result.maxPreview.observedMaxStage =
                                stages.length
                                    ? Math.max(
                                        ...stages
                                      )
                                    : null;
                        }


                        result.maxPreview.componentDuring =
                            liveComponent
                                ? inspectAwakenComponent(
                                    liveComponent
                                  )
                                : null;
                    }

                } finally {

                    /*
                     * 조사 시작 전 미리보기 OFF였던 경우에만 복원을 시도한다.
                     *
                     * 1차: 같은 미리보기 버튼 재호출
                     * 2차: 여전히 preview=true이면 상세 팝업을 닫아서 상태 폐기
                     *
                     * 실제 승격/레벨업 데이터는 변경하지 않는다.
                     */
                    if (
                        !initiallyEnabled
                    ) {

                        result.maxPreview.restoreAttempted =
                            true;


                        let livePopup =
                            findActiveNodeByName(
                                'HeroAwakenSkillUpPop'
                            );

                        let liveComponent =
                            awakenSkillPopupComponent(
                                livePopup
                            );


                        if (
                            liveComponent &&
                            liveComponent
                                ._maxLevelPreview
                        ) {

                            const restoreRow =
                                findAwakenMaxPreviewButtonRow();


                            if (
                                restoreRow
                            ) {

                                await pressGameButton(
                                    restoreRow.id,
                                    {
                                        waitMs:
                                            350
                                    }
                                );

                                await inspectionYield();


                                livePopup =
                                    findActiveNodeByName(
                                        'HeroAwakenSkillUpPop'
                                    );

                                liveComponent =
                                    awakenSkillPopupComponent(
                                        livePopup
                                    );


                                if (
                                    !liveComponent ||
                                    !liveComponent
                                        ._maxLevelPreview
                                ) {

                                    result.maxPreview.restoreMode =
                                        'preview-toggle';
                                }
                            }
                        }


                        /*
                         * 일부 버전에서는 최대 미리보기 버튼이 토글 해제가 아니다.
                         * 이 경우 popup 자체를 닫으면 preview 상태가 안전하게 폐기된다.
                         */
                        if (
                            liveComponent &&
                            liveComponent
                                ._maxLevelPreview
                        ) {

                            const closeRow =
                                findAwakenSkillPopupCloseButtonRow();


                            if (
                                closeRow
                            ) {

                                const closeResult =
                                    await pressGameButton(
                                        closeRow.id,
                                        {
                                            waitMs:
                                                300
                                        }
                                    );


                                if (
                                    closeResult.ok
                                ) {

                                    result.maxPreview.popupClosedForRestore =
                                        true;

                                    result.maxPreview.restoreMode =
                                        'close-popup';
                                }


                                await inspectionYield();
                            }
                        }
                    }


                    const afterPopup =
                        findActiveNodeByName(
                            'HeroAwakenSkillUpPop'
                        );

                    const afterComponent =
                        awakenSkillPopupComponent(
                            afterPopup
                        );


                    result.maxPreview.componentAfter =
                        afterComponent
                            ? inspectAwakenComponent(
                                afterComponent
                              )
                            : null;


                    /*
                     * popup이 닫혔거나 preview flag가 원래 OFF로 돌아왔으면 복구 성공.
                     */
                    result.maxPreview.restored =
                        initiallyEnabled
                            ? true
                            : (
                                !afterPopup ||
                                !afterComponent ||
                                !afterComponent
                                    ._maxLevelPreview
                              );


                    if (
                        !result.maxPreview.restoreMode &&
                        result.maxPreview.restored
                    ) {

                        result.maxPreview.restoreMode =
                            afterPopup
                                ? 'already-restored'
                                : 'popup-closed';
                    }
                }
            }
        }


        window.TOPWAR_AWAKEN_SKILL_INSPECTION =
            result;


        console.log(
            '[TOPWAR_AWAKEN_SKILL_INSPECTION]',
            result
        );


        return result;
    }


